(window.GIM_TP=window.GIM_TP||{})["Bava Metzia.1"]={"from":208,"a":[[["מאי זרע אחר מאי חיטי לגבי שעורים כזרע אחר דמי או לא כל העולם כולו בשדפון ושלו בירקון אי נמי כל העולם כולו בירקון ושלו בשדפון מאי תיקו","אמר ליה זרעה חיטי ואזל הוא וזרעה שערי ואשתדוף רובא דבאגא ואשתדוף נמי הנך שערי דיליה מאי מי אמרינן דאמר ליה אילו זרעתה חיטי הוה נמי משתדפא או דלמא מצי אמר ליה אילו זרעתה חיטי הוה מקיים בי (איוב כב, כח) ותגזר אומר ויקם לך","מסתברא דאמר ליה אי זרעתה חיטי הוה מקיים בי ותגזר אומר ויקם לך ועל דרכיך נגה אור","נשתדפו כל שדותיו של מחכיר ואשתדוף נמי הא בהדייהו ולא אשתדוף רובא דבאגא מאי מי אמרינן כיון דלא אשתדוף רובא דבאגא לא מנכי ליה או דלמא כיון דאשתדוף כולהו ארעתיה מצי אמר ליה האי משום לתך דידך הוא דהא משתדפו כל שדותיך","מסתברא דאמר ליה אי משום לתאי דידי הוה משתייר לי פורתא כדכתיב (ירמיהו מב, ב) כי נשארנו מעט מהרבה","נשתדפו כל שדותיו של חוכר ואשתדוף רובא דבאגא ואשתדוף נמי הא בהדייהו מאי מי אמרינן כיון דאשתדוף רובא דבאגא מנכי ליה או דלמא כיון דאשתדוף כולהו ארעתיה מצי אמר ליה משום לתך דידך הוא דהא משתדפו כל שדותיך מסתברא דאמר ליה משום לתאך הוא","אמאי הכא נמי נימא ליה אי משום לתאי דידי הוא הוה משייר לי פורתא דהוה מקיים בי כי נשארנו מעט מהרבה משום דאמר ליה אי הוה חזית לאישתיורי לך מידי הוה משתייר לך מדנפשך","מיתיבי היתה שנת שדפון וירקון או שביעית או שהיו שנים כשני אליהו אינו עולה לו מן המנין","קתני שדפון וירקון דומיא דשנים כשני אליהו מה שני אליהו דלא הוי תבואה כלל אף הכא נמי דלא הוי תבואה כלל אבל דאיכא תבואה סלקא ליה ולא קאמרינן מכת מדינה היא","אמר רב נחמן בר יצחק שאני התם דאמר קרא (ויקרא כה, טו) במספר שני תבואות ימכר לך שנים שיש בהן תבואה בעולם","אמר ליה רב אשי לרב כהנא אלא מעתה שביעית תעלה לו מן המנין דהא איכא תבואה בחוצה לארץ אמר ליה שביעית אפקעתא דמלכא היא","אמר ליה מר זוטרא בריה דרב מרי לרבינא אלא מעתה שביעית לא תעלה לו מן הגירוע אלמה תנן נותן סלע ופונדיון לשנה אמר ליה שאני התם דחזיא למישטחא בה פירי","אמר שמואל לא שנו אלא שזרעה וצמחה ואכלה חגב אבל לא זרעה כלל לא דאמר ליה אילו זרעתה הוה מקיים בי (תהלים לז, יט) לא יבשו בעת רעה ובימי רעבון ישבעו","מתיב רב ששת רועה שהיה רועה והניח עדרו ובא לעיר ובא זאב וטרף ובא ארי ודרס אין אומרים אילו היה שם היה מציל אלא אומדין אותו אם יכול להציל חייב ואם לאו פטור ואמאי נימא ליה אי הוית התם הוה מקיים בי (שמואל א יז, לו) גם את הארי גם (את) הדוב הכה עבדך","משום דאמר ליה אי הוית חזית לאיתרחושי לך ניסא הוה איתרחיש לך ניסא כר' חנינא בן דוסא דמתיין עיזי דובי בקרנייהו ונימא ליה נהי דלניסא רבה לא הוה חזינא לניסא זוטא"],[[0,"מאי","מי אמרינן ארבע שדות שסביבותיה לא נשדפו או דלמא אמר ליה אילו היו זרועות תבואה אף הן נשדפו:"],[0,"זרע אחר מאי","אם תמצא לומר אספסתא לאו הפסקה היא משום דלאו בכלל גזירת פורענות התבואה הוא דאמר ליה אילו תבואה הואי איהו נמי אישתדוף זרע אחר מי הוי הפסקה:"],[1,"ותגזר אומר","מה שתבקש מן היוצר יעשה ואני לא בקשתי מן השמים בתחילת השנה שיצליחני בשעורים אלא בחטין:"],[3,"כל שדותיו","בכל מקום שהן:"],[3,"לתך","מזלך:"],[5,"כולהו ארעתיה","ואפי' ישנן בבקעה אחרת:"],[7,"היתה שנת שדפון","גבי מוכר בזמן שהיובל נוהג שאינו מותר לו לגאול פחות משתי שנים תנן לה בערכין (דף כט:):"],[7,"או שנים כשני אליהו","שלא ירדו גשמים:"],[7,"אינו עולה לו מן המנין","שתי שנים:"],[8,"הא איכא תבואה בדוכתא אחריתי","אע\"ג דההוא באגא אישתדוף אמרינן לתא דידיה (מזל דידיה) גרם וסלקינן ליה מגרע מדמים מה שמגיע לשנה אחת כאילו היו בה פירות:"],[9,"שיש בהן תבואה","בשום מקום בארץ:"],[10,"אפקעתא דמלכא","המלך ביטלו מלזורעה והרי היא כמו שאינה ולא קראה הכתוב לישראל שנת תבואה:"],[11,"אלא מעתה","אי כמאן דליתה:"],[11,"לא תעלה לו בגירוע","מקדיש שדהו ובא לפדותו שנתן לו הכתוב פדיון בתחילת היובל חמשים שקל כסף (ויקרא כ״ז:ג׳) ואם אחר היובל וחשב לו הכהן וגו' ונגרע מערכך (שם). שנים שעברו הוא מגרע מן החשבון כמה שמגיע להם ונותן כמה שמגיע לשנים הבאות וכיון דבשביעית כמאן דליתנהו למה הן נמנות לפחות את הפדיון דתנן נותן סלע ופונדיון לשנים הבאות שזהו החשבון המגיע לכל שנה כשאתה מחלק חמשים סלעים למ\"ט שנים נמצאו שביעיות מועילות לגרע הפדיון דאי מדלית שבע שמיטות ותחלק חמשים שקלים למ\"ב שנה מגיע לכל שנה קרוב לסלע ודינר:"],[11,"למשטח ביה פירי","הלכך סלקא ליה דגבי פדיון שדה אחוזה לא כתיב שני תבואות:"],[12,"לא שנו","אם מכת מדינה היא מנכה לו:"],[12,"אבל לא זרעה","ואשתדוף רובא דבאגא לא מנכה ליה:"],[14,"רבי חנינא בן דוסא","במסכת תענית:"]],[[6,"אי הוית חזית לאשתיורי לך הוי משתייר לך מדנפשך","גבי חוכר איכא למימר הכי דאפילו יפטור אותו המחכיר מליתן חכירותו הרי לא נשתייר כלום דבנשדף כל השדה איירי והא דקתני מנכה לו לישנא קלילא נקט אי נמי נשאר קצת בשדה לא חשיב שיור המעט הנמצא לענין שיהא קורא כי נשארנו מעט מהרבה כיון ששום שדה לא פלט מהפסד מרובה אבל מחכיר שגוף הקרקע שלו וממנו יש לו לקבל חכירותו כדאמר לעיל מארעאי קבעינא יכול המחכיר לומר לחוכר כי נשארנו מעט מהרבה והרי נשאר לי חכירותי מה שקצבתי עמך בכך וכך כורין:"],[10,"אלא מעתה שביעית תעלה כו'","תימה מאי אלא מעתה בלאו הכי תקשה אברייתא אמאי אין שביעית עולה מן המנין כיון דלא דמי לשני אליהו וי\"ל דשפיר קאמר אלא מעתה דאי אמרת דמכת מדינה לא חשיב אלא דומיא דשני אליהו אתי שפיר דהוה תלינן טעמא במה שזו השדה אינה ראויה לתבואה לא מיקרי שני תבואות והיינו כי ליכא תבואה בעולם כגון שני אליהו אבל יש תבואה בעולם חשיב שדה זו ראויה לתבואה אף על גב דאישתדוף רובא דבאגא אבל שביעית ודאי אף על גב דאיכא תבואה בחו\"ל שדה זו אינה ראויה לתבואה כיון שהיא בארץ אבל השתא דאמר כי אישדוף רובא דבאגא הוה מכת מדינה ולא חשיבא שדה זו ראויה לתבואה ואפי' הכי גזירת הכתוב הוא כיון דאיכא תבואה בעולם עולה לו מן המנין א\"כ אפי' שביעית נמי ומשני שביעית אפקעתא דמלכא הוא ואי אפשר להיות תבואה בארץ בהיתר כלל ולהכי לא מקרי שנת תבואה אבל שנת שדפון דאע\"ג דהוי מכת מדינה אי אשתדוף רובא דבאגא חשיבא אפשר להיות בה תבואה כיון שיש בחו\"ל בשום מקום בעולם כי באפשר להיות בה תבואה מיקרי שנת תבואה ובשנים כבשני אליהו חשב כלא אפשר להיות בה תבואה כיון דבשום מקום ליכא:"],[13,"מתיב רב ששת רועה שהיה רועה עדרו כו'","תימה אמאי לא פריך ממתניתין דהפועלים (לעיל בבא מציעא דף צג:) דתנן הארי והדוב הרי זה אונס ואמאי נימא אילו נלחם בהם הוה מקיים ביה גם את הארי וי\"ל דהתם כיון שהיה שם ולא בא לו רוח גבורה אין יכול לומר דהוה מקיים ביה אבל הכא שלא היה שם דלמא אי הוה התם היה בו רוח וגבורה ודעת להלחם והוה מקיים ביה גם את הארי כו':"],[14,"לניסא זוטא מיהא חזיא קשיא","תימה מאי קשיא הא אמרן לעיל דכי אמר ליה זרעה חטין וזרעה שערי ואשתדוף דמצי אמר ליה אי זרעתה חטין הוה מקיים בי ותגזר אומר ויקם לך וכ\"ש כשלא זרעה כלל דליכא הוכחה שהיה ראוי להשתדף וי\"ל דשמואל מיירי כגון שאמר ליה זרע כל מה שתרצה דהשתא לא מצי למימר הוה מקיים בי ותגזר אומר ויקם לך דבסתמא לא היה מקבל הקדוש ברוך הוא תפלתו של זה שיצליח כל מה שיזרע אם לא שיעשה לו נס ולא קאמר לעיל הוה מקויים בי ותגזר אומר אלא לפי שמתפלל על מין אחד של חטין:"]]],[["חזינא קשיא","תני חדא פעם ראשונה ושניה זורעה ושלישית אינו זורעה ותניא אידך שלישית זורעה רביעית אינו זורעה לא קשיא הא כרבי הא כרשב\"ג","הא כרבי דאמר בתרי זימני הוי חזקה הא כרשב\"ג דאמר בתלת זימני הוי חזקה","אמר ריש לקיש לא שנו אלא שזרעה וצמחה ואכלה חגב אבל זרעה ולא צמחה מצי אמר ליה בעל הקרקע כל ימי זרע זרעא לה ואזיל ועד אימת אמר רב פפא עד דאתו אריסי מדברא וקיימא כימה ארישייהו","מיתיבי רשב\"ג משום ר\"מ אומר וכן היה רבי שמעון בן מנסיא אומר כדבריו חצי תשרי מרחשון וחצי כסליו זרע","חצי כסליו טבת וחצי שבט חורף חצי שבט אדר וחצי ניסן קור חצי ניסן אייר וחצי סיון קציר חצי סיון תמוז וחצי אב קיץ חצי אב אלול וחצי תשרי חום","רבי יהודה מונה מתשרי ר\"ש מונה ממרחשון","מאן מיקל בכולהו ר' שמעון וכולי האי לא קאמר לא קשיא הא דקבלה מיניה בחרפי הא דקבלה מיניה באפלי:","רבי יהודה אומר אם קבלה ממנו במעות: ההוא גברא דקביל ארעא למיזרעה בהו תומי אגודא דנהר מלכא סבא בזוזי איסתכר נהר מלכא סבא אתא לקמיה דרבא אמר ליה נהר מלכא סבא לא עביד דמיסכר מכת מדינה היא זיל נכי ליה","אמרו ליה רבנן לרבא הא אנן תנן ר' יהודה אומר אם קבלה הימנו במעות בין כך ובין כך אינו מנכה לו מן חכורו אמר להו לית דחש לה לדר' יהודה:","\u0001מתני׳\u0002 המקבל שדה מחבירו בעשרה כור חטים לשנה ולקתה נותן לו מתוכה היו חטיה יפות לא יאמר לו הריני לוקח מן השוק אלא נותן לו מתוכה:","\u0001גמ׳\u0002 ההוא גברא דקביל ארעא לאספסתא בכורי דשערי עבדא אספסתא וחרשה וזרעה שערי ולקו הני שערי שלחה רב חביבא מסורא דפרת לקמיה דרבינא כי האי גונא מאי כי לקתה נותן לו מתוכה דמי או לא","אמר ליה מי דמי התם לא עבדא ארעא שליחותא דמרה הכא עבדא ארעא שליחותא דמרה","ההוא גברא דקבל פרדס מחבריה בעשר דני חמרא תקיף ההוא חמרא סבר רב כהנא למימר היינו מתני' לקתה נותן לו מתוכה אמר ליה רב אשי מי דמי התם לא עבדא ארעא שליחותא הכא עבדא ארעא שליחותא","ומודה רב אשי בעינבי דכדום ובשדה שלקתה בעומריה:","\u0001מתני׳\u0002 המקבל שדה מחבירו לזרעה שעורים לא יזרענה חטים חטים יזרענה שעורים רשב\"ג אוסר תבואה לא יזרענה קטנית קטנית יזרענה תבואה ורשב\"ג אוסר:","\u0001גמ׳\u0002 א\"ר חסדא מ\"ט דרשב\"ג דכתיב (צפניה ג, יג) שארית ישראל לא יעשו עולה ולא ידברו כזב ולא ימצא בפיהם לשון תרמית","מיתיבי מגבת פורים לפורים ואין מדקדקין בדבר ואין העני רשאי ליקח מהן רצועה לסנדלו אא\"כ התנה במעמד אנשי העיר דברי רבי יעקב שאמר משום ר\"מ רשב\"ג"],[[1,"פעם ראשונה ושניה","זרעה ואכלה חגב או נשדפה חוזר וזורעה שנית ואם אינו זורעה אינו מנכה לו אפילו היא מכת מדינה:"],[1,"פלוגתא דרבי ורשב\"ג","גבי נשואה לראשון ומת לשני ומת במסכת יבמות:"],[3,"מצי אמר ליה בעל הקרקע כל יומי זרע זרע ואזיל","כלומר כל זמן הזריעה חזור וזרעה שמא לא הגיע זמן:"],[3,"ועד אימת","הוי משך זמן הזריעה:"],[3,"עד זמן דכי אתא אריסא מדברא","ונכנס לבית בזמן שהן רגילין ליכנס דהיינו לאחר תשע שעות ביום קרוב לסוף העשירית קיימא כימה שהוא זנב טלה להדי רישייהו בראש כל אדם דהיינו באמצע הרקיע שנראה לכל אדם כאילו הוא על ראשו והן הן ימי אדר לפי שבגלגל קבועין בו שנים עשר מזלות וזהו סידרן טש\"ת סא\"ב מע\"ק גד\"ד ולעולם ששה עולין וששה שוקעין בניסן לעולם בתחילת עלות השחר טלה מתחיל לעלות ומאזנים שוקע ושתי שעות המזל שוהה לעלות לאחר שתי שעות העולה גמר עלייתו והשוקע גמר שיקועו נמצא הששה עולים בשתים עשרה שעות ביום וששה בלילה כל ימי ניסן ראש טלה מתחיל לעלות ובאייר שור ובסיון תאומים וכן הסדר נמצא באדר מזל דגים מתחיל לעלות בבוקר סוף שתי שעות טלה מתחיל לעלות ולסוף ארבע גמר עלייתו ושור עולה לסוף שש גמר שור עלייתו ומתחיל תאומים לסוף שמנה גמר תאומים ומתחיל סרטן ונמצא ראש טלה באמצע שהרי עברו שש שעות משהתחיל ובשש שעות ראשו מגיע לאמצע שהרי מתחילת עליית המזל עד תחילת שיקועו שנים עשר שעות נמצא שמשעה שמתחיל לעלות עד שש שעות מגיע לאמצע הרקיע ולסוף שמנה שעות משעלה הוי זנבו באמצע הרקיע נמצא באדר זנב טלה בסוף שעה עשירית באמצע הרקיע הוא והכי אמרינן במסכת ברכות בפרק הרואה (ברכות דף נח:) שכימה בזנב טלה הוא:"],[4,"חצי תשרי וכו'","שש תקופות שהובטחו לנח ובניו קמפרש:"],[5,"קציר","כנגד זרע זה בתחילת גשמים זה בתחילת החמה וקיץ כנגד חורף וחורף הוא חוזקו וחורפו של סתיו וימי צינה לשון (איוב כ״ט:ד׳) כאשר הייתי בימי חרפי חוזקי ועיקרי קיץ הוא חוזקו של יבש ועל שמייבשין באותו פרק תמרים ותאנים לקציעות והן נקראין קיץ כדכתיב (שמואל ב ט״ז:ב׳) הלחם והקיץ לאכול הנערים וגו' קור הוא סופו של סתו וכן חום סופו של שמש וכן כל אחד שני חדשים י\"ב חדשים לששה עתים:"],[5,"מתחילת תשרי","מתחיל למנות שני חדשים בכל עת:"],[7,"מאן קמיקל","במשך ימי הזרע למי שבא לאחר זריעותיו:"],[7,"רבי שמעון","שמנה מן מרחשון ואומר מרחשון וכסלו זרע:"],[7,"בחרפי","חטין ושיפון הנזרעין בתחילת החורף:"],[7,"באפלי","שעורין וקטנית הנזרעין באדר:"],[8,"איסתכר","לשון (בראשית ח׳:ב׳) ויסכרו מעינות תהום נסתמה הליכתו שעכבוהו העליונים העליונים הסיבוהו דרך אחרת ואין ירק מצליח אלא בקרקע נרבצת בארץ לחה:"],[8,"מכת מדינה","לא עליו לבדו עברה ולאסוקי אדעתיה נמי לא הוה ליה דלא הוי עביד למיסתכר:"],[10,"מתני' ולקתה","שהיו חטין שדופות וגם כחושות וזו בחכירות הוצרכה לשנותה ולא בקבלנות דאי בקבלנות פשיטא דכל אחד זוכה ומתחייב בחלקו:"],[11,"גמ' עבדא אספסתא","היא נקצרת לשלשים יום כדאמר בריש ח\"ה (ב\"ב כח:) וחזר וזרעה שעורים:"],[12,"עבדא ארעא שליחותא","בעליה לא חכרה אלא לאספסתא ואילו זרע לה אספסתא ואזיל היה מצליח והוא פסק עמו ליקח שעורין מן השוק:"],[13,"פרדיסא","כרם:"],[13,"תקיף","החמיץ:"],[13,"עבדא ארעא שליחותא","הענבים לא לקו אלא משנעשה יין בחביותיו בביתו לקה ואמר בבבא בתרא (דף צו:) חמרא אכתפא דגברא שוור זה קונהו מזה טוב ומזלו גורם להחמיץ:"],[14,"ענבי דכדום","ענבים שהתליעו:"],[14,"בעומריה","בעודן שטוחות ליבש בימות הקיץ דכל [זמן] זה עודן צריכין לקרקע וכך הענבים שהתליעו בין בציר לדריכה וכגון דלא איחרו יותר מן המנהג:"],[15,"מתני' המקבל שדה לזרעה שעורין","ובחכירות כך וכך חטין או שעורין או מעות:"],[15,"לא יזרענה חטין","שהחטין מכחישות את הקרקע יותר מן השעורין והא לא מיתוקמא אלא בחכרנות דאי בקבלנות הא אמרינן תיכחוש ארעא ולא ליכחוש מרה והרי הוא נהנה בשינוי של זה:"],[15,"ורבן שמעון בן גמליאל אוסר","וטעמא מפרש בגמרא:"],[15,"תבואה לא יזרענה קטנית","שהקטנית מכחשת הקרקע יותר מן התבואה:"]],[[3,"וקיימא כימה להדי רישא","פי' בקונט' דכימה זנב טלה כדאמר בברכות (דף נח:) ולא דק אלא אמרינן התם דעש זנב טלה אלא שכימה סמוכה לה ואומר הב לי בניי ומה שפי' בקונטרס דביום ראשון של אדר בסוף שעה עשירית קיימא כימה באמצע הרקיע קשה דפועלים לא אתו מדברא עד צאת הכוכבים כדפי' בריש הפועלים (לעיל בבא מציעא דף פג:) ותו דבסוף י' שעות הן עוד היום גדול ואין נראין הכוכבים ומשמע שבא ליתן סימן לאריסין להכיר שעה שיבאו מן השדה וזה דוחק לומר דה\"ק כשיחשיך לילה אז רואין למפרע שבשעת הליכתן היתה כימה להדי רישייהו ונראה לפרש דאתו אריסי מדברא בתחילת הלילה וקיימא כימה להדי רישייהו היינו בתחילת שבט ואז כלה זמן הזרע והא דאמר בפ' כל הקרבנות (מנחות דף פה. ושם ד\"ה וזורע) שהיו זורעים קודם הפסח ע' יום וזהו חמשה יומי בתוך שבט התם שקרקע חשובה היא שזורעין בה לצורך העומר נמשך שם ימי הזרע יותר א\"נ דבתחילת שבט של חמה הוא דקיימא כימה להדי רישייהו ואין תחילת של שבט של חמה מתחיל ברוב שנים יותר מע' יום לפני הפסח.:"],[11,"שדא ביה אספסתא ועבדא","לא הוה צריך למימר דשדא ביה אספסתא דבלאו הכי מצי למימר אילו הוה זרע אספסתא הוה עבדא אלא מעשה הוה הכי:"]]],[["מיקל","אמר אביי טעמא דרבן שמעון כדמר דאמר מר האי מאן דניחא ליה דתתבור ארעיה ליזרעה שתא חטי ושתא שערי שתא שתי ושתא ערב","ולא אמרן אלא דלא כריב ותני אבל כריב ותני לית לן בה:","תבואה לא יזרענה קטנית [וכו']: מתני ליה רב יהודה לרבין תבואה יזרענה קטנית א\"ל והא אנן תנן תבואה לא יזרענה קטנית א\"ל לא קשיא הא לן והא להו","א\"ל רב יהודה לרבין בר ר\"נ רבין אחי הני תחלי דבי כיתנא אין בהן משום גזל עומדות על גבולין יש בהן משום גזל","ואם הוקשו לזרע אפילו דבי כיתנא נמי יש בהם משום גזל מ\"ט מאי דאפסיד אפסיד","א\"ל רב יהודה לרבין בר ר\"נ רבין אחי הני דילי דילך ודילך דילי נהוג בני מצרא אילן הנוטה לכאן לכאן והנוטה לכאן","לכאן דאיתמר אילן העומד על המיצר אמר רב הנוטה לכאן לכאן והנוטה לכאן לכאן ושמואל אמר חולקין","מיתיבי אילן העומד על המיצר יחלוקו תיובתא דרב תרגמא שמואל אליבא דרב בממלא כל המיצר כולו","אי הכי מאי למימרא לא צריכא דתלי טוניה לחד גיסא ואכתי מאי למימרא מהו דתימא דא\"ל פלוג הכי קמ\"ל דאמר ליה מאי חזית דפלגת הכי פלוג הכי","א\"ל רב יהודה לרבין בר ר\"נ רבין אחי לא תזבין ארעא דסמיכא למתא דא\"ר אבהו אמר רב הונא אמר רב אסור לו לאדם שיעמוד על שדה חבירו בשעה שעומדת בקמותיה","איני והא אשכחינהו רבי אבא לתלמידיה דרב אמר להו מאי אמר רב בהני קראי (דברים כח, ג) ברוך אתה בעיר וברוך אתה בשדה ברוך אתה בבואך וברוך אתה בצאתך","ואמרו ליה הכי אמר רב ברוך אתה בעיר שיהא ביתך סמוך לבהכ\"נ ברוך אתה בשדה שיהו נכסיך קרובים לעיר ברוך אתה בבואך שלא תמצא אשתך ספק נדה בשעת ביאתך מן הדרך ברוך אתה בצאתך שיהו צאצאי מעיך כמותך","ואמר להו ר' יוחנן לא אמר הכי אלא ברוך אתה בעיר שיהא בית הכסא סמוך לשולחנך אבל בהכ\"נ לא ורבי יוחנן לטעמיה דאמר שכר פסיעות יש","ברוך אתה בשדה שיהו נכסיך משולשין שליש בתבואה שליש בזיתים ושליש בגפנים ברוך אתה בבואך וברוך אתה בצאתך שתהא יציאתך מן העולם כביאתך לעולם מה ביאתך לעולם בלא חטא אף יציאתך מן העולם בלא חטא"],[[0,"גמ' מיקל","אע\"ג דמשני לא סבר דמקפיד איניש מידי דלא חסר בה:"],[1,"דאמר מר","רבה בר נחמני רביה דאביי דרבה גידלו בביתו:"],[1,"דתתבור","שתעשה בורה שלא יצמחו זרעוניה:"],[1,"ליזרע [שתא] חטין וכו'","ה\"נ פסק עמו חטין שמא הוא זרעה חטין בשנה שעברה ואם יזרענה זה שעורין נמצא זה מקלקלה:"],[2,"דלא כריב ותני","חרשה לאחר קצירה ושינה בשעת הזרע:"],[3,"מתני לה רב יהודה לרבין","במתני' תבואה יזרענה קטנית:"],[3,"הא לן והא להו","מתני' בא\"י קאי שהיא מקום הרים ואיכא למיחש לכחשא דארעא אנן השתא בבבל קיימינן שהיא מצולה וטבועה בבצעי המים וליכא למיחש לכחשא דארעא הלכך משנה בכל מקום שירצה מקטנית לתבואה ומתבואה לקטנית ורבי שמעון אוסר כדאמרן:"],[4,"תחלי דבי כיתנא","שחלים שקורין כרישי\"ן הגדילים בין הפשתן:"],[4,"אין בהם משום גזל","לכל הבא ועוקרן לפי שהוא משביח את הבעלים שמפסידים פשתן יותר על דמיה:"],[4,"ואם עומדת על גבול","הערוגה שאין עומדים בתוכה:"],[5,"יש בהם משום גזל","דלא מפסדי:"],[5,"הוקשו לזרע","אותן שחלים שעמדו בפשתן ימים רבים עד שנגמר גידוליהן שוב אין עקירתן מועלת לפשתן ויש בהם משום גזל:"],[6,"דילי דילך דילך דילי","יש באילנותי שהפירות שלך ובאילנותיך שהפירות שלי ששדותינו זו לזו סמוכות והמצרים גבוהים ואילנות נטועין בהם יש מהם נטועין בשלי ששרשיהן כפפו ונטו כולן לתוך שדך ויונקים משלך ויש בשלך שנוטין לתוך שלי ויונקים מארצי:"],[6,"ונהגו בני מצרא וכו' נוטה לכאן ולכאן","נוטין שרשין לשדה זו הפירות שלו:"],[8,"בממלא כל המצר","שנוטין שרשין לכאן ולכאן:"],[9,"דתלי טוניה","משא פירותיו וענפיו נוטה לצד האחד:"],[9,"פלוג הכי","טול אתה חציו שאצלך ואני חציו שאצלי:"],[9,"פלוג הכי","לעבר רוחב השדה חלוק האילן אם עומדת השדה מזרח ומערב יחלוק אותו האילן צפון ודרום:"],[10,"לא תזבון","לא תקנה שדה הסמוכה לעיר שעין בני האדם שולטת בה תמיד:"],[10,"אסור לאדם כו'","שלא יפסידנה בעין הרע:"],[12,"קרובין לעיר","שלא יהא טורח להכניס פירות:"],[12,"ספק נדה","וכ\"ש ודאי:"],[13,"אמר להו","רב אבא רבי יוחנן לא אמר הכי:"],[13,"סמוך לשולחנך","כלומר סמוך לביתך שלא תצטרך להרחיק בשדות והאי דנקט שולחנך שתוכל לבדוק עצמך לפני אכילה ולאחר אכילה כדאמר בשבת (דף מא.) כדתניא הנצרך לנקביו ואוכל דומה לתנור שהסיקוהו על גבי אפרו ואחר אכילה שהמאכל דוחק ומוציא את המעוכל ואם יהא צריך להרחיק פעמים שהעמוד חוזר ובא לידי הדרוקן אבל בית הכנסת סמוך לביתו לר' יוחנן לאו מעליותא היא:"],[13,"ר' יוחנן לטעמיה","דאמר במסכת סוטה (דף כב.) שכר פסיעות יש דאמר למדנו יראת חטא מבתולה וקיבול שכר מאלמנה שאמרה לו ולא שכר פסיעות יש אם יש בית הכנסת בשכונתי ואני באה לבית מדרשך להתפלל:"],[14,"משולשין","שיש שנה שלוקה בגפנים ובזיתים ואין לוקה בתבואה ויש שנה שלוקה בזו ולא בזו ותהי לו פליטה:"]],[[1,"האי מאן דבעי דתתבור [ארעיה]","פי' בקונט' שתקלקל שדה וקשה דאדרבה כך הוא רגילות של עובדי אדמה שזורעים שנה חטין ושנה שעורין וכשזורעין אותה ב' שנים חטין רצופין או שעורין מתקלקלת וכן נמי משמע בשילהי חזקת הבתים (ב\"ב דף נז:) גבי אחד אמר אכלה חטין ואחד אמר אכלה שעורין כדפי' רבינו שמואל התם לכך י\"ל האי מאן דבעי שתהא שדהו חשובה כאילו הניחה שנה אחת בורה כי כן דרך לזורעה שנה ולהובירה שנה כדי שתחזור לכחה ממה שהוכחשה ליזרע שתא חטין ושתא שעורים ולכך אסר רשב\"ג כשאמר לזרעה חטין שלא יזרע שעורים כי שמא אשתקד זרעה שעורים ואי כריב ותני לית לן בה שם לא יאסור רשב\"ג:"],[4,"הני תחלי דבי כיתנא אין בהם משום גזל","אע\"ג שהתנה יהושע שיהו מלקטין עשבים בכל מקום כדאמר בסוף פ' מרובה (ב\"ק דף פא.) התם מיירי בעשבים שאין ראוים לאדם אלא לבהמה וכן משמע מדלא נקט ירקות אבל תחלי שהן מאכל אדם אסור אא\"כ הוא שדה פשתן:"],[7,"אילן העומד על המיצר","פי' הקונטרס אינו מיושב שפירש אילן שנטוע בקרקע סמוך למיצר והשרשים נוטים בשל חבירו אלא נראה לפרש שהאילן עומד ממש על המיצר שהוא של שניהם ואין השרשים מתפשטין לקרקעו של זה יותר משל זה אך הענפים נוטין יותר לשל אחד מהם רב אמר הנוטה לכאן לכאן כיון שהשרשים שוים בשל זה כמו בשל זה אזלינן בתר הענפים מה שיש מן הענפים כנגד המיצר חולקים והשאר לרשות שנוטין הוי הכל שלו ושמואל אמר חולקין אזלינן בתר השרשים שהם שוים כמו כן יהיו שוים בענפים אבל אי נטוע כולו ברשות אחד והענפים נוטים ברשות חבירו בזה אמר ר' יוחנן בס\"פ לא יחפור (ב\"ב דף כז: ושם ד\"ה ואחד) מביא וקורא שעל מנת כן הנחיל יהושע את הארץ שכל הענפים יהא לבעל השרשים ובהא מודו נמי רב ושמואל דשמעתין ופריך אילן העומד על המיצר חולקים ומשני בממלא כל המיצר כמו שהשרשים הן כולן על המיצר כך הם הענפים ודתלי טעוניה לחד גיסא דקאמר לא שהענפים עוברים המיצר אלא שיש פירות לצד אחד יותר מלצד חבירו מהו דתימא ניפלוג לאורכו של מיצר קמ\"ל דחולקין לרוחבו של מיצר ושילהי הבית והעלייה (לקמן בבא מציעא דף קיח:) דתנן שתי גינות זו למעלה מזו וירק בינתים השרשים לכ\"ע הם של עליון לפי שהם יונקים מגינתו אבל הנוף שהוא באויר התחתון לר' יהודה הוא של תחתון ולר\"מ הוי לשל עליון דאמר שדי נופו בתר עיקרו והתם פסיק כר\"ש דאמר כל שיכול עליון לפשוט ידו וליטול הרי אלו שלו והיינו כר\"מ והשאר מסתמא הפקיר לתחתון ונראה דאפי' לרב דלית ליה הכא שדי נופו בתר עיקרו סובר שפיר כר\"מ דכיון דהתם כל השרשים כולן בשל עליון דין הוא למימר שדי נופו בתר עיקרו כדאמר נמי רבי יוחנן בשילהי לא יחפור ושמואל דאמר הכא חולקין יכול לסבור התם כרבי יהודה דלא אמר שדי נופו בתר עיקרו משום דרגילות למלאות גינתו עפר ולהשוותו אל גינת חבירו ועוד דאין כלל מן הנוף ברשות העליון אלא מיד שנראה חוץ לארץ הוא ברשות התחתון אבל בשמעתין רוב הנוף על המיצר רק מעט מן הענפים נוטים לכאן ולכאן חוץ לרוחב המיצר:"]]],[["לא קשיא הא דמהדר ליה שורא ורתקא הא דלא מהדר ליה שורא ורתקא","(דברים ז, טו) והסיר ה' ממך כל חולי אמר רב זו עין רב לטעמיה דרב סליק לבי קברי עבד מאי דעבד אמר תשעין ותשעה בעין רעה ואחד בדרך ארץ","ושמואל אמר זה הרוח שמואל לטעמיה דאמר שמואל הכל ברוח ולשמואל הא איכא הרוגי מלכות הנך נמי אי לאו זיקא עבדי להו סמא וחיי","ר' חנינא אמר זו צינה דא\"ר חנינא הכל בידי שמים חוץ מצנים פחים שנאמר (משלי כב, ה) צנים פחים בדרך עקש שומר נפשו ירחק מהם","ר' יוסי בר חנינא אמר זו צואה דאמר מר צואת החוטם וצואת האוזן רובן קשה ומיעוטן יפה","ר' אלעזר אמר זו מרה תניא נמי הכי מחלה זו מרה ולמה נקרא שמה מחלה שהיא מחלה כל גופו של אדם דבר אחר מחלה ששמונים ושלשה חלאים תלוין במרה וכולן פת שחרית במלח וקיתון של מים מבטלתן","ת\"ר י\"ג דברים נאמרו בפת שחרית מצלת מן החמה ומן הצנה ומן הזיקין ומן המזיקין ומחכימת פתי וזוכה בדין ללמוד תורה וללמד ודבריו נשמעין ותלמודו מתקיים בידו","ואין בשרו מעלה הבל ונזקק לאשתו ואינו מתאוה לאשה אחרת והורגת כינה שבבני מעים וי\"א אף מוציא את הקנאה ומכניס את האהבה","א\"ל רבה לרבא בר מרי מנא הא מילתא דאמרי אינשי שיתין רהיטי רהוט ולא מטו לגברא דמצפרא כרך ואמרו רבנן השכם ואכול בקיץ מפני החמה ובחורף מפני הצינה","א\"ל דכתיב (ישעיהו מט, י) לא ירעבו ולא יצמאו ולא יכם שרב ושמש לא יכם שרב ושמש כיון דלא ירעבו ולא יצמאו","א\"ל את אמרת לי מהתם ואנא אמינא לך מהכא (שמות כג, כה) ועבדתם את ה' אלהיכם וברך את לחמך ואת מימיך ועבדתם את ה' אלהיכם זו קריאת שמע ותפלה וברך את לחמך ואת מימיך זו פת במלח וקיתון של מים מכאן ואילך והסירותי מחלה מקרבך","א\"ל רב יהודה לרב אדא משוחאה לא תזלזל במישחתא דכל פורתא ופורתא חזי לכורכמא רישקא א\"ל רב יהודה לרב אדא משוחאה ד' אמות דאניגרא זלזל בהו דאנהרא לא תמשחנהו כלל","רב יהודה לטעמיה דאמר רב יהודה ארבע אמות דאניגרא לבני אניגרא דאנהרא דכולי עלמא","מכריז רבי אמי מלא כתפי נגדי בתרי עברי נהרא קוצו רב נתן בר הושעיא קץ שיתסר אמתא אתו עליה בני משרוניא דפנוהו הוא סבר כרשות הרבים ולא היא התם בעינן כולי האי הכא משום אמתוחי אשליהן הוא כמלא כתפי נגדי סגי","רבה בר רב הונא הוה ליה ההוא אבא אגודא דנהרא אמרו ליה ניקוץ מר אמר להו קוצו עילאי ותתאי והדר ניקוץ אנא היכי עביד הכי והכתיב (צפניה ב, א) התקוששו וקשו ואמר ריש לקיש קשוט עצמך ואחר כך קשוט אחרים","התם אבא דבי פרזק רופילא הוה ואמר אי קייצו קייצנא ואי לא קייצו אמאי איקוץ דאי ממתחי להו אשלייהו מסתגי להו"],[[0,"לא קשיא","דרב אדרב:"],[0,"שורא וריתקא","חומה ורתוקת גדר של נצרים כמו (איכה ב) חיל וחומה:"],[1,"כל חלי","דבר שכל החלאים תלוין בו וזו העין עין רעה:"],[1,"עבד מה דעבד","יודע היה ללחוש על הקברות ולהבין על כל קבר וקבר באיזו מיתה מת אם מת בזמנו אם בעין רעה:"],[2,"הכל ברוח","כל החלאים ותוצאות מיתה על נשיבת הרוח באין הכל לפי השעה והאדם יש לך אדם שרוח פלוני קשה לו ובשעה פלוני:"],[2,"והאיכא הרוגי מלכות","הרוגי חרב:"],[2,"אי לאו זיקא","שנכנס במכה:"],[2,"עבדי סמא וחיי","סם המחבר בשר חתוכה ומן העשבים הוא כדאמר בהמוכר את הספינה (בבא בתרא עד:):"],[3,"צינים פחים","קור הנופח ולאו היינו רוח דקאמר שמואל דשמואל זיקא בלא צינה נמי מזקת:"],[5,"זו מרה","שהמרירה שבה גדולה ונובעת ומתפשטת בגידין ובעצמות:"],[5,"וכולן פת במלח מבטלתן","כדיליף לקמן מקראי:"],[5,"וקיתון של מים","למי שאין לו יין:"],[6,"וזיקין","היינו רוח דאמר שמואל:"],[6,"מחכימת פתי","שדעתו מיושבת עליו לפי שאינו מצטער בעינוי:"],[6,"וזוכה בדין","אם יש לו דין עם חבירו דעתו מיושבת ליישב דבריו בבית דין להטעים:"],[6,"ללמוד וללמד","מחמת ישוב הדעת:"],[6,"ודבריו נשמעין","לבריות שיש לו לב להטעימן:"],[7,"הבל","זיעה וזוהם:"],[7,"נזקק לאשתו","אם בעל הרהורים הוא ומתוך שלבו טוב בבקר שאכל קצת תובע לאשתו ובצאתו לשוק ורואה נשים אינו מתאוה להן:"],[7,"כינה שבבני מעיין","תולעים:"],[7,"מוציא את הקנאה ואת התגר","שכשאין לבו טוב עליו הוא נוח לכעוס:"],[8,"ואמרו רבנן השכם ואכול","בערבי פסחים (קיב א) בדברים שצוה רבי לבניו:"],[11,"משוחאה","מודד קרקעות היה בשכר לקונים ולמוכרים ולאחין ולשותפין הבאין לחלוק:"],[11,"כורכמא רישקא","כרכום של גן שקורין קרוג אודמינל\"ט והוא משובח שבכורכמין:"],[11,"ארבע אמות דאניגרא","אמת המים שהמשיכוה מן הנהר הגדול אל השדות על פני הבקעה כולה ומניחין בעלי כל שדה ושדה מלזרוע את אגפיה רוחב ארבע אמות. שלא תתקלקל שפתה ומודדין אותם כולם ביחד ומציינים אותם שלא יחרשו מן הסימן ולחוץ:"],[11,"זלזל בהן","אל תדקדק בהן להרחיבן:"],[11,"לא תמשחנהו כלל","אלא באומד הדעת תניחנו כדי שיהו ניכרים לעינים שהן שלימות ורחבות:"],[12,"לבני אניגרא","אינו מזיק אלא יחידים ויש בידן למחול:"],[12,"לכ\"ע","ומאן מחיל:"],[13,"מלי כתפי נגדי בתרי עברי נהרא קוצו","המוצא יער או אילנות נטועין על שפת הנהר יקוץ ברוחב מלא כתף מושכי חבל הספינה והן מטין עצמן באלכסון והולכין כשהן משופעין לצד היבשה שלא תמשכם הספינה למים וכל כמות הצריך להלוכם דינם לקוץ ובשני עברי הנהר שפעמים שהילוכן מכאן ופעמים שהילוכן מכאן:"],[13,"קץ שיתסר אמתא","כרוחב דרך רה\"ר כדתנן בבבא בתרא (דף צט:) דרך רה\"ר שש עשרה אמה:"],[13,"בני משרוניא","שם העיר והיער היה שלהן:"],[13,"דפנוהו","הלקוהו:"],[13,"אשליהן","חבלים שלהן:"],[14,"אבא","יער:"],[14,"ניקייצו עילאי ותתאי","מי שיש להן יער על הנהר אצלי למעלה הימנו ולמטה הימנו הילוך דרך המים:"],[15,"התם דבי פרזק רופילא הוה","אותן שלמטה ושלמעלה לא של ישראל היה שיכול לקצוץ אותו יער של בית פרזק פחת פרסיים היה וידוע הוא שלא יקוצו ומה תועיל קציצה שלי:"],[15,"אי ממתחי אשלייהו מסתגי להו","אם יוכלו למתוח חבלם ולבא ממסע למסע או מכפר לכפר לילך ממטה למעלה ילכו:"]],[[1,"תשעין וט' מתו בעין הרע ואחד בדרך ארץ","וא\"ת א\"כ בני יוסף שלא שלטה בהן עין הרע. היה להן לחיות הרבה מכל השבטים וי\"ל שמתו בדרך ארץ יותר מאחרים כשהקב\"ה היה רוצה להמיתן היה שולח להם חלאים אחרים:"],[3,"צנים","קור כדמוכח הכא פחים חום כדמוכח בריש מסכ' ע\"ז (דף ג: ושם ד\"ה הכל) ומיירי הכא במאורעות הבאים על האדם דאילו במדות אמר בפ' כל היד (נדה דף טז: ושם ד\"ה הכל) הכל בידי שמים חוץ מיראת שמים:"],[8,"שיתין רהיטי רהוט","יש מפרשים דנקט שיתין לפי שימי החורף ששים וכן ימי הקיץ כדאמר לעיל (בבא מציעא דף קו:) ופת שחרית מצלת מן החמה ומן הצנה א\"נ כן דרך למינקט בכל מקום שיתין כדאמר בהחובל (ב\"ק דף צב:) שיתין תכלי מטייה לככא דקל חבריה שמע כו':"],[11,"ארבע גרמידי דאניגרי זלזל בהו","פירוש ארבע אמות שאתה מודד לבני אניגרא שדולים משם להשקות שדותיהם זלזל פירוש מדוד אותם שחוקות ולא מצומצמות כדי שיוכלו לעמוד שם בריוח ולא כפי' הקונט' דעל נהרא שמניחין מקום גם למושכי ספינות לא תמשח כלל שצריכין ריוח הרבה שלא יפלו במים אלא בלא מדידה יתנו שיהא ניכרת ונראה לעינים:"],[13,"בתרי עברי נהרא קוצו","פי' ענפי אילנות היער קוצו שצריכין להטות כתפיהם לצד היער שלא יפלו במים וא\"ת דאמרינן בסוף פרק המוכר פירות (ב\"ב דף צט: ושם ד\"ה ואמה) אמה בית השלחין אני מוכר לך נותן לו ב' אמות לתוכה אמה מכאן ואמה מכאן לאגפיה וי\"ל דהתם מיירי באמת המים שהוא לאדם אחד שהוא עושה חריץ תוך שדהו להשקות ממנה ואין צריך לאגפיים רק אמה מכאן ואמה מכאן והכא אניגרא הוא יאור גדול להשקות כל אותה בקעה לכך צריך ארבע אמות לאגפיה תדע דהתם זורעים אותן אמות ונוטעין שם אילנות כדאמר התם אבל הכא אין זורעין ונוטעין כלל שכל העם הולכים שם להשקות שדותיהם והא דקאמר דאנהרא לכ\"ע לאו משום דאניגרא ליהוו כולהו דאדם אחד אלא אינו דכ\"ע אלא לאותן המשקין שדותיהם לבד אי נמי ארבע אמות דהכא היינו ב' אמות של תוכה ואמה מכאן ואמה מכאן:"]]],[["ואי לא לא מיסתגי להו","רבה בר רב נחמן הוה קא אזיל בארבא חזא ההוא אבא דקאי אגודא דנהרא אמר להו דמאן אמרו ליה דרבה בר רב הונא אמר (עזרא ט, ב) ויד השרים והסגנים היתה במעל הזה ראשונה אמר להו קוצו קוצו","אתא רבה בר רב הונא אשכחיה דקייץ אמר מאן קצייה תקוץ ענפיה אמרי כולהו שני דרבה בר רב הונא לא אקיים ליה זרעא לרבה בר רב נחמן","אמר רב יהודה הכל לאיגלי גפא ואפילו מיתמי אבל רבנן לא מ\"ט רבנן לא צריכי נטירותא לכריא דפתיא ואפילו מרבנן","ולא אמרן אלא דלא נפקא באוכלוזא אבל לאוכלוזא לא דרבנן לאו בני מיפק באוכלוזא נינהו","אמר רב יהודה לכריא דנהרא תתאי מסייעי עילאי עילאי לא מסייעי תתאי וחילופא במיא דמיטרא","תניא נמי הכי חמש גנות המסתפקות מים ממעין אחד ונתקלקל המעיין כולם מתקנות עם העליונה נמצאת התחתונה מתקנת עם כולן ומתקנת לעצמה וכן חמש חצרות שהיו מקלחות מים לביב אחד ונתקלקל הביב כולן מתקנות עם התחתונה נמצאת העליונה מתקנת עם כולן ומתקנת לעצמה","אמר שמואל האי מאן דאחזיק ברקתא דנהרא חציפא הוי סלוקי לא מסלקינן ליה והאידנא דקא כתבי פרסאי קני לך עד מלי צוארי סוסיא מיא סלוקי נמי מסלקינן ליה","אמר רב יהודה אמר רב האי מאן דאחזיק ביני אחי וביני שותפי חציפא הוי סלוקי לא מסלקינן ליה ורב נחמן אמר נמי מסלקינן ואי משום דינא דבר מצרא לא מסלקינן ליה","נהרדעי אמרי אפילו משום דינא דבר מצרא מסלקינן ליה משום שנאמר (דברים ו, יח) ועשית הישר והטוב בעיני ה'","אתא אימליך ביה אמר ליה איזיל איזבון ואמר ליה זיל זבון צריך למיקנא מיניה או לא רבינא אמר לא צריך למיקנא מיניה נהרדעי אמרי צריך למיקנא מיניה והלכתא צריך למיקנא מיניה","השתא דאמרת צריך למיקנא מיניה אי לא קנו מיניה אייקור וזול ברשותיה","זבן במאה ושוי מאתן חזינא אי לכולי עלמא קא מוזילא ומזבין יהיב ליה מאה ושקיל ליה ואי לא יהיב ליה מאתן ושקיל ליה","זבן במאתן ושויא מאה סבור מינה מצי אמר ליה לתקוני שדרתיך ולא לעוותי אמר ליה מר קשישא בריה דרב חסדא לרב אשי הכי אמרי נהרדעי משום דרב נחמן אין אונאה לקרקעות","זבין ליה גריוא דארעא במיצעא נכסיה חזינן אי עידית היא אי זיבורית היא זביניה זביני"],[[0,"ואם לאו לא מסתגי להו","אין להם מהלך בעבר זה והולכין על כרחן דרך שפתו השנית שהרי על כרחן כשהולכין כנגד היער של עכו\"ם ילכו בשפתו השניה ולכשיגיעו כנגד שלי למה יטריחו לעבור את רוחב המים והרי הן צריכין לחזור ולעבור צד אחר כשכלתה הקצירה:"],[1,"חזא ההוא אבא","יער שהניח רבה בר רב הונא לפי שאין העליונים והתחתונים קוצצין ורבה בר רב נחמן לא היה יודע שכן היה שיהא עליון ותחתון של עכו\"ם המושל:"],[1,"יד השרים והסגנים","פסוק הוא בספר עזרא:"],[2,"תיקוץ ענפיה","ימותו בניו:"],[3,"לאגלי גפא","הכל מסייעין לגדור חומת העיר ולהעמיד שעריה שלא יכנס צבא שונאים לעיר:"],[3,"אגלי","שערים כמו ברכות (דף כח.) טרוקו גלי:"],[3,"גפא","סתימת העיר כדתנן לעיל (בבא מציעא דף כה:) מצא אחר הגפה גוזלות:"],[3,"לא צריכי נטירותא","תורתו משמרתו כדכתיב (משלי ו) בשכבך תשמור עליך:"],[3,"לכריא דפתיא","לכרות מעין או בורות למים לשתות:"],[3,"ואפילו מרבנן","שהרי גם הם צריכים לשתות ועל שם כלי ששותין בו משקין שקורין פתיא בלשון ארמי קרי ליה כריא דפתיא:"],[4,"דלא נפקי באכלוזא","שאין יוצאין בעלי בתים עצמן באכלוזא ובאוכלוסא לחפור אלא גובין מעות ושוכרין פועלים:"],[4,"לאו בני מיפק וכו'","גנאי הוא להן:"],[5,"לכריא דנהרא","כשמעלת שרטון ונופלים בה אבנים ומעכבין מרוצת המים וכורין ומנקין אותו להעביר מכשוליו:"],[5,"תתאי מסייעי לעלאי","כשהעליונים מתקנין כנגדן למעלה יש על התחתונים לסייען שמכשולין העליונים מעכבים מים מלירד נמצא תיקון העליונים לעזרת התחתונים:"],[5,"אבל העליונים אין צריכין לסייע את התחתונים","כשמתקנין למטה שתיקון של מטה אינו לעזרת עליונים אלא לרעתם שכל זמן שהמים רצים למטה הנהר מתמעט למעלה והשדות שלהן מתייבשות:"],[5,"וחילופא במיא דמיטרא","כגון בעיר שהמים קשים להרבות טיט ולקלקל את הדרכים ועושין להם חריץ במורד להוריד המים חוץ לעיר אם נתקלקל החריץ כנגד התחתונים וכורין להם העליונים צריכים לסייע את התחתונים לכרות כנגדן שכל זמן שלא ירדו המים התחתונים חוץ לעיר יעמדו העליונים במקומן אבל תחתונים אין להן לסייע לעליונים לכרות למעלה שכל זמן שלא ירדו העליונים למטה טוב להן לתחתונים:"],[6,"ומתקנת לעצמה","בפני עצמה כשמגעת כנגדה אין אחר מסייעה:"],[6,"המקלחות מים","מים סרוחין מי מטר:"],[6,"לביב אחד","חריץ מתוקן להוריד מי גשמים בו:"],[6,"כולן מתקנות עם התחתונה","מסייעות אותה לתקן כנגדה כדפרישית לעיל:"],[7,"האי מאן דאחזיק ברקתא דנהרא","בשני הפרסיים היה הקרקע מופקר לכל הקודם להחזיק בו ולפרוע למלך טסקא דהוא מס של קרקע ואם בא אחד ומחזיק על שפת הנהר מקום שהספינות עולות לנמל וצריך מקום פנוי הרבה לפורקי משאות לספינות ולטוענין מתוכן ומוציאין וזה החזיק לבנות שם בנין או לחרוש ולזרוע:"],[7,"חציפא הוי","שמקלקל מקום לרבים:"],[7,"אבל סלוקי","מדינא לא מסלקינן ליה:"],[7,"והאידנא דכתבי פרסאי","לאותן הלוקחין שדות שעל שפת הנהר קני לך השדה עד תוך הנהר מלא צואר הסוס והלוקחין גודרין גדירן רחוק מן הנהר שלא לקלקל את מקום הרבים ואם בא אחד והחזיק מן הגדר ולצד הנהר מסלקינן ליה לפי שהיא קנויה לבעל הגדר עד תוך המים:"],[8,"בני אחי","שדה העומדת ליקח בטסקא ושדות שני אחים סמוכין לה מכאן מכאן:"],[8,"ואי משום דינא דבר מצרא","אם אינן לא אחים ולא שותפים אלא מכח מצרנות באין על המחזיק ואומרים אנו היינו מצפים לקחתה שאנו צריכין לקרקע וטוב לכל אחד לקנות בסמוך לו ולא ליקח במקום אחר:"],[8,"לא מסלקינן ליה","דלא איכפת לן לדינא דבר מצרא כלל:"],[9,"ועשית הישר והטוב","דבר שאי אתה נחסר כ\"כ שתמצא קרקעות במקום אחר ולא תטריח על בן המצר להיות נכסיו חלוקין:"],[10,"אתא לאימלוכי ביה","שדה היוצאה לימכר ובא אחר ונטל רשות מבן המצרן ואמר ליה זיל זבון:"],[10,"נהרדעאי אמרי צריך למקני","דאי לא קנה מיניה מצי אמר ליה משטה הייתי בך כדי להעמידה על דמים הראויין לה שאם באתי אני אצל הבעלים היה מעלה לי בדמים בשביל שחביבה עלי:"],[11,"השתא דאמרת צריך למיקנייה מיניה","אם כן אין קניינו של זה כלום אם אייקר או זול ארעא ברשותא דבר מצרא אייקר או זול ולא יוסיף ולא יגרע הלוקח מלקבל דמים שנתן בה דכי אייקר רווחא דבר מצרא הוא וכי זול פסידא דבר מצרא הוא:"],[12,"ואי לא יהיב ליה מאתן","דגבי דהאי הוא דאוזיל:"],[14,"בי מיצעי דנכסי","של מוכר שדות המוכר מקיפות לה מכל צד:"],[14,"חזינן אי עידית היא","דבר העשוי לימכר לעצמו שאינו דומה לשאר שדות הסמוכות לה:"],[14,"זביניה זביני","ואין מצרני המוכר יכולים לסלקו שהרי יש ביניהן הפסק:"]],[[2,"ליקוץ ענפיה","שזה היה אותו יער עצמו של פרזיק רופילא ולא היתה ידו במעל כלל לכך קילל:"],[7,"האי מאן דאחזיק ברקתא דנהרא","קיבל בטסקא מן המלך כדפי' בקונטרס ולהכי קאמר דאחזיק ולא קאמר דזבין כדאמרינן לקמן זבין במאתים זבין מעכו\"ם וכן האי מאן דאחזיק ביני אחי דבסמוך מפר\"ת דוקא באחזיק שהיתה קרקע הפקר וקבלה מן המלך בטסקא לא מסלקינן ליה ולרב נחמן דוקא ביני אחי מסלקינן ליה שעשה יותר מדאי שלא כהוגן להחזיק ביני אחי אבל משום מצרנות לא מסלקינן ליה דלא שייך כאן ועשית הישר והטוב כיון שיוכלו לקבל מן המלך ולא חשו אבל במכר מודים הם כ\"ע דשייך דינא דבר מצרא דלא הוה ליה לאסוקי אדעתיה דמצרן שהיו הבעלים רוצים למכור ונהרדעי סברי דאפילו הכי שייך ועשית הישר והטוב והשתא אתי שפיר הא דאמרי נהרדעי משמיה דרב נחמן בשמעתין אין אונאה לקרקעות דאמצרנות קאמר כדמוכח בכתובות בפ' אלמנה (דף צט: ע\"ש ושם ד\"ה ה\"ג) דקאמר רבא גבי טעה השליח והאמר מר אין אונאה לקרקעות גבי מצרנות שהוא כעין שליח שהמקח לא יהיה שלו ואין צריך לדחוק כפי' הקונטרס דרב נחמן לית ליה דינא דבר מצרא:"],[7,"והאידנא דכתבי פרסאי","לא כפירוש הקונטרס דמפ' דמסלקינן ליה שהראשון קנאו מן המלך אלא דמסלקינן ליה לבא להחזיק לכתחילה משום דכיון דכתבי פרסאי כו' חיישינן שלא יבא להחזיק עד תוך הנהר כמו שכותב לו המלך ויעכב הילוך הספינות וביאתן לנמל וקנסינן ליה משום הכי להסתלק מכולה רקתא אפילו ממה שחוץ לנהר:"]]],[["ואי לא איערומי קא מערים","מתנה לית בה משום דינא דבר מצרא אמר אמימר אי כתב ליה אחריות אית בה משום דינא דבר מצרא","מכר כל נכסיו לאחד לית בה משום דינא דבר מצרא לבעלים הראשונים לית בה משום דינא דבר מצרא זבן מעכו\"ם וזבין לעכו\"ם לית בה משום דינא דבר מצרא","זבן מעכו\"ם דאמר ליה ארי אברחי לך ממצרא זבין לעכו\"ם עכו\"ם ודאי לאו בר ועשית הישר והטוב הוא שמותי ודאי משמתינן ליה עד דמקבל עליה כל אונסי דאתי ליה מחמתיה","משכנתא לית בה משום דינא דבר מצרא דאמר רב אשי אמרו לי סבי דמתא מחסיא מאי משכנתא דשכונה גביה מאי נפקא מינה לדינא דבר מצרא","למכור ברחוק ולגאול בקרוב ברע ולגאול ביפה לית בה משום דינא דבר מצרא","לכרגא ולמזוני ולקבורה לית בה משום דינא דבר מצרא דאמרי נהרדעא לכרגא למזוני ולקבורה מזבנינן בלא אכרזתא לאשה וליתמי ולשותפי לית בה משום דינא דבר מצרא","שכיני העיר ושכיני שדה שכיני העיר קודמין","שכן ותלמיד חכם תלמיד חכם קודם קרוב ותלמיד חכם תלמיד חכם קודם איבעיא להו שכן וקרוב מאי ת\"ש (משלי כז, י) טוב שכן קרוב מאח רחוק","הני זוזי טבי והני זוזי תקולי לית ביה משום דינא דבר מצרא הני ציירי והני שרי לית ביה משום דינא דבר מצרא","אמר איזיל ואטרח ואייתי זוזי לא נטרינן ליה אמר איזיל אייתי זוזי חזינן אי גברא דאמיד הוא דאזיל ומייתי זוזי נטרינן ליה ואי לא לא נטרינן ליה","ארעא דחד ובתי דחד מרי ארעא מעכב אמרי בתי מרי בתי לא מעכב אמרי דארעא ארעא דחד ודיקלי דחד מרי דארעא מצי מעכב אמרי דיקלי מרי דיקלי לא מצי מעכב אמרי דארעא","ארעא לבתי וארעא לזרעא ישוב עדיף ולית בה משום דינא דבר מצרא","אפסיק משוניתא או ריכבא דדיקלא חזינא אם יכול להכניס בה אפילו תלם אחד אית בה משום דינא דבר מצרא ואי לא לית בה משום דינא דבר מצרא","הני ד' בני מצרני דקדים חד מינייהו וזבין זביניה זביני ואי כולהו אתו בהדי הדדי פלגו לה בקרנזיל:"],[[0,"ואי לא איערומי קא מערים","אם באתי ליקח אצלם יסלקוני אקנה אני בית סאה באמצע ואהיה אני מצרן לכל רוח ואקנה אני אחרי כן לכל צד ולא יוכלו לסלקני מן המחצה ומן הנותר לכל רוח הלכך מהשתא מסלקינן ליה:"],[1,"ואי כתב ליה אחריות כו'","דודאי מכר הוא שאין כותבין אחריות על המתנה:"],[2,"מוכר כל נכסיו לאחד","בכל מקום שהן זו במזרח וזו במערב ויצאו מצרני אחת מהן וערערו:"],[2,"לית בהו משום דינא דבר מצרא","שלא תקנו חכמים ללוקח להסתלק לעשות הישר והטוב לבעל המצר שהוא רעה למוכר שזה לא יקנה השאר שימשוך את ידו בשביל זו ובמקום פסידא דמוכר לא תקון דינא דבר מצרא כדאמר לקמן הני ציירי והני שרו לית בה משום דינא דבר מצרא:"],[3,"אריא אברחי לך","ואין לך ישר וטוב מזה:"],[3,"עכו\"ם לאו בר ועשית וכו'","ואין לנו לומר על דינא דבר מצרא ועשית הישר והטוב אלא ללוקח שהמוכר אומר לו מה עשיתי לך אם ארצה לא אמכרנה לך ותהא בידי אבל ללוקח נאמר משוך ידך ויקחנה זה:"],[3,"שמותי ודאי משמתינא ליה","למוכר לקבולי עליה כל אונסא דאית ליה מחמת העכו\"ם:"],[4,"משכנתא","אם מכרה למי שממושכנת לו:"],[4,"לית בהו משום דינא דבר מצרא","שזה שכן מצרן מכולן שכולו שכונה בידו:"],[5,"למכור ברחוק ולגאול בקרוב","אם המוכר זה מוכרה מפני שהיא רחוקה ממנו ורוצה לקנות אחרת בקרוב:"],[5,"אין בה משום דינא דבר מצרא","לפי שאין לנו להפסיד מוכר משום טוב וישר דמצרן דכשם שעלינו לעשות טוב לזה כך עלינו לעשות טוב לזה. ואם באנו לעשות איחור בדבר שמא בין כך ובין כך תמכר זו שהיה רוצה זה לקנות:"],[6,"וכן לכרגא","לפרוע כסף גולגלתא למלך:"],[6,"[ולמזוני]","למזון אלמנה והבנות שב\"ד מוכרין בנכסי יתומין וכן לקבור את המת:"],[6,"בלא אכרזתא","וכיון דמשום רווחא דיתמי לא משהינן למילתא פן יכעוס שוטר המלך וכן חסרון מזונות ולבזיון המת כל שכן דמשום בר מצרא לא משהינן מילתא לאודועי:"],[6,"לאשה ליתמי ולשותפי","מכר לאשה לא מסלקינן ליה דלאו אורח ארעא לאהדורי ולבקש מי שיש לו קרקעות למכור ומה שבאה לידה ראשון אין לנו לומר ועשית הישר והטוב להרחיקו מעליו וכן יתמי ושותף שמכר לו לחבירו חלקו בשדה שהן שותפין בה אין לנו לסלקו משום דינא דבר מצרא ולומר אין אתה בא בחלק חבירך אלא כאחד המצרנין ויקחנה עמך אלא כיון דלא נתברר חלקו והרי הוא כשכן בכולה:"],[7,"שכיני העיר ושכיני השדה שכיני העיר קודמין","נראה בעיני דלאו בדינא דבר מצרא איירי אלא להשיא עצה דרך ישר וטוב למוכר שאם יש לו שדה למכור ובאו עליה ללוקח שכינים הדרים אצלו בדירה ושכן שיש לו בשדה ששדותיהן סמוכות זו לזו וזו שיש לו למכור אינה סמוכה למצרן שכיני העיר קודמין ואני לא דקדקתי בה מפי רבינו כל צרכי ועד הנה פירשתי דבמצרן דיליה קאמר והשתא לא נראה לי דאם כן הוה ליה למיתנינהו בהדי הנך דלעיל ולמימר הכי לאשה וליתמי ולשותפי ולשכיני העיר ולת\"ח לית בה משום דינא דבר מצרא מאי שנא דשני בלישנא דכולי שמעתא למינקט לישנא דקודמין ותו דקאמר שכן ותלמיד חכם ת\"ח קודם אי האי שכן מצרן הוא אמאי ת\"ח קודם תלמיד חכם לאו בר ועשית הישר והטוב הוא דהאי ועשית אלוקח שדיוה רבנן כדאמרינן לעיל גבי זבין לעכו\"ם עכו\"ם לאו בר ועשית כו' ותו קרוב ותלמיד חכם מאי דינא דבר מצרא איכא וא\"ת כששניהן מצרנין אטו משום דת\"ח הוא משלח גלימא דאינשי:"],[9,"זוזי טבי זוזי תקולי","מצרן שבא לעורר על המקח מביא מעות שמשקלן טוב יותר על של לוקח אבל של לוקח טבין וחריפין במטבע היוצאה יותר משל מצרן ואי נמי איפכא:"],[9,"לית בה משום דינא דבר מצרא","דאמר ליה המוכר בהא ניחא:"],[9,"הני ציירי והני שרו","לוקח ומצרן ששלחו מעותיהן של מצרן צרורין וחתומין וזה ירא להתירן שלא יאמר יותר היו ושל לוקח מותרין:"],[9,"לית בה משום דינא דבר מצרא","דפסידא דמוכר הוא דאמר לזוזי צריכנא:"],[10,"אמר ליה איזיל ואיטרח וכו'","מילתא באפי נפשיה היא מצרן שאמר איזיל ואיטרח וכו':"],[10,"דאמיד הוא","שאנו אומדין אותו דאפשר לו לקיים דבריו:"],[11,"ובתי דחד","בנין שעליה:"],[11,"מרי ארעא מעכב אמרי בתי","שלא למכור הבנין לאחר דהואיל והוא בא למוכרם וזה צריך לה טוב שיהיה בנינו בקרקע שלו ואיכא הישר והטוב:"],[11,"מרי בתי לא מעכב אמרי ארעא","שהוא אינו חשוב שכן לכשיגיעו שניו עומד להסתלק מיניה:"],[11,"ודיקלי דחד","שמכר לו דקלין בשדהו להניחן שם עד זמן פלוני או עד שיבשו:"],[12,"ארעא לזורעה","המצרן חפץ בה לזריעה והלוקח צריך בה לבנין בית:"],[12,"ישוב דבתי עדיף","לבית דין ולא תקנו כאן עשות ישר וטוב שזו טובה מזו:"],[13,"אפסיק משוניתא","שן סלע מפסיק בין שדה זו לשדה של מצרן:"],[13,"או ריכבא דדיקלא","הדקלים הכפופין וסמוכין זו לצד זו ומסוגרין כאותן שקורין פלשייר\"י בלעז:"],[13,"אם יכול להכניס המצרן תלם אחד","משדהו לתוך שדה זו אית בה וכו':"],[13,"תלם","שורות המענה:"],[13,"ואי אייתי בהדדי","שמערער כל אחד על מצרנותו:"],[14,"פלגי לה בקרנזיל","בארבע אלכסונות שיהא כל אחד נוטל בה על פני כולה סמוך לו כזה ☒ ולשון קרנזיל זיל בה לקרנות:"]],[[3,"משמתינן ליה עד דמקבל כו'","דוקא שישראל רוצה ליקח בדמים שנתן העכו\"ם:"],[6,"מזבנינן בלא אכרזתא","אין לפרש כל הני מילי לצורך יתומים דא\"כ הוה משמע דלשאר צורכי יתומים אין מוכרין בלא אכרזתא כי הנהו דחשיב פ' הנזקין (גיטין דף נב. ושם) מוכרים שדותיהן לקנות להן מגלה וציצית ושופר כו' וא\"כ בפרק שום היתומים (ערכין דף כב. ושם) דפריך לרב. אשי דאמר אין נזקקין כו' מדתנן שום היתומים שלשים יום ומכריזין בבוקר ובערב לוקמה במילי דיתמי שצריכי הכרזה אלא ודאי לכל מילי דיתמי אין צריכין הכרזה ובשמעתין מיירי בכרגא ומזוני וקבורה דאשה ובנות ואם תאמר לקבורה פשיטא דמזבנינן בלא אכרזתא דאטו יהיה מת מוטל באשפה כל ימי הכרזה וי\"ל דאם לוו לצורך קבורה קאמר דמזבנינן בלא אכרזתא כדי לפדות אי נמי דה\"א שממשכנין מחפצי יתומים עד שמכריזין קמ\"ל:"],[7,"שכיני העיר כו'","הא מילתא בדין הקדמה קמיירי כששניהם מצרנים ושכן עיר מצרן מצד העיר שיש לו שדה אחורי ביתו הסמוכה לזו ושכן שדה שיש לו שדה רחוקה מן העיר הסמוכה לזו:"],[11,"ארעא דחד ובתי דחד","שהבית בנוי על גבי קרקע מרי דארעא מעכב שלא ימכור הלה עציו ואבניו כי אם לו אבל בבית אצל בית או קרקע שאינו עומד לזריעה לא שייך דינא דבר מצרא דלא שייך התם טעמא דקאמר בסמוך להכניס תלם אחד ודוקא בשדה של זריעה שייך הישר והטוב שיכול לחורשה בבת אחת וכן פר\"ת בתשובה אחת המתחלת חזרנו על כל צידי צדדים ולא מצאנו דין מצרנות בבתים:"]]],[["\u0001מתני׳\u0002 המקבל שדה מחבירו לשנים מועטות לא יזרענה פשתן ואין לו בקורות שקמה קיבלה הימנו לז' שנים שנה ראשונה יזרענה פשתן ויש לו בקורות שקמה:","\u0001גמ׳\u0002 אמר אביי בקורות שקמה אין לו בשבח שקמה יש לו ורבא אמר אפילו בשבח שקמה נמי אין לו","מיתיבי המקבל שדה מחבירו והגיע זמנו לצאת שמין לו מאי לאו שמין לו בשבח שקמה לא שמין לו ירקא וסילקא","ירקא וסילקא נעקור ונשקול בדלא מטא יומא דשוקא","ת\"ש המקבל שדה מחבירו והגיע שביעית שמין לו שביעית מי קא מפקעא ארעא אלא אימא המקבל שדה מחבירו והגיע יובל שמין לו","ואכתי יובל מי מפקעא קבלנות לצמיתות אמר רחמנא אלא אימא הלוקח שדה מחבירו והגיע יובל שמין לו","וכי תימא ה\"נ שמין לו בירקא וסילקא סילקא וירקא ביובל הפקירא הוא אלא לאו שבח שקמה","תרגמא אביי אליבא דרבא שאני התם דאמר קרא (ויקרא כה, לג) ויצא ממכר בית ממכר חוזר שבח אינו חוזר ונגמר מיניה התם זביני מעליא הוא ויובל אפקעתא דמלכא היא","רב פפא קביל ארעא לאספסתא קדחו בה תאלי כי קא מסתלק אמר להו הבו לי שבחא א\"ל רב שישא בריה דרב אידי לרב פפא אלא מעתה דיקלא ואלים ה\"נ דבעי מר שבחיה א\"ל התם לאו אדעתא דהכי נחית אנא הכא אדעתא דהכי נחיתנא","כמאן כאביי דאמר בשבח שקמה יש לו אפילו תימא כרבא התם לית ליה פסידא הכא איכא פסידא","א\"ל מאי פסדתיך ידא דאספסתא שקול ידא דאספסתא וזיל אמר ליה אנא כורכמא רישקא רבאי א\"ל גלית אדעתך דלמשקל ואסתלוקי עבדת שקל כורכמא רישקא וזיל אין לך אלא דמי עצים בלבד","רב ביבי בר אביי קביל ארעא ואהדר ליה משוניתא קדחו ביה זרדתא כי קא מיסתלק אמר להו הבו לי שבחאי אמר רב פפי משום דאתיתו ממולאי אמריתו מילי מולייתא אפילו רב פפא לא אמר אלא דאית ליה פסידא הכא מאי פסידא אית לך:","רב יוסף הוה ליה ההוא שתלא שכיב ושבק חמשה חתנוותא אמר עד האידנא חד השתא חמשה עד האידנא לא הוו סמכו אהדדי ולא מפסדו לי השתא חמשה סמכו אהדדי ומפסדו לי אמר להו אי שקליתו שבחייכו ומסתלקיתו מוטב ואי לא מסליקנא לכו בלא שבחא","דאמר רב יהודה ואיתימא רב הונא ואיתימא ר\"נ האי שתלא דשכיב יורשים דיליה מסתלקין להו בלא שבחא ולאו מילתא היא","ההוא שתלא דאמר להו אי מפסדינא מסלקנא אפסיד אמר רב יהודה מסתלק בלא שבחא רב כהנא אמר מסתלק ושקיל שבחא ומודה רב כהנא דאי אמר אי פסידנא מסתלקנא בלא שבחא מסתלק בלא שבחא רבא אמר אסמכתא היא ואסמכתא לא קניא","ולרבא מאי שנא מהא דתנן אם אוביר ולא אעביד אשלם במיטבא התם מאי דאפסיד משלם הכא מאי דאפסיד מנכינן ליה ואידך יהבינן ליה","רוניא שתלא דרבינא הוה אפסיד סלקיה אתא לקמיה דרבא א\"ל חזי מר מאי קא עביד לי א\"ל שפיר עביד א\"ל הא לא התרה בי א\"ל לא צריכא להתרות רבא לטעמיה דאמר רבא מקרי דרדקי שתלא טבחא ואומנא"],[[0,"מתני' לשנים מועטות","פחות משבע שנים:"],[0,"לא יזרענה פשתן","שזרע פשתן מכחיש בארץ הרבה ואינה חוזרת ליושנה עד שבע שנים והא לא מיתוקמא אלא בחכירות דאי בקבלנות מאי דבעי ליזרע שהרי הבעלים חולקין בו:"],[0,"ואין לו בקורות שקמה","עץ סרק הוא וקוצצין ענפיו לקורות הבנין והן חוזרין וגדילין ופחות מז' שנים אין נעשות קורות הלכך קיבלה לפחות משבע שנים לא יקוץ קורות שבה דלאו אדעתא דקורות נחית דבשנים מועטות אינם חוזרים לקורות אבל קיבלה לז' שנה ראשונה זורעה פשתן וקוצץ שנה ראשונה שקמה שבה:"],[1,"גמ' שבח שקמה יש לו","עשו והשביחו שמין לו שבחם לכשיסתלק:"],[5,"לצמיתות אמר רחמנא","מי שאילולי יובל היתה נצמתת דכתיב (ויקרא כ״ה:כ״ג) והארץ לא תמכר לצמיתות:"],[7,"וניגמר מיניה","דמקבל:"],[7,"התם זביני מעליא הוא","וכל כמה דאשבחא ארעא ברשותיה אשבחא וארעא דהדרא משום דיובל אפקעתא דמלכא הוא ומאי דלא פקע מלכא לא מפקע ממכר אפקע שבחא לא פקע:"],[8,"קדחי בה תאלי","צמחו בה אילנות:"],[8,"דיקלא ואלים","קיבל הימנו אילן לפירותיו כך וכך שנים ונתעבה והגבירו עיקרו ה\"נ וכו':"],[8,"לאו אדעתא דהכי נחת","אלא לאכילת פירות הכא אדעתא דהכי נחת לכל אשר יצמח בה:"],[9,"התם לית ליה פסידא","כל מה שהשביח שקמה לא מנע ממנו חרישה וזריעה:"],[10,"ידא דאספסתא","מקום הדקלין היה זורע אספסתא ידא כמו (במדבר ב׳:י״ז) איש על ידו:"],[10,"אנא כורכמא רישקא רבאי","אני הייתי מגדל במקומן כרכום שדמיו יקרין:"],[10,"א\"ל","מדקאמרת כורכמא רישקא רבאי שהוא דבר הנקצר בכל שנה ולא אמרת אנא תאלי הייתי נוטע בה למישקל שבחייהו גלית אדעתך דלא נחתת להא ארעא אדעתא למיעבד בה מידי דבר קיימא למישם ליה שבחיה ומפיק אלא מידי דתיעקריה ותישקליה ותיזיל כי מסתלקת שקול כורכמך רישקך אותו כורכמא רישקא דהיינו תאלי שקיימו בה עקור אותו ולך וכשתבא לעקור אינו אלא עצים וזה יתן לך דמי עצים:"],[11,"אהדר ליה משוניתא","הגביהו סביב גבוליה כעין שן הר:"],[11,"קדחי ביה זרדתא","בההיא משוניתא צמחו בה אילנות של עוזרדין קורמיי\"ר בלעז:"],[11,"ממולאי","מבית עלי שהיה ממשפחה רעועה:"],[11,"אמריתו מילי מולייתא","דברים גבנונים לשון מוליא במוליא במו\"ק (דף י:) גבשושית:"],[11,"אפילו רב פפא","דבעי שכר שבחא דתאלי:"],[11,"דאית ליה פסידא","שצמחו במקום הראוי לזריעה:"],[11,"הכא מאי פסידא איכא","במשוניתא אין דרך לזרוע:"],[12,"שתלא","נוטע כרם בקרקע בעל הבית ועליו להיות אריס כל הימים ונוטל מחצה בפירות:"],[14,"אפסיד","מאי דאשבח כבר מיהו אכתי הוה שבחא ומיסתלקנא דקאמר בלא שבחא קאמר:"],[14,"ורב כהנא אמר וכו'","דה\"ק אי מפסידנא מסתליקנא על כרחי ושקילנא מאי דאשבחי:"],[14,"לא קניא","ואפילו אמרת הכי לא מסלקינן ליה בלא שבחא:"],[15,"מאי דאפסיד מנכינן ליה","שיימינן מאי דמטי לבעל הבית בהפסד ומנכינן ליה מחלקו דשתלא בשבח:"],[16,"אומנא","מוהל תינוקות:"],[16,"כמותרין ועומדין דמי","לסלקינהו:"],[16,"מקרי דרדקי","פסידא דלא הדר הוא דשבשתא כיון דעל על:"]],[[8,"אלא מעתה דיקלא ואלים ה\"נ","דבעי מר שבחא באלימות הדקל הא ודאי אפילו לאביי לית ליה דדוקא בשבח שקמה דליכא פרי אלא שבח דגידול ענפים קאמר אביי דיש לו דאדעתייהו נחת אבל אדעתא דאלימות הדקל לא נחת ה\"נ מר לא נחת אדעתא דתאלי אלא אדעתא דאספסתא א\"ל התם ודאי לאו אדעתא דהכי נחת כדקאמרת אבל אנא נחתינא למה שיצמיח הקרקע דהיינו אספסתא ואלו צמחו במקומה:"],[9,"כמאן כאביי","דאילו לרבא דאמר בשבח שקמה אין לו אע\"ג דאיכא למימר דאדעתא דהכי נחית ומשני דאפילו תימא כרבא דהתם כו':"],[10,"אין לך אלא דמי עצים בלבד","ואע\"ג דבסוף פרק השואל (לעיל בבא מציעא דף קא. ושם) אמר דמצי למימר זיתי אני נוטל אי לאו משום ישוב א\"י הכא לא מצי אמר ליה דמיירי דהני תאלי לא היו ראוים לנוטעם במקום אחר ואם היה נוטלם היו מתים ולא היו שוים אלא לעצים א\"נ מדלא א\"ל תאלי הוה נטענא אלא כורכמא דרישקא שמשעוקרין אותן אין נוטעין אותן במקום אחר גלית אדעתיך שלא היית חושש בדבר שראוי לנוטען ולכך אין לך אלא דמי עצים וכגון שהתאלי לא היו מכחישין אותו יותר מאספסתא וכורכמא דרישקא שאם לא כן לא יכול לומר תאלי הוה נטענא שהרי לאספסתא קבלה:"],[13,"מסלקינן להו בלא שבחא ולאו מילתא היא","פי' ריב\"ן שלא אמר דבר זה מעולם אלא להפחידו אמר כן ותימה דאם לא אמר מעולם למה הזכיר כל כך אמוראים רב הונא ואיתימא רב יהודה ואיתימא כו' וי\"ל דרב יוסף לא הזכיר אלא אחד מהם ובני בית המדרש נסתפקו בין אלו איזה מהן הזכיר:"]]],[["וספר מתא כולן כמותרין ועומדין דמי כללא דמילתא כל פסידא דלא הדר כמותרין ועומדין דמי","ההוא שתלא דאמר להו הבו לי שבחאי דבעינא למיסק לארעא דישראל אתא לקמיה דרב פפא בר שמואל אמר להו הבו ליה שבחיה א\"ל רבא איהו אשבח ארעא לא אשבח א\"ל אנא פלגא דשבחא קאמינא לך א\"ל עד האידנא הוה שקיל בעל הבית פלגא ושתלא פלגא השתא בעי למיתב מנתא לאריסא א\"ל ריבעא דשבחא קאמינא","סבר רב אשי למימר ריבעא דהוא דנקא דאמר רב מניומי בריה דרב נחומי באתרא דשקיל שתלא פלגא ואריסא תילתא האי שתלא דבעי לאסתלוקי יהבינן ליה שבחא ומסלקינן ליה כי היכי דלא נמטייה הפסד לבעל הבית","אי אמרת בשלמא ריבעא דהוא דנקא שפיר אלא אי אמרת ריבעא ממש קא מטי ליה פסידא לבעל הבית פלגא דנקא","א\"ל רב אחא בריה דרב יוסף לרב אשי ולימא ליה אנת מנתא דילך הב ליה לאריסא ואנא מנתא דילי מאי דבעינא עבידנא ביה אמר כי מטית לשחיטת קדשים תא ואקשי לי","גופא אמר רב מניומי בריה דרב נחומי באתרא דשקיל שתלא פלגא ואריסא תילתא האי שתלא דבעי איסתלוקי יהבינן ליה שבחיה ומסלקינן ליה כי היכי דלא ליפסוד בעל הבית אמר רב מניומי בריה דרב נחומי קופא סבא פלגא שטפה נהרא ריבעא","ההוא גברא דמשכין פרדיסא לחבריה לעשר שנין וקש לחמש שנין אביי אמר פירא הוי רבא אמר קרנא הוי וילקח בו קרקע והוא אוכל פירות","מיתיבי יבש האילן או נקצץ שניהם אסורים בו כיצד יעשו ימכרו לעצים וילקח בהן קרקע והוא אוכל פירות מאי לאו יבש דומיא דנקצץ מה נקצץ בזמנו אף יבש בזמנו וקתני ילקח בהן קרקע והוא אוכל פירות אלמא קרנא הוי","לא נקצץ דומיא דיבש מה יבש בלא זמנו אף נקצץ בלא זמנו","ת\"ש נפלו לה גפנים וזיתים זקנים"],[[1,"א\"ל אנא פלגא בשבחא קאמינא","כדרך שאר שתלים שאינן מסתלקין:"],[1,"השתא קבעי למיתב מנתא לאריסא","כלומר כיון דמיסתלק לו בלא זמנו אמאי שקיל פלגא בשבחא עד האידנא הוה שקיל בעל הבית פלגא בפירות וזה היה עושה בה כל עבודתו כמשפט אריסין:"],[1,"השתא קבעי למיתב מנתא לאריסא","עכשיו זה יטול כל המגיע לו וילך ועל בעל הבית ליטול עבודת הכרם ויצטרך לתתה לאריסא ודרך אריס שיורד לכרם נטוע ליטול שליש בפירות נמצא בעל הבית מפסיד שליש ממחציתו בכל שנה:"],[1,"ריבעא דשבחא","לקמן מפרש ואזיל:"],[2,"סבר רב אשי למימר ריבעא","דתרי תילתא המגיעין לבעל הבית משתוציא השליש שיצטרך ליתן לאריס שיורד לה דהוא דנקא בכל שבח הכרם כגון אם השבח ששה דינרים יוציא מהן שליש שעתיד ליתן לאריס נותרו ארבעה דינרים מהן יטול השתל דינר והיינו ריבעא במאי דמטא לבעל הבית דהוא דנקא דשבחא כוליה:"],[2,"דנקא","שתות:"],[2,"דאמר רב מניומי באתרא דשקיל שתלא פלגא","בפירות ועושה עבודה לעולם:"],[2,"ואריסא תילתא","אריס היורד לתוך הכרם גמורה ועובדה נוטל שליש בפירות:"],[2,"האי שתלא דבעי איסתלוקי","שיימינן ליה כי היכי דלא נפסיד בעל בית כלומר מעיינין במילתא למיתב ליה כי היכי דלא נמטייה פסידא לבעל הבית בסילוק של זה:"],[3,"אי אמרת בשלמא דנקא","שקיל שתלא שפיר דכי הדר שקיל אריסיה תילתא הרי שלשה דינרין בין שניהן פש ליה פלגא דבעל הבית כדהוה שקל עד השתא:"],[3,"אלא אי אמרת ריבעא ממש","דינר וחצי והאריס יטול שליש שהן שני דינרין:"],[3,"פסידא לבעה\"ב","חצי דינר ממחציתו:"],[4,"ולימא ליה","שתלא אנת מנתא דידך הב ליה לאריסא שיטרח בו החצי שלך שהיה מוטל עלי לעשות ואתה אוכל פירות הב ליה לאריסא ועלי לנכות מחלקי כפי המגיע לו והיינו ריבעא ממש דינר וחצי כיצד טול אתה שלשה רבעי הכרם לחלקך מהן תתן השליש לאריס נמצאת אוכל כל השנה חצי פירות הכרם בלא יציאה:"],[4,"מנתא דידי מאי דבעינא עבידנא ביה","אני אמכור לאחרים הרביע המגיע לידי ולא שייך גבאי למיתן מנתא לאריסא דהא מזבנינא ומסתלקנא הקונה ירד ויעשה ויאכל ואם באת לקנותו הרי אין עלי לעשות לך ותאכל את פירותי בחנם אם תתנהו לאריס לישקול מיניה וביה שוה חצי דינר והדינר ישאר לך והיינו תרי תילתי שהרי עכשיו אתה קונה ממני ולעולם ריבעא ממש קאמר רב פפא (ואין בעל הבית מפסיד כלום שעד עתה היה אוכל חצי הפירות ומעתה אוכל שני שלישים דהיינו ארבעה דינרים):"],[4,"כי מטית לשחיטת קדשים","הכרתי בך שאתה חדוד ויודע להעמיק ולהקשות וכי מטית למסכת זבחים שהיא עמוקה תא אקשי לי ואתן לב לתרץ לפי שאלתך ויש אומרים דחויי מדחיה ולא היא דעל כרחיך קבולי קיבלה חדא דקושיא מעליא היא ועוד מדקאמר קסבר רב אשי למימר מכלל דמסקנא לאו הכי הוא:"],[5,"קופא סבא פלגא","גפן שהזקינה בכרם הרי הוא כשאר זמורות שחולקין בהם ונוטל בה שתלא פלגא כשאר פירות דכיון דאורחה בהכי אדעתא דהכי נחת:"],[5,"שטפה נהר","ובאו לחלק העצים הוה ליה כי שתלא דמיסתלק בלא זמניה ושקיל ריבעא שטפה נהרא פעמים שעוקרין לגמרי ופעמים ששוטף את הקרקע ומכחישו ואין ראוי לצמוח בו כלום עד זמן מרובה:"],[6,"ההוא גברא דמשכין פרדיסא לחבריה","משכן לו כרם במשכנתא דסורא א\"נ בנכייתא:"],[6,"וקש","הזקין ובזמנו שהיה ראוי לכך:"],[6,"פירא הוי","עצים שבו ויטלם המלוה:"],[7,"יבש האילן","במשכנתא קאי:"],[7,"מה נקצץ בזמנו","שאין אדם קוצץ אילן שעושה פירות אלא בזמנו שחדל לו מעשות פרי:"],[8,"בלא זמנו","ומודה אביי בלא זמנו שחדל לעשות פרי דכיון דלאו אורחיה לאו פירא הוא ולאו אדעתא דהכי נחת:"],[9,"נפלו לה","לאשה משניסת מת אביה ונפלו לה בירושה:"]],[[0,"וספר מתא כמותרין ועומדין","פי' בקונטרס משום דשבשתא כיון דעל על לכך חשיב פסידא דלא הדר וליתא דרבא גופיה אית ליה בפ' לא יחפור (ב\"ב דף כא. ושם) דשבשתא ממילא נפקא אלא להכי קרי ליה הכא פסידא דלא הדר לפי שבאותה שעה שלימדו שיבושים נתבטל לו לימוד של אמת:"],[6,"רבא אמר קרנא הוי","וא\"ת והא קופא סבא פלגא ודוחק לומר דפליג רבא אדרב מניומי וי\"ל דקופא סבא פלגא משום דשתלא שקיל אפילו בגוף הקרקע פלגא וכי מסתלק בלא זמניה הוא דשקיל ריבעא משום דעליו לשלם אפילו מה שהבעל יצטרך ליתן לאריס שישמור חלקו שהיה מוטל על השתלא לשמור וכן שטפה נהרא ריבעא דאדעתא דהכי נחית שאם יסתלק בלא זימניה באיזה ענין שיסתלק שלא יקח אלא ריבעא ובקופא סבא שאין עוד מה לשמור שקיל פלגא אבל הכא המלוה אין לו בגוף כלום אלא בפירות:"],[7,"מה נקצץ בזמנו","דאין דרך לקצוץ שלא בזמנו ולהפסיד פירות ועוד דאמרינן בפרק לא יחפור (ב\"ב דף כו.) האי דיקלא דטעון קבא אסור למיקציה ואית דגרסי איפכא יבש בזמנו ואין נראה לר\"י:"],[8,"לא מה יבש שלא בזמנו","יבש משמע שלא בזמנו מדלא קתני הזקין ואע\"ג דהזקין נמי משמע שלא בזמנו כדאמרינן בסמוך אימא והזקינו הזקינו משמע בין בזמנו בין שלא בזמנו אבל יבש לא משמע אלא שלא בזמנו:"],[8,"אף נקצץ שלא בזמנו","וא\"ת ואמאי איצטריך למימר אף נקצץ שלא בזמנו והא מעיקרא לא פריך אלא מיבש דהוה דומיא דנקצץ אבל מנקצץ בזמנו לא פריך משום דאיכא למימר דנקצץ בזמנו היינו לאחר שיבש שלא בזמנו והשתא דשני ליה מיבש תו לא קשיא ליה לאביי וי\"ל דמעיקרא נמי קשיא ליה מנקצץ דנקצץ משמע סתמא אחר שיבש בזמנו כמו שדרכו והא דקאמר מה נקצץ בזמנו אף יבש בזמנו משום שרוצה להקשות משניהם אי נמי לא איצטריך אלא לאפוקי דלא נידוק איפכא נקצץ דומיא דיבש כדמשני בתר הכי:"],[9,"נפלו לה זיתים זקנים ימכרו וילקח בהן קרקע ובעל אוכל פירות","אבל לא יקצוץ עצים אלמא קרנא הוי וקשה לאביי דאמר עצים פרי הוי במקום שאין פרי אחר ותימה דמאי פריך דהתם ע\"כ מיירי שעושין קצת פירות מדפליג התם רבי יהודה ואמר לא תמכור מפני שבח בית אביה ומוקי ליה התם בשדה שאינה שלה ואי ליכא פירות כלל מה שבח בית אביה יש הלא בעל השדה לא יניחם לעמוד שם יותר אחר שנתייבשו והבעל יקוץ אותם לעצים וכן משמע נמי מעיקרא דבעי לאוקמי פלוגתייהו בנפלו לה זיתים בשדה שלה ופליגי אבל בשדה שאינה שלה דברי הכל ימכרם ופריך והא עבדים ושפחות זקנים דהוי כנפלו בשדה שאינה שלה ופליגי והנהו עבדים ושפחות ע\"כ כשעושין קצת מלאכה דאי לאו הכי מה מכירה שייך בהם דמי יקנה וה\"נ מיירי דאיכא בזיתים קצת פירי ולכך הוו קרנא אפילו לאביי ולפי שאין עושין אלא פירות מועטין ילקח בהן קרקע ויאכל פירות וזהו טובת שניהם אבל בשמעתין דליכא פרי אז העצים מיקרו פרי לאביי וי\"ל דמ\"מ מוכח שפיר דקרנא הוי אפילו כשיבש לגמרי ולהכי קאמר תנא קמא ילקח בהן קרקע אפילו מעתה שעושין קצת פירות לטובתו של בעל ופליג ארשב\"ג דאמר לא תמכור משום שבח בית אביה ולא חיישינן לטובת הבעל כל זמן שעושין קצת פירות עד שתייבש לגמרי ואז ילקח בהן קרקע אבל לאביי דאמר פרי הוי וכשייבש לגמרי נוטל בעל הבית הכל אם כן אין זה טובת הבעל מה שלקח בהן קרקע ואוכל פירות משלו כי טוב לו יותר להמתין מעט עד שתייבש לגמרי ויהא הכל שלו:"]]],[["ימכרו לעצים וילקח בהן קרקע והוא אוכל פירות אימא והזקינו","ואיבעית אימא לאו מי אוקימנא לההיא כגון שנפלו לה בשדה אחרת דקא כליא קרנא:","ההוא שטרא דהוה כתיב ביה שנין סתמא מלוה אמר שלש לוה אמר שתים קדים מלוה ואכלינהו לפירי מי נאמן רב יהודה אמר קרקע בחזקת בעליה קיימא רב כהנא אמר פירות בחזקת אוכליהן קיימי","והלכתא כוותיה דרב כהנא דאמר פירות בחזקת אוכליהן קיימי והא קי\"ל דהלכתא כוותיה דרב נחמן דאמר קרקע בחזקת בעליה עומדת","התם מילתא דלא עבידא לאיגלויי היא הכא מילתא דעבידא לאיגלויי היא ואטרוחי בי דינא תרי זמני לא מטרחינן","מלוה אומר חמש לוה אומר שלש א\"ל אייתי לי שטרך א\"ל שטרא אירכס לי אמר רב יהודה מלוה נאמן מגו דאי בעי אמר לקוחה היא בידי","א\"ל רב פפא לרב אשי רב זביד ורב עוירא לא סבירא להו הא דרב יהודה מאי טעמא האי שטרא כיון דלגוביינא קאי מיזהר זהיר ביה ומיכבש הוא דכבשיה לשטריה סבר אוכלה תרתין שנין יתירתא","א\"ל רבינא לרב אשי אלא מעתה האי משכנתא דסורא דכתבי הכי במישלם שניא אלין תיפוק ארעא דא בלא כסף היכא דכבשיה לשטר משכנתא ואמר לקוחה היא בידי הכי נמי דמהימן וכי מתקני רבנן מילתא דאתי בה [לידי] פסידא א\"ל התם תקינו ליה רבנן דמרי ארעא יהיב טסקא וכרי כריא","ארעא דלית לה כריא ולא יהיב טסקא מאי א\"ל איבעי ליה למחויי לא אימחא מאי איהו הוא דאפסיד אנפשיה","אריס אומר למחצה ירדתי ובעל הבית אומר לשליש הורדתיו מי נאמן רב יהודה אמר בעל הבית נאמן רב נחמן אמר הכל כמנהג המדינה","סבור מינה לא פליגי הא באתרא דשקיל אריסא פלגא הא באתרא דשקיל אריסא תילתא","אמר להו רב מרי ברה דבת שמואל הכי אמר אביי אפילו באתרא דשקיל אריסא פלגא פליגי רב יהודה אמר בעל הבית נאמן דאי בעי אמר שכירי ולקיטי הוא:","יתומים אומרים אנו השבחנו ובעל חוב אומר אביכם השביח על מי להביא ראיה"],[[0,"ימכרו וכו'","אלמא קרנא הוי דאי פירא הוה הא תקון רבנן פירות לבעל:"],[0,"והזקינו","קפצה עליהן זקנה בלא זמנן:"],[1,"לאו מי אוקימנא","בכתובות בפרק האשה שנפלו לה נכסים (דף עט:):"],[1,"בשדה אחרת","שלא היתה הקרקע שלה שהיו דקלים בשדה של אחרים דהא כליא קרנא דידה לגמרי אי אמרת לישקלינהו בעל לכולהו:"],[2,"ההוא שטרא","שטר משכנתא דסורא במישלם שניא אלין ולא פירש בו מנין השנים:"],[2,"הכי גרסינן וקדים מלוה ואכלינהו לפירי","דשנה שלישית מקמי דנתבעיה לדינא:"],[2,"קרקע בחזקת בעליה עומדת","אע\"ג דלא תבעיה עד לאחר אכילת פירות אנן בתר קרקע אזלינן וכי מספקא לן שנה זו של מי אוקי ארעא בחזקת מריה ושלא כדין אכלינהו לפירי:"],[3,"בחזקת אוכליהן עומדות","כיון דקדים ואכלינהו ואתא לאפוקי מיניה נייתי ראיה דלאו שלש הוו דבתר אכילת פירות אזלינן:"],[3,"והא קי\"ל הלכתא כרב נחמן בדיני","ורב נחמן קרקע בחזקת בעליה עומדת קאמר גבי שוכר מרחץ משנים עשר זהובים לשנה מדינר זהב לחדש בהשואל (לעיל בבא מציעא דף קב:) ואפילו בא בסוף החדש אמר כולו למשכיר כשנתעברה השנה:"],[4,"הני מילי מילתא דלא עבידא לאיגלויי","כלומר בתר קרקע ודאי אית לן למיזל ומיהו הני מילי בספק שאין עומד לעולם להתברר כי ההוא דמספקא לן בין אם תפיס לשון ראשון ואי תפיס לשון אחרון:"],[4,"אבל הכא מילתא עבידא לאיגלויי","בסוף שיבאו עדי שטר ויעידו:"],[4,"ואטרוחי בי דינא תרי זימני","שמא הדין עם המלוה ואם נוציאנו מידו עתידין אנו לחזור ולגבותו מיד הלוה לאחר זמן:"],[5,"מלוה אומר חמש וכו'","מילתא אחריתי היא מלוה ולוה שבאו לדין מלוה אומר חמש שנים מושכנת לי ואין השטר לפנינו ולוה אומר לשלש וכבר אכלת שלש:"],[5,"מגו דאי בעי אמר לקוחה היא בידי","לעולם ואכלתיה שני חזקה ואבד השטר ממני:"],[6,"לא סבירא להו הא דאמר רב יהודה","ולא אמרינן מגו שהדברים מוכיחין שהוא רמאי שאמר אבד השטר והאי שטרא לא דמי לשטר זביני דאילו שטר זביני לעדות שמכרה לו הוא בא וכי עד עולם תאמר לו להזהר בו אמור רבנן ביה עד תלת שנין מצי לאיזדהורי אינש בשטרא טפי לא מיזדהר דקסבר לא יצא עוד ערעור עליה אבל זה שהוא מודה ששטר משכנתא הוא לראיית מנין שנים של אכילת פירות לגוביינא דאכילת פירות דמנין השנים קאי ומיזדהר זהיר ביה דלא לירכס ליה עד כלות השנים והאי דקאמר אירכס לא מהימן דמיכבש הוא דכבשיה וכו':"],[7,"אלא מעתה","אדרב יהודה קפריך דאמר אי בעי אמר לקוחה היא בידי:"],[7,"הכי נמי דמהימן","וכי עביד רבנן מילתא דאתי בה לידי רמאות כי האי:"],[7,"תקון רבנן למרי ארעא דיהיב טסקא","למלכא:"],[7,"וכרי כריא","מתקן החריץ סביבות הגבולים:"],[8,"ואי ארעא קניא הוא","דלית ליה טסקא וכריא נמי לית ליה מאי ליעביד:"],[8,"למחויי","הוו יודעים שלא מכרתיה לו אלא היא משכון בידו:"],[10,"הכי גרסינן הא באתרא דשקיל אריסא פלגא הא באתרא דשקיל אריסא תילתא","ולא גרסינן שתלא בכולי מילתא:"],[11,"שכירי","לימים או לחדשים ושבתות ושכרתיו במעות וכל נאמן דקאמר בשבועת היסת הוא:"],[12,"אנו השבחנו","ואין לבע\"ח במה שהשביחו יתומים כלום:"]],[[7,"א\"ל רבינא לרב אשי משכנתא דסורא אם אמר לקוחה היא בידי ה\"נ דנאמן כו'","אלא ודאי לא מהימן הקשה הרב רבי אלחנן דהא תנן (ב\"ב דף כח.) חזקת הבתים כו' חזקתן ג' שנים ואומר ר\"י דהתם בטוען שמחזיק בה בגזל הויא חזקה שהיה לו למחות תוך שלש כי יודע בודאי כיון שנכנס לה בגזל אם ישתוק לו ג' שנים ולא ימחה שיטעון על ידי ג' שנים שיהיה שלו ולכך היה לו למחות שידוע לכל שתקנו חכמים למחות תוך שלש ואם לא מיחה הפסיד אבל כשבמשכנתא בא לידו סובר המקשה כי לא תקנו חכמים אין לחוש שאחר ג' יטעון שקר וא\"ת אם כן לעולם יהיה בעל הקרקע נאמן לומר שבגזל הוא בא מגו דאי בעי אמר במשכנתא היה אצלך או לפירות הורדתיך וי\"ל דהוי מגו במקום עדים דאנן סהדי אם היה בא בגזל לא היה שתיק אלא היה מוחה אי נמי אין זה מגו שאין טוען ברצון משכנתא היה או לפירות הורדתיך לפי שסבור להוציא גם הפירות שכבר אכל אי נמי חשיב מגו להוציא כיון שאכלה שני חזקה וקשה דטעמא דבשלש שנים הויא חזקה משום דעד שלש שנים מיזדהר איניש בשטריה טפי לא מיזדהר והשתא הלא ע\"כ צריך לשמור לעולם כי שמא יטעון זה משכנתא היא וע\"כ נראה דלא בעי למימר שלא יהא נאמן [לומר] לקוחה היא בידי אלא שואל מה תקנה יעשה הממשכן שלא יוכל להחזיק ולטעון לקוחה היא בידי דמחאה נראה דלא מהניא אלא כשאומר פלניא אכיל ארעאי בגזלנותא ומשני רב אשי דאיבעי ליה למחויי ולומר תוך שלשה דעו כי משכנתא היא בידו דחשיבא שפיר מחאה בכי האי גוונא וכי האי גוונא יש לפרש בפ' חזקת הבתים (בבא בתרא דף לה: ושם) גבי ואי טעין ואמר לפירות הורדתיך נאמן ואף על גב דהתם רב אשי פריך לרב כהנא ואי לפירות אחתיה מאי הוה ליה למיעבד ורב כהנא משני דאיבעי ליה למחויי ומייתי ראיה ממשכנתא דסורא ובשמעתין רב אשי משני איבעי ליה למחויי וכן משני רב אשי התם בההוא פירקא (דף לח.) גבי האי מאן דזבין דקלא לחבריה איכא למימר דרב אשי התם קיבל שינויא מרב כהנא ולהכי משני ליה איהו נמי הכי:"],[7,"האי משכנתא דסורא כו'","אע\"ג דהא גופא דהכא אפשר דמשכנתא דסורא הוי שייך שפיר לאקשויי בהאי לישנא לפי שמשכנתא דסורא הוה קים ליה שתקנו חכמים לעשות להכי קאמר אלא מעתה תקנת משכנתא דסורא וכו':"]]],[["סבר רבי חנינא למימר ארעא בחזקת יתמי קיימא ועל בעל חוב להביא ראיה אמר להו ההוא סבא הכי א\"ר יוחנן על היתומים להביא ראיה מאי טעמא ארעא כיון דלגוביינא קיימא כמאן דגביא דמיא ועל היתומין להביא ראיה","אמר אביי אף אנן נמי תנינא ספק זה קדם וספק זה קדם קוצץ ואינו נותן דמים","אלמא כיון דלמיקץ קיימא אמרינן ליה אייתי ראיה ושקול הכא נמי האי שטרא כיון דלגוביינא קיימא כמאן דגביא דמיא ועל היתומים להביא ראיה","אייתו יתמי ראיה דאינהו אשבחו סבר רבי חנינא למימר כי מסלקינן להו בארעא מסלקינן להו","ולא היא בדמי מסלקינן להו מדרב נחמן דאמר רב נחמן אמר שמואל שלשה שמין להם את השבח ומעלין אותן בדמים ואלו הן בכור לפשוט","ובעל חוב וכתובת אשה ליתומים ובעל חוב ללקוחות","א\"ל רבינא לרב אשי למימרא דסבר שמואל בעל חוב ללקוחות ומי אית ליה שבחא ללוקח והאמר שמואל בעל חוב גובה את השבח וכי תימא לא קשיא כאן בשבח המגיע לכתפים כאן בשבח שאין מגיע לכתפים והא מעשים בכל יום וקא מגבי שמואל אפי' בשבח המגיע לכתפים","לא קשיא הא דמסיק ביה כשיעור ארעא ושבחא הא דלא מסיק ביה שיעור ארעא ושבחא","וכי לא מסיק שיעור ארעא ושבחא דיהיב ליה זוזי ללוקח ומסלק ליה הניחא למ\"ד אי אית [ליה] זוזי ללוקח לא מצי מסלק ליה לבעל חוב שפיר אלא למ\"ד אית ליה זוזי ללוקח מצי מסלק ליה לבעל חוב ונימא ליה אי הוו לי זוזי הוה מסליקנא לך מכולא ארעא השתא דלית לי זוזי הב לי גריוא דארעא בארעאי שיעור שבחאי","הכא במאי עסקינן כגון דשויא ניהליה אפותיקי דא\"ל לא יהא לך פרעון אלא מזו:","\u0001מתני׳\u0002 המקבל שדה מחבירו לשבוע אחד בשבע מאות זוז השביעית מן המנין קבלה הימנו שבע שנים בשבע מאות זוז אין השביעית מן המנין","שכיר יום גובה כל הלילה שכיר לילה גובה כל היום שכיר שעות גובה כל הלילה וכל היום שכיר שבת שכיר חדש שכיר שנה שכיר שבוע יצא ביום גובה כל היום יצא בלילה גובה כל הלילה וכל היום:","\u0001גמ׳\u0002 ת\"ר מנין לשכיר יום שגובה כל הלילה ת\"ל (ויקרא יט, יג) לא תלין פעולת שכיר אתך עד בקר ומנין לשכיר לילה שגובה כל היום שנאמר (דברים כד, טו) ביומו תתן שכרו","ואימא איפכא שכירות אינה משתלמת אלא בסוף","ת\"ר ממשמע שנאמר לא תלין פעולת שכיר אתך איני יודע שעד בקר מה ת\"ל עד בקר מלמד שאינו עובר אלא עד בקר ראשון בלבד","מכאן ואילך מאי אמר רב עובר משום בל תשהא אמר רב יוסף מאי קראה (משלי ג, כח) אל תאמר לרעך לך ושוב ומחר אתן ויש אתך","ת\"ר האומר לחבירו צא שכור לי פועלים שניהן אין עוברין משום בל תלין זה לפי שלא שכרן"],[[1,"ספק","בבבא בתרא (דף כד:) באילן הנטוע בתוך חמשים אמה סמוך לעיר וקתני התם אם העיר קדמה קוצץ ואינו נותן דמים ספק זה קדם ספק זה קדם קוצץ ואינו נותן דמים אלמא כיון דבין הכי ובין הכי למקצץ קאי דכי קדם אילן נמי קתני קוצץ כי מספקא לן אמרינן קוץ ממה נפשך שהרי עליך לעשות נמצא הספק מוטל על הדמים ולא על קציצת האילן דאילו גבי אילן הסמוך לבור של יחיד קתני בה גבי ודאי דידיה אם הבור קדמה קוצץ ונותן דמים אם האילן קדם לא יקוץ תנן גבי ספק זה קדם וספק זה קדם לא יקוץ אלמא גבי ספק אילן דעיר טעמא משום דממה נפשך עומד לקציצה והכא נמי בין יתומים השביחו ובין אביהן השביח דינו ליטול קרקע עם השבח ואם היתומים השביחו מעלה להן השבח בדמים כדלקמיה הלכך גבי ארעא עם השבח ממה נפשך נמצא היתומים תובעין להוציא ממנו ועליהן הראיה:"],[3,"בארעא מסלקינן להו","יהבינן להו גריוא דארעא שיעור שבחייהו:"],[4,"ומעלין אותן","מן הקרקע:"],[4,"בדמים","ולא שקלי בארעא גופיה:"],[4,"בכור לפשוט","בכור ופשוט שהשביחו קרקע קודם שחלקו וקי\"ל (ב\"ב דף קכד.) שאין הבכור נוטל פי שנים בשבח שהשביחו נכסים לאחר מיתת אביהן דהוה ליה ראוי ואין הבכור נוטל הבכורה בראוי דכתיב בכל אשר ימצא לו וכשהן באין לחלוק נוטל בכור פי שנים בקרקע שהיא משובחת ושמין את השבח ונותן לפשוט רביע שהוא מגיע לו בשבח שבתוך חלקו של זה:"],[6,"וכן בעל חוב ליתומין","וכן בעל חוב שקדם שטר הלואתו לשטר מקח של לקוחות טורפה מהן עם מה שהשביחו ושם להן שבח ונותן דמים וטעמא דכולהו משום דמעיקרא ארעא דידיה הוא ואין לנו לכופו למכור להן קרקע שלו בשביל השבח אם יש בידו מעות ולקמן מוקי לה בקרקע שנעשית לו אפותיקי:"],[6,"המגיע לכתפים","צריכין לקרקע דבר מועט דאילו אין צריכין לקרקע הוו להו פירות ולא מיקרו שבח ובעל חוב גובה השבח קאמר ולא פירות גמורין כדאמרינן בפ\"ק:"],[8,"הניחא למ\"ד","פלוגתא במסכת כתובות (בהכותב):"],[8,"אי אית ליה זוזי ללוקח","שיעור דמי החוב:"],[8,"שפיר","איכא למימר דארעא מעיקרא דידיה הואי והוא דנחת לה שלא ברשות שקל שבחא בזוזי ולא בארעא הואיל והוה מסיק ביה שיעור ארעא כוליה:"],[11,"מתני' שכיר יום גובה כל הלילה","שכיר שפעולתו ליום ויוצא לערב גובה כל הלילה כל הלילה הוא זמן גבייתו בין לענין שבועה שתקנו לו חכמים שכיר בזמנו הוא נשבע ונוטל בין לענין שאינו עובר עליו משום לא תבוא עליו השמש (דברים כ״ד:ט״ו) אלא משום לא תלין פעולת שכיר אתך עד בקר (ויקרא י״ט:י״ג):"],[11,"שכיר לילה","שיוצא ממלאכתו בבוקר:"],[11,"גובה כל היום","בין לענין שבועה ובין לענין שאינו עובר עליו משום בל תלין אלא משום לא תבא עליו השמש ובגמרא יליף לה:"],[11,"שכיר שעות","גובה כל היום וכל הלילה אמוראי מפרשי לה בגמרא:"],[11,"שכיר שבוע","שמיטה:"],[11,"יצא ביום","שכלתה שכירותו לבוקר או ביום:"],[11,"גובה כל היום","וכיון ששקעה חמה עובר עליו:"],[11,"יצא בלילה","שכלתה שכירותו בלילה:"],[11,"גובה כל הלילה וכל היום","דכיון דמשכה פעולתו משתחשך הוה ליה שכיר לילה ואינו עובר עליו בבוקר עד למחרת בשקיעת החמה:"],[13,"גמ' איפוך אנא","דלא תלין בשכיר לילה לא תבא בשכיר יום:"],[13,"שכירות אינה משתלמת אלא בסוף","כדאמר באיזהו נשך (לעיל בבא מציעא סה.) כשכיר שנה בשנה שכירות שנה זו משתלמת בתחילת שנה אחרת אלמא לא משתעבד ליה לשכיר יום עד שתשקע החמה וכי כתיב לא תבא על כרחך בשכיר לילה תוקמיה שנשתעבד לו לבוקר משכלתה שכירותו וכן לא תלין נמי לא תוקמיה בשכיר לילה דהא לא משתעבד ליה עד הבוקר:"],[14,"ממשמע שנאמר וכו'","שאין לינה קרויה אלא עד הבוקר דכתיב (שמות ל״ד:כ״ה) ולא ילין לבקר וכל לינה שבמקרא לינת לילה הוא:"],[15,"מאי קראה","היכא רמיזא בל תשהא:"],[16,"זה לפי שלא שכרו","ולא קרינא שכיר גביה:"]],[[0,"סבר ר' חנינא למימר בארעא מסלקינן להו","תימה כיון דטעמא דעל היתומין להביא ראיה משום שהקרקע בחזקת בעל חוב והיינו כשעשה אפותיקי כדמסיק א\"כ הוה ליה כיורד לתוך שדה חבירו ונטעה שלא ברשות דפשיטא דלא שקיל מגוף הקרקע את השבח וי\"ל דכיון שהיה הקרקע בחזקת אביהם תחלה ועדיין לא יצאת מרשותן עדיפי מיורד לתוך שדה חבירו ונטעה שלא ברשות א\"נ ביורד לתוך שדה חבירו נמי היה סבור דמסלקינן ליה בארעא:"],[11,"יצא בלילה גובה כל הלילה וכל היום","וכן ברישא בשכיר שעות דלילה אע\"פ שיצא ממלאכתו ועוד לילה גובה כל היום ואינו עובר בבל תלין בעמוד השחר דלינה משמע כל הלילה וזה השכירות לא לן כל הלילה וא\"ת לא ילין דחלב חגי (שמות כ״ג:י״ח) הוא בעמוד השחר גרידא שאם העלה אימורים על גבי המזבח בתחילת הלילה והורידן לפני עמוד השחר נפסלין בלינה כדאמרינן בזבחים (דף פו.) וי\"ל מפני שהן ראוין להקריב בתחילת הלילה קרינא ביה לינה אפילו בעמוד השחר ודוחק ועוד דבפרק שני דזבחים (דף כ:) משמע גבי קידוש ידים ורגלים ומי כיור דעמוד השחר פוסל בלינה אפילו לא התחיל לינה אלא לאחר תחילת הלילה:"]]],[["וזה לפי שאין פעולתו אצלו היכי דמי אי דאמר להו שכרכם עלי שכרו עליו הוא דתניא השוכר את הפועל לעשות בשלו והראהו בשל חבירו נותן לו שכרו משלם וחוזר ונוטל מבעל הבית מה שההנה אותו","לא צריכא דאמר להו שכרכם על בעל הבית","יהודה בר מרימר א\"ל לשמעיה זיל אגיר לי פועלים ואימא להו שכרכם על בעל הבית מרימר ומר זוטרא אגרי להדדי","אמר רבה בר רב הונא הני שוקאי דסורא לא עברי משום בל תלין מידע ידעי דעל יומא דשוקא סמיכי אבל משום בל תשהא ודאי עובר:","שכיר שעות גובה כל הלילה וכל היום: אמר רב שכיר שעות דיום גובה כל היום שכיר שעות דלילה גובה כל הלילה ושמואל אמר שכיר שעות דיום גובה כל היום ושכיר שעות דלילה גובה כל הלילה וכל היום","תנן שכיר שעות גובה כל הלילה וכל היום תיובתא דרב אמר לך רב לצדדין קתני שכיר שעות דיום גובה כל היום שכיר שעות דלילה גובה כל הלילה","תנן היה שכיר שבת שכיר חדש שכיר שנה שכיר שבוע יוצא ביום גובה כל היום יוצא בלילה גובה כל הלילה וכל היום","אמר לך רב תנאי היא דתניא שכיר שעות דיום גובה כל היום שכיר שעות דלילה גובה כל הלילה דברי ר' יהודה ר\"ש אומר שכיר שעות דיום גובה כל היום שכיר שעות דלילה גובה כל הלילה וכל היום","מכאן אמרו כל הכובש שכר שכיר עובר בה' שמות הללו ועשה משום (ויקרא יט, יג) בל תעשוק את ריעך ומשום (ויקרא יט, יג) בל תגזול ומשום (דברים כד, יד) בל תעשוק שכיר עני ומשום (ויקרא יט, יג) בל תלין ומשום (דברים כד, טו) ביומו תתן שכרו ומשום (דברים כד, טו) לא תבא עליו השמש","הני דאיכא ביממא ליכא בליליא דאיכא בליליא ליכא ביממא אמר רב חסדא שם שכירות בעלמא","איזה הוא עושק ואיזהו גזל א\"ר חסדא (משלי ג, כח) לך ושוב לך ושוב זה הוא עושק יש לך בידי ואיני נותן לך זה הוא גזל","מתקיף לה רב ששת איזהו עושק שחייבה עליו תורה קרבן דומיא דפקדון דקא כפר ליה ממונא אלא אמר רב ששת נתתיו לך זהו עושק יש לך בידי ואיני נותן לך זה הוא גזל","מתקיף לה אביי איזה הוא גזל שחייבה עליו תורה קרבן דומיא דפקדון בעינן דקא כפר ליה ממונא אלא אמר אביי לא שכרתיך מעולם זה הוא עושק נתתיו לך זה הוא גזל","ולרב ששת מאי שנא עושק דקשיא ליה ומאי שנא גזל דלא קשיא ליה אמר לך גזל דגזליה והדר כפריה","אי הכי אפילו עושק נמי דהדר כפריה הכי השתא בשלמא התם כתיב (ויקרא ה, כא) או בגזל מכלל דאודי ליה מעיקרא אבל גבי עושק מי כתיב או בעושק (ויקרא ה, כא) או עשק כתיב שעשקו כבר","רבא אמר זה הוא עושק זהו גזל ולמה חלקן הכתוב לעבור עליו בשני לאוין:","\u0001מתני׳\u0002 אחד שכר אדם ואחד שכר בהמה ואחד שכר כלים יש בו משום (דברים כד, טו) ביומו תתן שכרו ויש בו משום לא תלין פעולת שכיר אתך עד בוקר אימתי בזמן שתבעו לא תבעו אינו עובר עליו המחהו אצל חנוני או אצל שולחני אינו עובר עליו","שכיר בזמנו נשבע ונוטל עבר זמנו אינו נשבע ונוטל אם יש עדים שתבעו (בזמנו) הרי זה נשבע ונוטל","גר תושב יש בו משום ביומו תתן שכרו ואין בו משום לא תלין פעולת שכיר אתך עד בקר:","\u0001גמ׳\u0002 מני מתני' לא תנא קמא דמאחיך ולא רבי יוסי ברבי יהודה מאי היא דתניא"],[[0,"וזה לפי שאין פעולתו עליו","ולא קרינא ביה פעולתו אתך:"],[2,"ואימא להו וכו'","דאי לא משתלימנא לא עברנא:"],[2,"אגרי להדדי","כשהיה האחד צריך לפועלים חבירו פוסק עמהן ואמר להן שכרכם על בעל הבית:"],[3,"הני שוקאי דסורא","בעלי בתים של סורא שאין מגיעין למעות עד יום השוק:"],[3,"לא עברי","על שכר פועלין:"],[3,"מידע ידעי דעל יומא דשוקא סמכי","להגיע למעות הלכך אפילו אית ליה מעות גביה לא עבר דאדעתא דהכי איתגר ליה וכיון דמיומא קמא לא עברי תו לא עברי כדאמרינן לעיל שאינו עובר עליו אלא בקר ראשון:"],[3,"אבל משום בל תשהא עובר","מיום השוק ואילך:"],[4,"שכיר שעות דיום","שנשכר לו מן הבקר עד חצות:"],[4,"גובה כל היום","דהא כלתה שכירתו מחצות ואיכא בלא תבא:"],[4,"שכיר שעות דלילה גובה כל הלילה","ולכשיעלה עמוד השחר עובר משום בל תלין דהא נשתעבד לו קודם לכן:"],[4,"ושמואל אמר שכיר שעות דיום הוא גובה כל היום","כדקאמרת ואין לילה הולך אחר יום אבל שכיר שעות דלילה גובה כל הלילה וכל היום שהיום הולך אחר הלילה הואיל ושכירותו בליל יום זה לא דמי לשכיר יום דאתמול שאינו גובה אלא כל הלילה:"],[5,"תנן שכיר שעות גובה כל הלילה וכל היום","בשלמא שמואל מוקי לה בשכירות שעות דלילה אלא רב במאי מוקי לה:"],[5,"לצדדין","והכי קאמר שכיר שעות יש שגובה כל הלילה ויש שגובה כל היום וכדאמרי אנא:"],[6,"יצא בלילה וכו'","אלמא הואיל ומשכה פעולתו בלילה הוה ליה שכיר שעות דלילה וקתני גובה כל הלילה וכל היום:"],[6,"משום לא תגזול","דהא אוקמיה באיזהו נשך (דף סא.) לכובש שכר שכיר דאי גזל ממש מלאו דריבית ואונאה נפקא:"],[8,"ה' שמות","חמשה לאוין לא תעשוק את רעך ולא תגזול ולא תלין ולא תעשוק שכיר עני ואביון ביומו תתן שכרו ולא תבוא עליו השמש ועשה ביומו תתן:"],[9,"שם שכירות","כולהו בחד ודאי לא משכחת לה אלא הכי קאמר עבירות כל השמות הללו בשם שכירות הן יש מהן בשכירות לילה ויש מהן בשכירות יום:"],[10,"גזל","משמע שאנסו בידו מידו ממש טפי מעושק דכתיב (שמואל ב כ״ג:כ״א) ויגזול את החנית מיד המצרי וכן (שופטים ט׳:כ״ה) בבעלי שכם ויגזלו את כל אשר יעבור עליהם בדרך:"],[11,"מתקיף לה רב ששת","על כרחיך עושק דקא כפר ליה הוא מדחייביה עליו בתורת כהנים קרבן שבועה דכתיב (ויקרא ה׳:כ״א) וכחש בעמיתו בפקדון או בתשומת יד וגו':"],[11,"אלא אמר רב ששת וכו'","לקמן פריך לרב ששת מאי שנא עושק דקשיא ליה ומ\"ש גזל דלא קשיא ליה:"],[12,"לא שכרתיך מעולם","לא דמי לגזל כי נתתיו לך דהא מודי ליה דעבד בהדיה וקא גזל ליה:"],[13,"מ\"ש גזל דלא קשיא ליה","הא איהו נמי גבי קרבן שבועה כתיב ואי לא כפר שבועה היכא:"],[13,"דגזליה והדר כפריה","כל זמן שלא תבעו בבית דין אלא בינו לבין עצמו היה גוזלו ואומרו איני נותן לך וכשתבעו בב\"ד כפר ונשבע ולעולם גזל לא איקרי אלא א\"כ אומר לו איני נותן לך:"],[14,"אי הכי עושק נמי","נוקמיה כרב חסדא בלך ושוב ודקשיא לך שבועה היכא כגון דהדר כפריה:"],[14,"הכי גרסינן הכי השתא בשלמא התם או בגזל","כתיב וכחש השתא מכלל דאודי ליה מעיקרא כלומר וכחש בעמיתו בגזל במה שהיה גוזלו עד עתה בתורת גזל כחש עכשיו וכפר ומקודם כחש קרוי גזל:"],[14,"אבל הכא מי כתיב או בעושק","דנימא וכחש בעושק דמעיקרא:"],[14,"או עשק כתיב","על ידי הכחשה עשקו:"],[14,"שעשקו כבר","משעה שהתחיל לתובעו עושקו בכחישה ולא נקרא עשק על ידי דבר אחר קודם כחישה:"],[16,"מתני' שכר בהמה וכלים","יליף בגמרא:"],[16,"לא תבעו אינו עובר עליו","בגמרא יליף ליה דכתיב אתך מדעתך ולא מדעתו:"],[16,"המחהו","נתקן מאצלו והעמידו אצל חנוני שהיה פועל צריך לקנות פירות מחנוני ואמר לו בעל הבית לחנוני תן לו בדינר פירות ועלי לשלם:"],[16,"או אמר לשולחני","תן לו בדינר מעות:"],[17,"נשבע ונוטל","מפרש בגמרא:"],[17,"ואם יש עדים שתבעו","בזמנו:"],[18,"גר תושב","שקבל עליו שלא לעבוד עבודה זרה ואוכל נבילות וטריפות:"],[18,"יש בו משום וכו'","מפרש בגמרא:"]],[[2,"אמר ליה לשמעיה זיל אגיר לי פועלים","לא משום שהיה דעתו לדחות אלא היה ירא שלא יהא פנוי ליתן להם ואפילו משום בל תשהא לא היה עובר כיון שהוא עסוק במלאכה אחרת:"],[12,"מתקיף לה אביי איזהו גזל כו'","תימה וכי לא ידע אביי דרב ששת מוקי לה באודי ליה והדר כפריה וי\"ל דסבר אביי דאית לן לאוקמי גזל דומיא דעשק וכי היכי דלא קאי וכחש אעושק לא קאי נמי אגזל אלא תחילת גזל דקרא ותחילת עושק הוא כיחש ולא דייק כדדייק רב ששת בסמוך דהכא כתיב או בגזל והכא כתיב או עשק בלא בי\"ת:"],[14,"או עשק כתיב","לא גרסינן שעשקו כבר:"],[15,"ולמה חלקן הכתוב לעבור עליו בשני לאוין","לאו משום דכתיב גזל ועשק ששינה בלשון דייק אלא משום דכתיב תרי לאוין תימה בשלמא הכא חילקן כדי לעבור עליו בשני לאוין אבל גבי אשם גזילות למה נכתבו שניהם או בגזל או עשק:"]]],[["מאחיך פרט לאחרים גרך זה גר צדק בשעריך זה אוכל נבילות","אין לי אלא שכר אדם מנין לרבות בהמה וכלים ת\"ל בארצך כל שבארצך וכולן עוברים בכל השמות הללו","מכאן אמרו אחד שכר אדם ואחד שכר בהמה ואחד שכר כלים יש בו משום ביומו תתן שכרו ויש בהן משום בל תלין פעולת שכיר רבי יוסי ברבי יהודה אומר גר תושב יש בו משום ביומו תתן שכרו ואין בו משום לא תלין בהמה וכלים אין בהן אלא משום בל תעשק בלבד","מני אי תנא קמא דמאחיך קשיא גר תושב אי רבי יוסי קשיא בהמה וכלים","אמר רבא האי תנא תנא דבי ר' ישמעאל הוא דתנא דבי ר' ישמעאל אחד שכר אדם ואחד שכר בהמה ואחד שכר כלים יש בו משום ביומו תתן שכרו ומשום לא תלין גר תושב יש בו משום ביומו תתן שכרו ואין בו משום בל תלין","מ\"ט דת\"ק דמאחיך גמר שכיר שכיר ורבי יוסי ברבי יהודה לא גמר שכיר שכיר","נהי דלא גמר שכיר שכיר בהמה וכלים משום ביומו תתן שכרו נמי ניחייב תני רבי חנניא אמר קרא ולא תבא עליו השמש כי עני הוא מי שהן באין לידי עניות ועשירות יצאו בהמה וכלים שאינן באין לידי עניות ועשירות","ות\"ק האי כי עני הוא מאי עביד ליה ההוא מיבעי להקדים עני לעשיר ורבי יוסי ברבי יהודה ההוא מלא תעשק שכיר עני ואביון נפקא","ות\"ק חד להקדים עני לעשיר וחד להקדים עני לאביון","וצריכא דאי אשמעינן אביון משום דלא כסיף למתבעיה אבל עשיר דכסיף למתבעיה אימא לא ואי אשמעינן עשיר משום דלא צריך ליה אבל אביון דצריך ליה אימא לא צריכא","ותנא דידן מה נפשך אי יליף שכיר שכיר אפילו גר תושב נמי אי לא יליף שכיר שכיר בהמה וכלים מנא ליה","לעולם לא יליף שכיר שכיר ושאני התם דאמר קרא ולא תלין פעולת שכיר אתך עד בקר כל שפעולתו אתך אי הכי אפילו גר תושב נמי אמר קרא רעך רעך ולא גר תושב","אי הכי אפילו בהמה וכלים נמי הא כתיב אתך מה ראית לרבות בהמה וכלים ולהוציא גר תושב מסתברא בהמה וכלים הוה ליה לרבות שכן ישנן בכלל ממון רעך גר תושב אינו בכלל ממון רעך","ות\"ק דמאחיך האי רעך מאי עבדי ליה ההוא מיבעי ליה לכדתניא רעך ולא עמלקי עמלקי מאחיך נפקא","חד למשרא עושקו וחד למשרא גזלו וצריכי דאי אשמעינן גזלו משום דלא טרח ביה אבל עושקו דטרח גביה אימא לא ואי אשמעינן עושקו משום דלא אתא לידיה אבל גזלו דאתא לידיה אימא לא צריכא","ורבי יוסי ברבי יהודה האי לא תלין פעולת שכיר אתך עד בקר מאי עביד ליה מיבעיא ליה לכדרב אסי דאמר רב אסי אפילו לא שכרו אלא לבצור לו אשכול אחד של ענבים עובר משום בל תלין","ואידך מואליו הוא נושא את נפשו נפקא דבר המוסר נפשו עליו"],[[0,"מאחיך","לא תעשוק שכיר עני ואביון מאחיך:"],[0,"פרט לאחרים","עובד כוכבים:"],[0,"זה גר אוכל נבילות","דכתיב ביה שעריך (דברים י״ד:כ״א) לגר אשר בשעריך תתננה ואכלה:"],[1,"וכולן","על שכר ישראל ועל שכר בהמה וכלים וגר וגר תושב:"],[1,"עובר בכל השמות הללו","בין הכתובים כאן ובין האמורים בתורת כהנים דיליף גזירה שוה לאיתויינהו הכא כדלקמן:"],[2,"ויש בהם משום בל תלין","האמור בתורת כהנים והוא הדין ללא תעשוק ולא תגזול דכתיב גביה ומיהו של שכיר יום ליתיה בשכיר לילה:"],[2,"ר' יוסי בר' יהודה וכו'","לקמן מפרש לה:"],[2,"אין בהם אלא משום לא תעשוק שכיר וגומר","דכתיב ביה בארצך דמרבי בהמה וכלים אבל ביומו תתן שכרו אע\"ג דסמיך ליה לא ולקמן מפרש טעמא:"],[3,"קשיא גר תושב","דמתניתין תנן אין בו משום בל תלין האמור בתורת כהנים ובברייתא קתני כולן עוברים בכל השמות הללו:"],[3,"קשיא בהמה וכלים","דקתני מתני' יש בהם משום ביומו תתן שכרו ומשום לא תלין ור' יוסי בר' יהודה סבר אין בהן אלא משום לא תעשוק דמשנה תורה ואפילו משום ביומו וגו' דסמיך ליה לא:"],[4,"גר תושב יש בו משום ביומו תתן שכרו","וכל שכן משום לא תעשוק שכיר דבגויה כתיב בשעריך:"],[4,"ואין בו משום לא תלין","דתורת כהנים וכן משום לא תעשוק ולא תגזול דת\"כ והאי דנקט הני משום דמפרשי בהו שכיר יום ושכיר לילה וה\"ק יש בו משום ביומו תתן שכרו דמשתעי גבי שכיר לילה ואין בו משום שכיר יום:"],[5,"גמר שכיר שכיר","כתיב הכא לא תעשוק שכיר וכתיב בשכיר יום לא תלין פעולת שכיר מה כאן גר תושב בהמה וכלים איתרבאי אף בת\"כ נמי גר תושב בהמה וכלים:"],[5,"לא גמר","הלכך דתורת כהנים ליתנהו לא בבהמה וכלים ולא בגר תושב:"],[6,"משום דביומו תתן שכרו","ליחייב דהך סמיך ליה דבקרא דלעיל כתיב מארצך:"],[7,"להקדים עני לעשיר","נשכרו שני פועלין אחד עני ואחד עשיר ואין בידו ליתן אלא לאחד מהן העני קודם:"],[7,"אביון","מעונה מעני ולשון אביון האובה ואינו משיג מה שנפשו מתאוה לכל טוב ואשמעינן קרא דעני קודם לאביון משום דעני כסיף למיתבעיה אף על גב דצריך:"],[9,"ואי אשמועינן עשיר","דלקדמיה עני משום דלא צריך ליה העשיר לשכר כמו העני:"],[9,"אבל אביון","הורגל לבושת ולא כסיף למיתבעיה:"],[9,"אבל אביון דצריך ליה","טפי מעני אימא דליקדמיה לעני קמ\"ל דעני קודם דצריך ליה וכסיף למיתבעיה:"],[10,"ותנא דידן","וכן דבי רבי ישמעאל דאמרו תרוייהו בהמה וכלים אכולהו וגר תושב לית להו דת\"כ אי גמיר ג\"ש אפילו גר תושב נמי ליחייביה משום שכיר יום:"],[11,"אתך","קרא יתירא הוא:"],[11,"שפעולתו אתך","ואפילו בהמה וכלים:"],[11,"רעך","בהנך דתורת כהנים כתיב לא תעשק את רעך:"],[14,"עשקו","שכר שכיר:"],[14,"גזלו","גזילה ממש:"],[15,"ור' יוסי האי אתך מאי עביד ליה","דמרבי מיניה תנא דידן בהמה וכלים אף על גב דגזרה שוה לא גמיר:"],[15,"אלא לבצור אשכול אחד","כלומר שכיר שעות:"],[16,"מואליו הוא נושא את נפשו","כל ששיעבד עצמו עליו:"]],[[0,"מאחיך פרט לאחרים","תימה אמאי איצטריך מאחיך למעוטי עכו\"ם מגר תושב נפקא דדוקא גר תושב ולא עכו\"ם ועוד תימה אמאי איצטריך למיכתב גר צדק מגר תושב נפקא דכ\"ש גר צדק וליכא למימר דאי לאו דכתיב גר צדק הוה מוקמינן בשעריך לגר צדק דבשעריך לא משמע אלא גר תושב שאוכל נבילות דומיא (דברים י״ד:כ״א) דלגר אשר בשעריך תתננה ואכלה:"],[0,"מגרך זה גר צדק","תימה אמאי איצטריך למימר גר צדק דמאחיך נפקא דגר צדק אחיך לכ\"ע לרבי יהודה ולרבנן דפליגי בהחובל (ב\"ק דף פז. ושם) גבי אין לעבדים בושת דיש לו אחוה ואחיך הוא במצות וי\"ל דשאני הכא דכתיב מאחיך דמשמע ממובחר שבאחיך כדדרשינן ב\"ק (דף פח.) מקרב אחיך אי נמי מאחיך ולא כל אחיך כדדרשינן קדושין (דף כד:) מן העוף ולא כל העוף והוה ממעטינן גר אי לאו דכתיב גרך אבל באיזהו נשך (לעיל בבא מציעא דף עא.) גבי רבית דדריש גר זה גר צדק קשיא לר\"י אמאי איצטריך פשיטא דמה לי ישראל מה לי גר צדק וכי בכל המצות אין גר צדק בכלל ישראל וכן קשה דזימנין כתיב לאזרח ולגר וזימנין דלא כתיב ומ\"ש:"],[1,"כל שבארצך","ולא מוקמינן ליה למעוטי חוצה לארץ דחובת הגוף היא ואינה תלויה בארץ:"],[7,"ורבי יוסי ברבי יהודה לא יליף שכיר שכיר","ובפ\"ק דקדושין (דף יד: ושם) דלא משכח תנא דלא יליף שכיר שכיר היינו דוקא גבי עבד עברי משום דסבר דההוא דהכא לא מופנה והאי מופנה:"],[14,"ואי אשמעינן גזל משום דלא טרח","לא הוה צריך להאי צריכותא דאי לא כתיב אלא חד אפילו לא תגזול הוה מוקמינן לה בעושק דמשתעי ביה קרא כדאמר באיזהו נשך (לעיל בבא מציעא סא. ושם ד\"ה לעבור) אבל השתא דכתיבי תרוייהו מוקמינן לה בגזל עובד כוכבים באם אינו ענין אלא משום דמשכח צריכותא אפי' מיעטיה בהדיא מגזל לא הוה שמעינן עשק :"],[15,"ורבי יוסי בר' יהודה האי לא תלין אתך מאי עביד ליה","תימה דבסמוך בברייתא דריש מיניה כמה דרשות ומצאתי כתוב כמדומה בתוס' רבינו אלחנן דהכא משכיר קבעי מאי עביד ליה דהוי ליה למיכתב לא תלין פעולתו אתך:"],[15,"לבצור אשכול אחד","היינו שכיר שעות נראה לר\"י דאיצטריך למיכתב משום דשכיר משמע שכיר יום או חצי יום שאין רגילות להשכיר פועלים אלא ליום או לחצי יום אבל לכל דהו לא אי נמי איצטריך לאשמועינן דאפילו שכרו לבצור אשכול אחד ואכלו אפילו הכי עובר עליו:"]]],[["ואידך ההוא מיבעי ליה לכדתניא (דברים כד, טו) ואליו הוא נושא את נפשו מפני מה עלה זה בכבש ונתלה באילן ומסר את עצמו למיתה לא על שכרו","דבר אחר ואליו הוא נושא את נפשו כל הכובש שכר שכיר כאילו נוטל נפשו ממנו רב הונא ורב חסדא חד אמר נפשו של גזלן וחד אמר נפשו של נגזל","מאן דאמר נפשו של גזלן דכתיב (משלי כב, כב) אל תגזל דל כי דל הוא ואל תדכא עני בשער וכתיב (משלי כב, כג) כי ה' יריב ריבם וקבע את קבעיהם נפש ומ\"ד נפשו של נגזל דכתיב (משלי א, יט) כן ארחות כל בוצע בצע את נפש בעליו יקח","ואידך נמי הכתיב את נפש בעליו יקח בעליו דהשתא ואידך נמי הכתיב וקבע את קבעיהם נפש מה טעם קאמר מה טעם קבע את קבעיהם משום דנטלו נפש:","אימתי בזמן שתבעו לא תבעו אינו עובר עליו: ת\"ר לא תלין פעולת שכיר יכול אפילו לא תבעו ת\"ל אתך לדעתך","יכול אפי' אין לו ת\"ל אתך שיש אתך יכול אפי' המחהו אצל חנוני ואצל שולחני ת\"ל אתך ולא שהמחהו אצל חנוני ואצל שולחני:","המחהו אצל חנוני ואצל שולחני אינו עובר: איבעיא להו חוזר או אינו חוזר רב ששת אמר אינו חוזר ורבה אמר חוזר","אמר רבה מנא אמינא לה מדקתני אינו עובר עליו מעבר הוא דלא עבר הא מיהדר הדר ורב ששת אמר מאי אינו עובר אינו בתורת לעבור:","בעו מיניה מרב ששת קבלנות עובר עליו משום בל תלין או אין עובר משום בל תלין","אומן קונה בשבח כלי והלואה היא או אין אומן קונה בשבח כלי ושכירות היא","אמר להו רב ששת עובר והתניא אינו עובר התם שהמחהו אצל חנוני ואצל שולחני","נימא מסייעא ליה הנותן טליתו לאומן גמרה והודיעו אפי' מכאן ועד עשרה ימים אינו עובר משום בל תלין נתנה לו בחצי היום מששקעה עליו חמה עובר משום בל תלין","ואי אמרת אומן קונה בשבח כלי אמאי עובר","אמר רב מרי בריה דרב כהנא בגרדא דסרבלא למאי יהבה ניהליה לרכוכי היינו שבחיה","לא צריכא דקא אגריה מיניה לבטושי בטשא ובטשא במעתא:"],[[0,"ואידך ההוא מיבעי ליה לכדתניא","להענישו כאילו הוא נוטל את נפשו כדתניא וכו' ומסקנא כל הכובש שכר שכיר וכו':"],[0,"ואליו הוא נושא","כל עצמו הוא מוסר נפשו עליו לעלות בכבש גבוה וסיכן בעצמו ליפול ולתלות באילן כשעלה עליו למסוק זיתים ולגדור תמרים ומסר נפשו עליו למיתה שמא יפול מן הכבש או מן האילן:"],[1,"ה\"ג ד\"א ואליו הוא נושא את נפשו","ופליגי בהא רב הונא ורב חסדא במשמעותא דקרא חד אמר נפשו של שכיר נענש עליו כאילו הורגו וחד אמר נפשו של גזלן הגיד לך הכתוב שגורם מיתה לעצמו:"],[2,"וקבע","וגוזל את גוזליהם ומה יקבע מהן את נפשם שגורמים הגזלנים רעה לעצמן:"],[2,"אל תגזל דל כי דל הוא ואל תדכא וגו'","אף אם דל הוא ואין לו עזר אל תגזלהו והוא אחד מארבע לשונות שכי משמש בהן אם:"],[3,"דהשתא","לאחר גזילה דהיינו גזלן:"],[3,"משום דנטלו נפש","והכי משמע וקבע את קבעיהם נפש את אשר קבעו את נפשם מהם:"],[4,"לדעתך","ולא מדעתו:"],[6,"חוזר","השכיר אצל בעל הבית אם לא נתן החנוני ונתחייב בעל הבית לשלם:"],[7,"אינו בתורת לעבור","כלומר אין לו עליו כלום שיהא עליו בתורת דמים שום עבירות שכר שכיר:"],[8,"קבלנות","אומן שקבל עליו לעשות מלאכה בכך וכך ולא לשכירות ימים:"],[9,"אומן קונה בשבח כלי","וזוכה במה שהשביחו ומשום קבלנותו יוצא לו וכשמחזירו לו הרי הוא כמוכר לו שבח שהיה לו בתוכו:"],[9,"הלואה היא","ולא שם שכירות עליה:"],[13,"בגרדא דסרבלא","פולקיי\"ר בלע\"ז שאין כאן שבח כלי שאם היה מניחו כמות שהוא היתה מתקיימת הרבה יותר מעתה:"],[13,"לרכוכי","שיהא רך:"],[13,"היינו שבחיה","דאיכא דניחא ליה בהכי מפני שמחמם יותר ויש נוי בדבר:"],[14,"דאגר לביטשי","אלא לעולם לאו בגרדא אלא בתיקון הראשון שקורין פוליי\"ר כשבא מבית הגרדי בוטשין אותו ברגלים בתוך כלי עץ במים וקרקע הראויה בכך מיהו לא בקבלנות עסקינן אלא בשכירות בין ישביח ובין לא ישביח שכרו לפי מנין בטישותיה כך וכך בטישות בכך וכך מעות:"],[14,"דאגרי' לביטשי","לחשבון בטישות:"]],[[6,"חוזר עליו או אינו חוזר עליו","היכא דא\"ל אני פוטרך לגמרי אפי' לא יתן לי פשיטא דאינו חוזר דאם לא כן בכל מחילה בעלמא תיבעי ליה אי בעי קנין או לא והיכא דא\"ל נמי אני פוטרך אם יפרע לי שולחני פשיטא דחוזר כיון דאין שולחני רוצה ליתן לו והכא מיירי כשאמר ליה הפועל סתמא שיסמוך על שולחני ומיבעיא ליה מי אמרי' דאדעתא דהכי סמך אם יתן לו או דלמא לגמרי פוטרו אפילו לא יתן לו וא\"ת פשיטא שלא פטרו לגמרי אלא דוקא אם יתן שהרי שולחני יכול לחזור בו אפי' במעמד שלשתן כיון שאין לבעל הבית בידו לא פקדון ולא מלוה וכיון דיכול לחזור מסתמא לא פטרו לגמרי דלאו בשופטני עסקינן וי\"ל דלעולם איכא למימר שפטרו לגמרי ומתחייב לו שולחני מדין ערב דכשמסמיכו השולחני הוי כאומר סמוך עלי ופטור בעל הבית לגמרי וה\"ה דהוה מצי למיבעי אם השולחני יכול לחזור בו אם לאו דהא בהא תליא והשתא מוכח דמחילה אינה צריכה קנין דע\"כ הכא בלא קנין איירי דקנין לא שייך אלא כשפטרו לגמרי בהדיא ואפי' לא פטרו לגמרי בפירוש כיון שהקנה לו דומה ודאי שלפוטרו הקנה לו דאם לא כן מאי צריך קנין ובפוטרו בהדיא פשיטא דאינו חוזר כדפרישית ובהא לא מיבעיא ליה אלא ודאי בלא קנין איירי ומיהו מצינו לפרש דהכא איירי כשאמר ליה בהדיא אני פוטרך אם יתן לי ואם לא אחזור עליך ופליגי כל זמן שלא חוזר בו שולחני אם יכול לחזור על בעה\"ב ולזה הפירוש נמי יש להוכיח קצת דמחילה אינה צריכה קנין מדאמר רב ששת אינו חוזר אלמא פוטרו כל זמן שירצה שולחני לפרוע לו ובלא קנין מיירי דבקנין אפילו רבה מודה ועוד י\"ל דפלוגתא דהכא לא שייכא מידי למחילה דלכ\"ע פועל חוזר על בעה\"ב ולא פליגי אלא לענין בל תלין כשחוזר בו מיד ביום ראשון על בעה\"ב דלרב ששת אינו חוזר עליו לענין להתחייב בבל תלין כיון דניתק שעה אחת ממנו כשעמד אצל שולחני שוב אינו חוזר לאיסור בל תלין ורבה אמר כיון דתוך זמנו חוזר הוה כדמעיקרא ודייק רבה ממתניתין דקתני המחהו אצל שולחני אינו עובר עליו משמע דוקא כל זמן שעומד אצל שולחני הא מיהדר הדר וחוזר לאיסורו דאי לא הדר לאיסורו הוה ליה למיתני אינו יכול לעבור עליו ולא דמי להא דקתני אחר זמנו אינו עובר עליו ולא קתני אינו יכול דהתם ליכא למיטעי ורב ששת דחי דאינו בתורת לעבור עליו כלל אפילו יחזור בו ומיהו בירושלמי דשבועות גבי חנוני על פנקסו דנשבעין ונוטלין מבעל הבית קאמר דדוקא כשלא העמיד לפועלים אצל חנוני אבל העמידם אצלו אין בעל הבית חייב לפועלים כלום ומפרש רב אלפס דירושלמי אתי אליבא דרב ששת וסבר כמותו אבל מ\"מ לדידן קי\"ל כרבה ומוקי ההיא דלא פליגי לענין בל תלין אלא לענין אם צריך בעל הבית לשלם לפועלים אם לאו וכן משמע בפ\"ק דקדושין (דף טז. ושם) דמחילה אינה צריכה קנין גבי עבד עברי דקאמר למה לי שטרא לימא ליה באפי תרי זיל אמר רבא זאת אומרת עבד עברי גופו קנוי והרב שמחל על גרעונו אין גרעונו מחול משמע דאי לאו דגופו קנוי לו היה יכול למחול ובלא קנין איירי דבקנין לא היה צריך שטר דאפילו עבד כנעני קונה עצמו בחליפין כדמוכח בהשולח (גיטין דף לט: ושם) דקאמר שקל כומתא ושדא בה ואמר קני הא וקני נפשך וקאמר דלא עשה ולא כלום משום דהוה ליה בכליו של מקנה אבל אי הוה בכליו של קונה הוה קניא נפשה בחליפין וכן בפרק הנושא (כתובות דף קד.) אמרינן דלאחר כ\"ה שנה אבדה כתובתה משום דמסתמא מחלה ואע\"ג דלא עשתה שום קנין דבקנין לאלתר נמי אבדה כתובתה ומדאמר לעיל באיזהו נשך (בבא מציעא דף עא:) תן על גבי קרקע והפטר ובפרק הזורק בגיטין (דף עח: ושם) זרוק לי והפטר אין ראיה דאיכא למימר דאיירי בקנין ואין להקשות מה\"ג שפירש בפ\"ק דסנהדרין (דף ו. ד\"ה צריכה) גבי פשרה צריכה קנין דשניהם צריכין קנין המוחל צריך להקנות שמחל לו והמשלם צריך להקנות שישלם לו החצי דשאני פשרה משום דדמי למחילה בטעות שאילו היה יודע שהיה זוכה בדין לא היה מוחל ולהכי צריכה קנין דאלים טפי ומהאי טעמא נמי איכא מאן דבעי ג' ולא סגי בב' משום דדמי למחילה בטעות כל שכן אם לא נפרש כמו שמפרש בהלכות גדולות אלא הקנין עושין קודם שישמעו שיקיימו דברי הפשרנים דבלא קנין יוכלו לחזור בהן כשישמעו הפשרה דאז לא קשה כלום:"],[9,"אומן קונה בשבח כלי כו' אמר להו עובר","פי' יש ענין שעובר כגון היכא דליכא שבח כלי כמו בשליחא דאגרתא או דאגריה לבטשי אבל רב ששת סבר שפיר דאומן קונה בשבח כלי כדמוכח בהגוזל קמא (ב\"ק דף צט. ע\"ש ושם ד\"ה דאגריה) דקאמר התם לימא רב ששת פליגא אדרב אמי דאמר אומן קונה בשבח כלי אמר רב אשי בר חמא דרב ששת בשליחא דאגרתא והנך דבעו מרב ששת לא הזכירו בבעייתן אומן קונה בשבח כלי אלא סתם שאלו קבלן עובר בבל תלין או לאו והגמרא הוא שאומר אומן קונה כו' שלפי הפשט בו תליא הבעיא ולהכי קאמר נמי לימא מסייע ליה שהיה סבור הגמרא דהא בהא תליא ורב ששת שהשיב עובר סבר דאין אומן קונה [ועי' תוס' נדה לד: ד\"ה כי]:"]]],[["שכיר בזמנו נשבע ונוטל וכו': שכיר אמאי תקינו ליה רבנן למשתבע ושקיל","אמר רב יהודה אמר שמואל הלכות גדולות שנו כאן הני הלכתא נינהו הני תקנות נינהו אלא אמר רב יהודה אמר שמואל תקנות גדולות שנו כאן גדולות מכלל דאיכא קטנות","אלא אמר רב נחמן אמר שמואל תקנות קבועות שנו כאן שבועה דבעל הבית היא ועקרוה רבנן לשבועה דבעל הבית ושדיוה אשכיר משום כדי חייו דשכיר ומשום כדי חייו דשכיר מפסדנא ליה לבעל הבית","בעל הבית גופיה ניחא ליה דמשתבע שכיר ושקיל כי היכי דליתגרו ליה פועלים שכיר גופיה ניחא ליה דמשתבע בעל הבית ויפקע כי היכי דליגרוהו בעל הבית על כרחיה אגר שכיר נמי בעל כרחיה איתגר","אלא בעל הבית טרוד בפועלים הוא אי הכי ניתב ליה בלא שבועה כדי להפיס דעתו של בעל הבית","וניתב ליה בעדים טריחא להו מילתא וניתב ליה מעיקרא שניהם רוצים בהקפה","אי הכי אפי' קצץ נמי אלמה תניא אומן אומר שתים קצצת לי והלה אומר לא קצצתי לך אלא אחת המוציא מחבירו עליו הראיה קציצה ודאי מידכר דכירי ליה אינשי","אי הכי אפי' עבר זמנו נמי אלמה תנן עבר זמנו אינו נשבע ונוטל חזקה אין בעל הבית עובר משום בל תלין","והא אמרת בעל הבית טרוד בפועליו הוא הני מילי מקמיה דלימטייה זמן חיוביה"],[[1,"הלכות גדולות שנו כאן","כאותם שמנו חכמים בנשבעין ונוטלין במסכת שבועות (דף מד:) דשכיר ונגזל ונחבל וחנוני על פנקסו:"],[1,"הני הלכה נינהו","בתמיה וכי הלכות למשה מסיני הם והלא אינם אלא תקנות חכמים כדמפרש התם:"],[2,"תקנות קבועות","ראוי לעשותן קבע לעקור עליהם דבר מן התורה דמדאורייתא מי שיש עליו לשלם הוא נשבע דכתיב (שמות כב) ולקח בעליו ולא ישלם והכא שקלוה לשבועה מבעל הבית ושדיוה אשכיר:"],[3,"ויפקע","יפסיד שכרו:"],[3,"כי היכי דליגרוהו","שלא ימנעו מלשוכרו שידאגו לומר חשוד הוא זה לתבוע שכרו משקבלו:"],[3,"על כרחיה אגר","כשהוא צריך לפועלין על כרחו שוכרם:"],[3,"על כרחיה מיתגר","נשכר שצריך למזונות:"],[4,"טרוד בפועליו","וסבר שנתן לו ולא נתן:"],[5,"ליתיב ליה בעדים","ויתן לו בלא שבועה לתקנו להן לכל שוכרי פועלין שיתנו שכרם בעדים ואם יאמר פרעתיו שלא בעדים יתן בלא שבועה:"],[5,"טריחא להו מילתא","לחזר בתר עדים כל היום:"],[5,"וניתיב ליה מעיקרא","לתקון לבעל הבית דיהיב אגריה בצפרא מקמי עבידתייהו דאי אתי שכיר לא מהימן:"],[5,"שניהם רוצים בהקפה","בעל הבית פעמים שאין לו ופועל שמא יפלו ממנו:"],[6,"אי הכי","דבעל הבית טרוד ושכח:"],[7,"אפי' עבר זמנו נמי","ותבעו למחר להימנוהו לפועל:"]],[[0,"שכיר בזמנו נשבע ונוטל","בפ' כל הנשבעין (שבועות דף מה: ושם ד\"ה מתוך) מפרש לא שנו אלא ששכרו בעדים אבל שכרו שלא בעדים מתוך שיכול לומר לא שכרתיך מעולם יכול לומר שכרתיך ונתתי לך שכרך תימה דהיכי נאמן במגו דהא מפרש בגמ' דטעמא דשכיר נשבע משום דבעה\"ב טרוד בפועליו ואנן חושבין אותו כאילו אמר איני יודע מדפריך בגמ' אי הכי ניתיב ליה בלא שבועה וא\"כ מה מועיל מגו דאילו אומר איני יודע לא הוה מהני שום מגו והוה חייב דהוה ליה כאומר הלויתני ואיני יודע אם פרעתיך דחייב כדתנן בהגוזל בתרא (ב\"ק דף קיח.) וביבמות בפרק האשה שהלכה (יבמות דף קיד:) משמע נמי דלא מהני מגו בכי האי גוונא דאמר אינה נאמנת לומר מת בעלי במלחמה משום דאמרה בדדמי לה ואינה יודעת בברור שמת ולא מהני לה מגו דאי בעיא אמרה מת על מטתו:"],[1,"מכלל דאיכא קטנות","אע\"ג דבפרק השולח (גיטין דף לו.) אמרינן תקנה גדולה התקינו שיהיו מפרשין שמותיהן בגיטין וכן בהגוזל קמא (ב\"ק דף קג:) תקנה גדולה התקינו שאם יציאה יתירה על הקרן כו' לא פריך אלא הכא דקאמר שנו כאן דמשמע ולא במקום אחר:"],[2,"תקנות קבועות","הא דנקט לשון רבים משום דקאי אכל הנהו דנשבעין ונוטלין בפרק כל הנשבעין (שבועות דף מד:) דשכיר ונגזל ונחבל ושכנגדו חשוד על השבועה וחנוני על פנקסו וקרי להו קבועות משום דעקרו לשבועה ממקומה וקבעוה לשכנגדו שיהא נשבע ונוטל והגמרא לא הוצרכה לפרש טעם כולם אלא טעמא דשכיר:"],[2,"שקלוה רבנן לשבועה מבעה\"ב ושדיוה אשכיר","וא\"ת והלא אף בכופר הכל איירי ת\"ק מדפליג עליה ר' יהודה ואמר דשכיר אינו נשבע אלא במודה מקצת ובכופר הכל מי מיחייב בעל הבית שבועה דאורייתא ומאי קאמר דשקלוה רבנן מבעל הבית וי\"ל דאמודה במקצת קאמר דשקלוה מבעל הבית ואפי' היכא דכופר הכל טפי הוה לן לחיוביה בעל הבית שעליו לשלם שהרי אם מודה מקצת הוא נשבע ולפי שהיתה ראויה להיות על בעל הבית קאמר דשקלוה:"],[4,"טרוד בפועליו הוא","וחשוב כמו איני יודע דחייב אפי' כופר הכל כדתנן בהגוזל בתרא (ב\"ק דף קיח.) הלויתני ואיני יודע אם פרעתי לך חייב ולא פליג בין אם יש לו פועלים הרבה בין אין לו:"],[4,"אי הכי ניתיב ליה בלא שבועה","וא\"ת מאי פריך וכי לעולם ישכח פעמים שאומר בעל הבית אמת ולכך לא רצו לתקן שיטול בלא שבועה תדע דאי חשוב בודאי שכח אמאי פטר ר' יהודה כופר הכל אלא ודאי חששא בעלמא דחיישינן שמא שכח ולהכי פטר ר' יהודה בכופר הכל דליכא שבועה דאורייתא אבעל הבית דלא חשבינן ליה לבעה\"ב כאומר איני יודע כי רגילות הוא שיודע יפה אבל כשמודה מקצת חששו לשמא שכח כי פעמים שהוא שוכח מחמת שהוא טרוד בפועליו וישבע לשקר לפי שסבר שפרע וה\"נ לרבנן דלא מחזקינן ליה בודאי שכח וי\"ל דנראה לגמ' דלת\"ק מחזקינן ליה בודאי שכח ואומר איני יודע מדמחייב בכופר הכל שאם לא היתה אלא חששא בעלמא אמאי שקיל שכיר אפי' בשבועה כיון דאיכא למימר דבעה\"ב יודע יפה שפרע אלא ודאי דחשיב ליה כאומר איני יודע ומשני להפיס דעתו של בעה\"ב לפי שסבר בדעתו בברור שפרע אבל בהלויתני ואיני יודע אם פרעתיך אין צריך שבועה דלא שייך הספק כיון שהוא מודה שאינו יודע אם פרע:"],[5,"וניתיב ליה בעדים","פי' נתקן שלא יתן לו אלא בעדים ואם יפרע בלא עדים איהו דאפסיד אנפשיה ולא נצטרך להפיס דעתו דכל כמה שנוכל לתקן שלא ישבע על חנם יש לתקן וכן ניתיב ליה מעיקרא פריך דנתקן אם לא יקח שכרו מתחלה שיפסיד קודם שנתקן שבועה על חנם:"],[6,"אי הכי אפילו קצץ נמי","וא\"ת והא קציצה הוי כאומר איני יודע אם הלויתני דפטור לר\"נ ור' יוחנן דאמרי (לעיל בבא מציעא דף צז:) מנה לי בידך והלה אומר איני יודע פטור וי\"ל דהכא שמודה מקצת יש לחייבו דהוה כחמשין ידענא וחמשין לא ידענא (שם צח.) וא\"ת לוקי כגון שאותה אחת שמודה כבר פרע דהשתא הוי כופר הכל וי\"ל דניחא ליה לשנויי קציצה מידכר דכירי שהוא מתורץ גם לרב הונא ורב יהודה . ועוד אפי' לר\"נ ור' יוחנן ניחא ליה לשנויי הכי כדי לאוקמי בכל ענין אפי' לא פרע אותה אחת שמודה ועוד דהפשט משמע שלא פרע דומיא דמילתיה דר' יהודה:"],[6,"שתים קצצת לי כו'","המוציא מחבירו עליו הראיה ואם לא הביא ראיה ישבע בעה\"ב ויפסיד אומן דבלא שבועה אינו יכול להפטר כיון שמודה במקצת והכי מפרש לה בהדיא בריש כל הנשבעין (שבועות דף מו.) וא\"ת דהכא קתני המוציא מחבירו עליו הראיה ובחזקת הבתים (ב\"ב מה: ושם ד\"ה נתנה) תניא דבקציצה נמי נשבע ונוטל וי\"ל דבריש כל הנשבעין פריך כי האי גוונא ומשני דהך ברייתא דחזקת הבתים ר' יהודה היא:"],[6,"קציצה מידכר דכירי אינשי","לא מצי לשנויי דהכא משום הכי אין שכיר נשבע ונוטל משום דאיירי כששכרו שלא בעדים דאי איכא עדים נחזי עדים מאי קאמרי כמה קצץ דהכי פריך בפ' חזקת הבתים (בבא בתרא דף מה:) בהלכה דאומן דהא ע\"כ איירי כשיש עדים דומיא דרישא דקתני שכיר בזמנו נשבע ונוטל דמוקי לה רב ושמואל ששכרו בעדים כדאמרי' התם בשבועות (דף מה:) בהדיא וה\"נ סיפא איירי בשכרו בעדים ולא שמעו הקציצה או שמעו ושכחו ובחזקת הבתים דפריך רבא לאביי דאמר אי לא ראה אע\"ג דאיכא עדים יש לאומן חזקה ואי ראה אע\"ג דליכא עדים אין לו חזקה מהנותן טליתו לאומן ואומר שתים קצצת לי ובעל הבית אומר לא קצצתי לך אלא אחת כל זמן שהטלית ביד אומן על בעה\"ב להביא ראיה ואי דאיכא עדים ניחזי מאי קאמרי אלא לאו דליכא עדים ואע\"ג דראה אומן נאמן התם לא הוה מצי למימר דאיכא עדים וכגון ששכחו או לא שמעו הקציצה דא\"כ אף לדידיה תקשי דכיון דמשמע ליה דאיירי בכל ענין אפילו בראה אי מיירי נמי דאיכא עדים אמאי נאמן אומן דבאיכא עדים וראה לכולי עלמא אין לו חזקה כדתנן במתני' ורבא דקאמר אלא לאו דליכא עדים (ולא ראה) אינו אומר כן אלא כדי שלא יקשה לו למה שרצה להעמידו אף בראה ואביי דמשני ליה לא דליכא עדים ולא ראה הוי מצי לאוקמה בדאיכא עדים ולא ראה וכגון שלא שמעו הקציצה אלא משום דרבא אוקמה בדליכא עדים אוקמה איהו הכי ועוד נראה דאי משום מגו בעל הבית נאמן אמאי נקט שחולקין בקציצה ושבק לומר שחולקין בפריעה זה אומר נתתי וזה אומר לא נתת כדתנן בפ' כל הנשבעין (שבועות דף מד:) ועוד יש לתרץ דאפילו איירי בששכרו שלא בעדים אין נאמן במגו כיון שהוא מודה במקצת שלא היה יכול להעיז ולכפור ולומר לא שכרתיך מעולם כדין כל מודה מקצת דאין נאמן במגו דאי בעי כפר הכל ועוד אומר ר\"י דודאי כי איכא עדים רגילות שיודעים וזוכרין הקציצה כדאמרינן בחזקת הבתים וברייתא כולה בדליכא עדים איירי ורישא דקתני נשבע ונוטל הכי פירושו יביא ראיה ששכרו ואז יהיה נשבע ונוטל. והיכא דקתני המע\"ה היינו יביא עדים שקצץ לו שתים שהעדים יודעים הקציצה אם יודעין ששכרו כדפריך וכן משמע בפרק כל הנשבעין דקאמר עלה ראיה דלשלם קתני ראיה דלשבע לא קתני משמע דנשבע ונוטל היינו שיביא ראיה ששכרו ויהיה נשבע ונוטל:"]]],[["אבל מטא זמן חיוביה רמי אנפשיה ומידכר","וכי שכיר עובר משום בל תגזול התם תרי חזקי הכא חדא חזקה גבי בעל הבית איכא תרי חזקי חדא דאין בעל הבית עובר משום (ויקרא יט, יג) בל תלין וחדא דאין שכיר משהא שכרו והכא חדא חזקה:","אם יש עדים שתבעו הרי זה נשבע ונוטל: והא קתבעו לקמן א\"ר אסי שתבעו בזמנו ודלמא לבתר הכי פרע אמר אביי שתבעו כל זמנו","ולעולם לא פרע ליה א\"ר חמא בר עוקבא כנגד אותו היום של תביעה:","\u0001מתני׳\u0002 המלוה את חבירו לא ימשכננו אלא בב\"ד ולא יכנס לביתו ליטול משכונו שנאמר (דברים כד, יא) בחוץ תעמוד היו לו שני כלים נוטל אחד ומניח אחד","ומחזיר את הכר בלילה ואת המחרישה ביום ואם מת אינו מחזיר ליורשיו רשב\"ג אומר אף לעצמו אינו מחזיר אלא עד שלשים יום ומשלשים יום ולהלן מוכרן בב\"ד:","\u0001גמ׳\u0002 אמר שמואל שליח ב\"ד מנתח נתוחי אין אבל משכוני לא והתנן המלוה את חבירו לא ימשכננו אלא בב\"ד מכלל דבב\"ד ממשכנין","א\"ל שמואל אימא לא ינתחנו אלא בב\"ד הכי נמי מסתברא דקתני סיפא לא יכנס לביתו ליטול משכונו מני אילימא בעל חוב מרישא שמע מינה אלא לאו שליח ב\"ד","אי משום הא לא איריא ה\"ק המלוה את חבירו לא ימשכננו אלא בב\"ד מכלל דבב\"ד ממשכנים ובעל חוב אפי' נתוחי נמי לא שלא יכנס לביתו ליטול משכונו","מתיב רב יוסף (דברים כד, ו) לא יחבל ריחים ורכב הא דברים אחרים חבל (דברים כד, יז) לא תחבל בגד אלמנה הא של אחרים תחבל מאן אי נימא בעל חוב הא כתיב (דברים כד, י) לא תבא אל ביתו לעבוט עבוטו אלא לאו שליח ב\"ד","תרגמה רב פפא בריה דרב נחמן קמיה דרב יוסף ואמרי לה רב פפא בריה דרב יוסף קמיה דרב יוסף לעולם בבעל חוב ולעבור עליו בשני לאוין","ת\"ש ממשמע שנאמר (דברים כד, יא) בחוץ תעמוד איני יודע שהאיש אשר אתה נושה בו יוציא אלא מה תלמוד לומר (דברים כד, יא) והאיש לרבות שליח בית דין מאי לאו שליח בית דין כלוה"],[[1,"גבי בעל הבית","כלומר בזכותא דבעל הבית איכא תרי חזקי לזכותו:"],[2,"והא תבע ליה קמן","ומה עדים שתבעו אותו מצריכין:"],[2,"ודלמא לבתר הכי","דאזלי עדים מהתם פרעיה בו ביום דלא עבר בבל תלין:"],[2,"כל זמנו","עד שעבר עליו:"],[3,"ולעולם","בתמיהה ובשביל שתבעו כל היום ולא נתן יהא שכיר זה נאמן לעולם לומר לא התקבלתי ואם רוצה בעה\"ב לישבע לא נאמין וכי כל כך השהה שכיר שכרו:"],[3,"א\"ר חמא בר עוקבא כנגד כל היום של תביעה","יום אחד לאחר זמנו נתנו לו חכמים לישבע ויטול:"],[4,"מתני' המלוה את חבירו","והגיע זמן ולא פרע לו:"],[4,"לא ימשכננו","אפי' בשוק אלא בב\"ד:"],[4,"ולא יכנס לביתו","בגמ' מפרש במאן קאי:"],[4,"היו לו שני כלים","וחובו כנגד שניהם ומשכנו בשניהם:"],[4,"נוטל אחד ומחזיר אחד","בשעה שהוא צריך לזה יחזירנו לו משום החזרת העבוט ויעכב את השני וכשיצטרך זה לשני יטול זה את הראשון ויחזיר את השני כדמפרש ואזיל מחזיר את הכר בלילה ואת המחרישה ביום:"],[5,"מת","הלוה אין משיב העבוט ליורשין שאין כאן מצות העבוט אלא ימכרנו ויגבה חובו דהשב תשיבם לו כתיב ולא ליורשין:"],[5,"שלשים יום","זמן ב\"ד:"],[6,"גמ' ושליח ב\"ד מנתח נתוחי","אף הוא אינו רשאי ליכנס לביתו ולמשכנו אלא רואהו בשוק ומנתק דבר שאוחז בידו ממנו:"],[8,"ממשכנין","משמע בתוך הבית:"],[9,"חבילה","מתוך הבית משמע דהא ריחיים ורכב בגו ביתא שכיחי:"],[10,"לעולם בבעל חוב","קאמר ולא תידוק מינה הא כלים אחרים חבול דבכלים אחרים עובר משום לא תבא אל ביתו ולהכי איצטריך להוסיף לאו שני משום ריחיים ורכב וחד משום לא תבא אל ביתו:"],[11,"ממשמע שנאמר בחוץ תעמוד","ויוציא אליך את העבוט וכי איני יודע שהאיש יוציאנו אלא מי יוציאנו אם לא בעה\"ב:"],[11,"מאי לאו לרבות שליח ב\"ד כו'","שיכנס לתוך הבית וה\"ק והאיש דהוא שליח ב\"ד ואשר אתה נושה בו יוציא אליך:"]],[[0,"השתא דמטא זמן חיוביה רמי אנפשיה ומדכר","וא\"ת א\"כ בזמנו אמאי נשבע שכיר ונוטל לימא בעה\"ב איני זוכר עתה אבל הניחו לי עד שיעלה עמוד השחר שאזכור אם נתתי אם לאו כיון שאחר זמנו אנו פוטרים אותו מטעם זה ועוד קשה במודה במקצת אמאי אין בעל הבית נשבע דרמי אנפשיה ומידכר שלא ישבע לשקר וי\"ל דחזקה שאין בעה\"ב עובר בבל תלין לא מהני אלא היכא דאיכא חזקה דאין שכיר משהה שכרו בהדיה כמו שאפרש בסמוך ואם היה יכול בעה\"ב לטעון הניחו לי עד שיעלה עמוד השחר לא היתה כאן חזקה דאין שכיר משהה שכרו שהרי לא השהה אתו אלא תבעו ממנו בב\"ד ולא רצו ליתן לו ושהו אותו לעמוד השחר:"],[1,"וכי שכיר עובר בבל תגזול","וא\"ת בעל הבית נמי אית ליה הך חזקה שאינו עובר בבל תגזול וי\"ל דחמיר ליה לאו אחד כמו שנים א\"נ בלאו הכי משני ליה שפיר וא\"ת ומ\"מ איכא חזקה דאין בעה\"ב עובר בבל תלין כנגדו והוה ברי וברי והמע\"ה וי\"ל דחזקה של בעל הבית אינה חזקה טובה כשל שכיר דזימנין לא רמי אנפשיה למידכר והוה לן למימר דנשבע ונוטל וחזקה דאין שכיר משהה שכרו לבדו לא חשיבא כחזקת שכיר אלא כששתיהן ביחד הוו כנגד חזקת שכיר והוי ברי וברי והמע\"ה:"],[2,"והא תבע ליה קמן","ס\"ד השתא אם יש עדים שתבעו היינו אפי' אחר זמנו ולכך פריך דמה אנו צריכין לעדים הלא תובעו השתא בפנינו ולמאי דס\"ד הוה מצי למיפרך אמאי נשבע ונוטל אלא פריך שפיר:"],[3,"ולעולם","פי' בקונטרס וכי שכיר משהה שכרו כ\"כ ואינו מיושב דאין בזה ראיה שנפרע דחזקה דאין שכיר משהה שכרו אינה מועלת אלא היכא דאיכא חזקה דאין בעה\"ב עובר בבל תלין בהדה ובל תלין אינו עובר אלא בוקר ראשון אלא הכי פירושו ולעולם שכיר נשבע ונוטל אין זו תקנה טובה שיהא נאמן לעולם לומר לא פרע לי:"],[5,"מחזיר את הכר בלילה","בריש תמורה (דף ו. ושם ד\"ה מחזיר) פריך לרבא דאמר כל דאמר רחמנא לא תעביד אי עביד לא מהני והרי השבת העבוט דאמר רחמנא לא תעבוט עבוטו ותנן מחזיר את הכר בלילה אלמא דמהני וקשה דמנליה דמתני' איירי במשכנו באיסור וא\"ל דסמיך אברייתא דאלו מציאות (לעיל בבא מציעא דף לא:) דקתני משכנו שלא ברשות מנין כו' דא\"כ מאי קשה לן דהא בברייתא גופה יליף מהשב תשיב כדמשני התם ואי אדשמואל סמיך א\"כ מה צריך לתרץ מהשב תשיב הלא עיקר קרא לשמואל איירי במשכנו באיסור דאם חבל וגו' משמע דמשכנו בביתו וי\"ל דסמיך אמעשים בכל יום דמחזיר אפי' משכנו שלא ברשות א\"נ סמיך אברייתא דלקמן (בבא מציעא דף קיד:) דמתרץ לה רב ששת המלוה [את] חבירו אינו רשאי למשכנו משכנו חייב להחזיר לו אע\"ג דהאי דפריך לרבא בתמורה לא אתי אליבא דשמואל דלשמואל אין שייך להקשות דעיקר קרא במשכנו באיסור כתיב מ\"מ אין להוכיח משם שלא יהא הלכה כשמואל כי כן דרך גמרא להקשות ולתרץ אפילו דלא כהלכתא כדאשכחן בפ\"ב דכתובות (דף כו:) וברייתא דאלו מציאות (לעיל בבא מציעא דף לא:) דקאמר אין לי אלא במשכנו ברשות אין צריך לומר דשמואל יהפוך וישנה אין לי אלא משכנו שלא ברשות אלא יעמידנה כתנא דפליג אתנא דקאי כוותיה ויהפוך הדרשה:"],[5,"ואת המחרישה ביום","קשה לר״ת דתניא בסוף פירקין (בבא מציעא דף קטז.) חבל זוג של ספרים וצמד של פרות חייב משום ב' כלים ופירש בקונטרס פרות החורשות וחייב עליהם החובלן לפי שעושין אוכל נפש א״כ היאך נטל את המחרישה דקתני ומחזיר הא עבר כי נפש הוא חובל (דברים כ״ד:ו׳) ועוד דאין נראה לחייב אלא דוקא דומיא דריחיים ורכב שמתקנים האוכל עצמו בכלי לכן מפרש ר״ת צמד פרות היינו פרות המרכסות בתבואה וגריס ר״ת נמי זוג של מספרים ולא גרסינן זוג של ספרים וכן גריס ר״ח והם תספורת של ירק או לגזוז בית השחיטה כדאמרינן בבכורות (דף כה.) שדרכן היה לגזוז אבל פרות החורשות לא מיקרי כלי שעושין אוכל נפש ועוד נראה לר״ת דמחרישה דהכא לאו היינו מחרישה שחורשין בה את הקרקע דנראה דלא מיחייב בהשבת העבוט אלא בכלי העשוי לגוף האדם ולהנאתו ועוד דמוקי בגמ' במחרישה דכספא ואין דרך לחרוש קרקע במחרישה של כסף אלא נראה לר״ת דהיינו מגרדתא שמגרדין בו בני אדם בבית המרחץ כדאמר בפרק חבית (שבת דף קמז:) עבדא ליה אימיה מגרדתא דכספא וכן בפרק מציאת האשה (כתובות דף סח.) במחרישה דכספא פר״ח דהיינו מגרדתא:"],[7,"אימא לא ינתחנו אלא בבית דין","וא\"ת מנין דניתוח אסור לבעל חוב ואומר ר\"י דמדרבנן הוא כדאמר בסמוך בעל חוב ניתוח נמי לא גזירה שמא יכנס בביתו:"],[7,"וחסורי מיחסרא והכי קתני","תימה דקאמר חסורי מיחסרא כדי לדחות וי\"ל דאין לחוש כיון שאינו מגיה כ\"כ ורוב ספרים גרסי הכי קאמר:"]]],[["לא שליח ב\"ד כמלוה","ת\"ש (שמות כב, כה) אם חבל תחבל שלמת רעך בשליח בית דין הכתוב מדבר אתה אומר בשליח בית דין הכתוב מדבר או אינו אלא בבעל חוב כשהוא אומר (דברים כד, י) לא תבא אל ביתו לעבוט עבוטו הרי בע\"ח אמור הא מה אני מקיים אם חבל תחבל שלמת רעך בשליח ב\"ד הכתוב מדבר","תנאי היא דתניא שליח ב\"ד שבא למשכנו לא יכנס לביתו למשכנו אלא עומד מבחוץ והלה מוציא לו משכון שנאמר (דברים כד, יא) בחוץ תעמוד והאיש","ותניא אידך בע\"ח שבא למשכנו לא יכנס לביתו למשכנו אלא עומד בחוץ והלה נכנס ומוציא לו משכונו שנאמר בחוץ תעמוד ושליח ב\"ד שבא למשכנו הרי זה נכנס לביתו וממשכנו","ולא ימשכננו דברים שעושין בהן אוכל נפש ונותן מטה ומטה ומצע לעשיר מטה ומטה ומפץ לעני לו אבל לא לאשתו ולא לבניו ולבנותיו","כדרך שמסדרין לבע\"ח כך מסדרין בערכין כלפי לייא עיקר סידור בערכין כתיב אלא אימא כדרך שמסדרין בערכין כך מסדרין בבע\"ח","אמר מר נותן מטה ומטה ומצע לעשיר מטה ומטה ומפץ לעני למאן אילימא לאשתו ולבניו ולבנותיו הא אמרת לו אבל לא לאשתו ולבניו ולבנותיו אלא אידי ואידי לדידיה","תרתי למה לי חדא דאכיל עלה וחדא דזג עלה כדשמואל דאמר שמואל כל מילי ידענא אסותייהו לבר מהני תלת מאן דאכיל אהינא מרירא אליבא ריקנא ומאן דאסר מיתנא דכיתנא רטיבא אחרציה ומאן דאכיל נהמא ולא מסגי ארבעה גרמידי","תני תנא קמיה דרב נחמן כדרך שמסדרין בערכין כך מסדרין בבע\"ח א\"ל השתא זבוני מזבנינן ליה סדורי מסדרינן ליה ומי מזבנינן ליה והתנן מחזיר את הכר בלילה ואת המחרישה ביום","תנא כרשב\"ג תנא קמיה והכי קאמר ליה השתא לרשב\"ג זבוני מזבנינן ליה סדורי מסדרינן ליה דתנן רשב\"ג אומר אף לעצמו אינו מחזיר אלא עד שלשים יום מכאן ואילך מוכרן בב\"ד","וממאי דכי קאמר רשב\"ג זבוני לגמרי קאמר דלמא הכי קאמר עד שלשים יום הדר ליה בעיניה מכאן ואילך מיהדר ליה למאי דחזי ליה ומזבנינן מאי דלא חזי ליה","אי סלקא דעתך אית ליה לרשב\"ג האי סברא ליכא מידי דלא חזי ליה דאמר אביי רשב\"ג ורבי שמעון ורבי ישמעאל ורבי עקיבא כולהו סבירא להו כל ישראל בני מלכים הן","רשב\"ג דתנן לא את הלוף ולא את החרדל רשב\"ג מתיר בלוף מפני שהוא מאכל לעורבין","רבי שמעון דתנן בני מלכים סכין שמן וורד על גבי מכותיהן בשבת שכן דרכן לסוך בחול ר' שמעון אומר כל ישראל בני מלכים הן","רבי ישמעאל ורבי עקיבא דתניא הרי שהיו נושין בו אלף זוז ולבוש איצטלא בת מאה מנה מפשיטין אותה ממנו ומלבישים אותו איצטלא הראויה לו ותנא משום רבי ישמעאל ותנא משום רבי עקיבא כל ישראל ראוין לאותה איצטלא","ולמאי דסליק אדעתין מעיקרא דיהיב ליה מאי דחזי ליה ומזבנינן מאי דלא חזי ליה בשלמא כר וכסת חזי ליה דביני ביני אלא מחרישה למאי חזיא אמר רבא בר רבה מחרישה דכספא","מתקיף לה רב חגא ולימא ליה לאו עלי קרמית אמר ליה אביי"],[[0,"לא שליח ב\"ד כמלוה","והכי קאמר בחוץ תעמוד אתה והאיש שהוא שליח ב\"ד ואשר אתה נושה בו יוציא אליך:"],[1,"הרי בעל חוב אמור","שאינו רשאי:"],[1,"הכתוב מדבר","שהוא רשאי ליכנס לחובלו והכי קאמר קרא אם חבול תחבול על ידי שליח ב\"ד עד בוא השמש תשיבנו לו:"],[2,"שנאמר בחוץ תעמוד והאיש","שהוא שליח בית דין גם הוא יעמוד בחוץ:"],[4,"לא ימשכננו כלים שעושין בהן אוכל נפש","דאיתרבו מכי נפש הוא חובל:"],[4,"מטה ומטה","לקמן הוא מפרש אחת לאכול ואחת לישן:"],[4,"מצע","של לבד שקורין פולטר\"א במקום שאין כסתות:"],[4,"לעשיר","שהורגל במצעות:"],[4,"ומפץ לעני","לפי מה שהורגל דגבי ערכין כתיב ואם מך הוא מערכך ודרשינן (ערכין דף כד.) החייהו מערכך גזבר הבא למשכנו כשאין ידו משגת והוא נידון בהשגת יד דכתיב (ויקרא כ״ז:ח׳) והעמידו לפני הכהן והעריך אותו הכהן משייר לו כדי חייו ונוטל השאר ויצא ידי הקדש ואפי' העשיר לאחר שאמדוהו ונטל מה שבידו ומינה נמי גמרינן לבעל חוב שמשיירין לו כדי חייו כדאמר לקמן (בבא מציעא דף קיד.) דגמר מיכה מיכה:"],[4,"לו","הוא צריך ליתן מטה אבל לא לאשתו ולבניו דהחייהו כתיב ולא הוטל על המלוה להחיות את בני ביתו:"],[5,"שמסדרין","שמין להניח לו צרכי חייו לשון והעריך אותו לישנא אחרינא שמשרדין לשון שריד ושתיהן שמעתי:"],[5,"אדרבה עיקר סידור בערכין כתיב","כדפי' לעיל:"],[6,"למאן","המטה השנית:"],[7,"מיתנא רטיבא דכיתנא אחרציה","חבל לח של פשתן על מתניו:"],[7,"אהינא","תמרא:"],[7,"אליבא ריקנא","קודם אכילה:"],[7,"ולא מסגי ארבעה גרמידי","קודם שישן הלכך יהבינן ליה מטה שניה ומושיבה ברחוק ארבע אמות ממקום אכילתו ועל כרחו ירגיל לעמוד וללכת במשכב ולא יישן על מטה שאכל:"],[8,"זבוני מזבנינן ליה","לאחר שלשים יום אף כלים הצריכין לו כדתנן משלשים ולהלן מוכרן:"],[9,"תנא כרבן שמעון תני תנא קמיה","דרב נחמן להך מתני' רשב\"ג אומר כדרך שמסדרין וכו':"],[10,"זבוני לגמרי","שלא ישאיר לו לפי צרכו בצמצום:"],[10,"בעיניה","כמות שהיא חשובה אם חבל כסות של מעיל יחזיר לו הוא בעצמה:"],[10,"מהדר ליה מאי דחזי ליה","ימכור לו של שיראין ויתן לו אחת של צמר ואחת של קנבוס:"],[11,"אי אית ליה לרבן גמליאל האי סברא","לסדר לבעל חוב:"],[11,"ליכא מידי דלא חזי ליה","מאחר שהורגל בו דהא שמענא ליה דאמר כל ישראל בני מלכים הם דאמר אביי וכו':"],[12,"לא את הלוף ולא את החרדל","מטלטלין בשבת שאינם ראוים היום לא זה לבשל ולא זה לטחון לוף מין קטנית ואינן ראוין למאכל כשהוא חי ואפילו לעופות:"],[12,"לעורבים","וישראל בני מלכים ויש להם לגדל עורבים לנוי ולשחוק:"],[13,"תנא כרבן שמעון תני תנא קמיה","דרב נחמן להך מתני' רשב\"ג אומר כדרך שמסדרין וכו':"],[13,"שכן דרכן לסוך בחול","בלא שום מכה הלכך כי איכא מכה נמי לא מוכחא מילתא דלרפואה עביד (דכי גזרו) רבנן משום שחיקת סממנין:"],[14,"מפשיטין אותה ממנו","לפרוע לבעל חוב את חובו:"],[15,"בשלמא כר וכסת","דתנן במתניתין איכא למימר מוכרן דקאמר רשב\"ג לביני ביני קאמר לקנות גרועה הימנו וביני ביני יטול בחובו:"],[15,"אלא מחרישה","דקתני במתניתין ועלה קאמר רשב\"ג מוכרן מאי ביני ביני איכא:"],[16,"ונימא ליה","מלוה:"],[16,"לאו עלי דידי רמית","לפרנסך:"]],[[4,"מטה ומטה","בפ' שום היתומים (ערכין דף כג:) לא תני אלא מטה המוצעת משום דמוצעת לא שבקינן ליה אלא אחת כדאמר נמי הכא מטה ומטה ומצע ובפ' אע\"פ (כתובות דף סד:) גבי משרה אשתו על ידי שליש בעני שבישראל דלא יהיב לה אלא מטה ומפץ משום דהתם קודם שנשאת לו לא היה לה אלא חדא מטה:"],[8,"השתא זבוני מזבנינן","הכסת והכר שיש לו בעין סדורי מסדרינן בתמיה פירוש ואנן נסדר לו להניח מן המעות כדי לקנות כסות לצורך שנים עשר חדש כמו שעושין בערכין:"],[16,"נימא ליה לא עלי דידי רמית","לאו אמתני' פריך אמאי מחזיר לו הכר דא\"כ למה המתין עד כאן ועוד דמה צריך טעם על מצות המקום ועוד וכי לא ידע דכתיב (דברים כ״ד:י״ג) ולך תהיה צדקה אלא על כרחך ידע ואפילו הכי מקשה ליה וא\"כ מה מתרץ לו אלא נראה דארבי עקיבא ורבי ישמעאל פריך דאמרי כל ישראל בני מלכים הם וכולן ראוין לאותה איצטלא ואמאי כיון דאינו לובשה אלא לכבוד ולנוי בעלמא למה יש לנו לומר שכל זה הטיל הכתוב על המלוה כיון שלא פירש הכתוב בהדיא ולא היה שייך עליו יותר מעל אחר כיון דסגיא ליה בלאו הכי ומשני גם באיצטלא שייך לומר לך תהיה צדקה והטיל עליו הכתוב שלא למנוע ממנו הנוי והכבוד והתענוג שהורגל בו עד עתה:"]]],[["איברא עליה קרמי משום שנאמר (דברים כד, יג) ולך תהיה צדקה","איבעיא להו מהו שיסדרו בבעל חוב מי גמר מיכה מיכה מערכין או לא","ת\"ש דשלח רבין באגרתי' דבר זה שאלתי לכל רבותי ולא אמרו לי דבר ברם כך היתה שאלה האומר הרי עלי מנה לבדק הבית מהו שיסדרו","ר' יעקב משמיה דבר פדא ור' ירמיה משמיה דאילפא אמרי ק\"ו מבעל חוב ומה ב\"ח שמחזירין אין מסדרין הקדש שאין מחזירין אינו דין שאין מסדרין ור' יוחנן אמר נדר בערכך כתיב מה ערכין מסדרין אף הקדש מסדרין","ואידך ההוא לנידון בכבודו הוא דאתא מה ערכין נידון בכבודו אף הקדש נידון בכבודו","ויסדרו בב\"ח ק\"ו מערכין ומה ערכין שאין מחזירין מסדרין בעל חוב שמחזירין אינו דין שמסדרין אמר קרא (ויקרא כז, ח) ואם מך הוא מערכך הוא ולא ב\"ח","ואידך האי עד שיהא במכותו מתחילתו ועד סופו","ויחזירו בהקדש קל וחומר מב\"ח ומה בעל חוב שאין מסדרין מחזירין הקדש שמסדרין אינו דין שמחזירין אמר קרא (דברים כד, יג) ושכב בשלמתו וברכך יצא הקדש שאין צריך ברכה","ולא והכתי' (דברים ח, י) ואכלת ושבעת וברכת וגו' אלא אמר קרא ולך תהיה צדקה מי שצריך צדקה יצא הקדש שאין צריך צדקה","אשכחיה רבה בר אבוה לאליהו דקאי בבית הקברות של עובדי כוכבים א\"ל מהו שיסדרו בב\"ח א\"ל גמר מיכה מיכה מערכין גבי ערכין כתיב ואם מך הוא מערכך גבי ב\"ח כתיב (ויקרא כה, לה) וכי ימוך אחיך"],[[0,"איברא","באמת:"],[0,"עליה רמי","שיהא לו צדקה שהכתוב הטיל עליו לעשות לו צדקה להלך לפניו:"],[1,"מיכה מיכה","גבי לוה ומלוה כתיב וכי ימוך אחיך ומטה ידו ממך וגבי ערכין כתיב ואם מך הוא מערכך:"],[2,"ברם כך היתה שאילה","אבל כן נשאלה שאילה אחת בבית המדרש מינה יש ללמוד שאין מסדרין:"],[2,"","דבר זה [שאלתי] אם למדנו גזירה שוה דמיכה מיכה ולא אמרו לי דבר:"],[2,"הרי עלי מנה לבדק הבית","והשגת יד לא כתיב אלא בערכין אבל שאר הקדשות אין נידונין בהשג יד ומה שיש לו גובין הימנו והמותר יגבו לאחר זמן אם יעשיר:"],[2,"מהו שיסדרו לו","כשבאין למשכנו:"],[3,"שמחזירין","שמלוה מצווה להשיב לו את העבוט:"],[3,"אין מסדרין","להשאיר לו כלום משבא למכור לאחר שלשים:"],[3,"נדר בערכך","כי יפליא נדר בערכך נפשות (ויקרא כ״ז:ב׳) הקיש נדרים לערכין:"],[4,"ההוא לנידון בכבודו","היקש נדר לערכין להכי אתא שאם אמר דמי לבי או ראשי או כבידי עלי נותן דמי כולו אבל אם אמר על אבר שאין הנשמה תלויה בו דמיו עלי שמין אותו כעבד הנמכר בשוק כמה הוא שוה ביד וכמה הוא שוה בלא יד להא מילתא איצטריך למיגמר נדר מערכין גבי ערכין כתיב (שם) ערכך נפשות אם אמר ערך אבר שהנשמה תלויה בו עלי נותן דמי כולו ואם אמר ערך ידי עלי לא אמר כלום שאין ערך כתוב אלא לנפש:"],[4,"נידון בכבודו","האבר נידון לפי כבודו שאם הנשמה תלויה בו נותן דמי כולו:"],[5,"ויסדרו לב\"ח","גמרא קא פריך לה:"],[5,"שמחזירין","מיום אל יום את כלי הצריך לו:"],[5,"אינו דין שמסדרין","כשבא למכור לאחר שלשים יום ישאיר לו כדי חייו כגון מטה ומפץ והנך דאמר בערכין (דף כג:):"],[6,"ואידך","תנא קמא דמתני' דאמר מסדרין לבעל חוב דקתני אם מת אינו מחזיר ליורשיו הא לו מחזיר לעולם:"],[6,"האי","הוא דכתיב בערכין דריש ליה עד שיהא במכותו מתחילתו ועד סופו שאם העריך עצמו עני והעשיר קודם שהעריכו כהן אינו נידון בהשגת יד אלא נותן ערך עשיר:"],[7,"ויחזירו בהקדש","העבוט עד שלשים יום:"]],[[3,"הקדש שאין מחזירין אינו דין שאין מסדרין","וא\"ת ערכין יוכיח שאין מחזירין ומסדרין ויש לומר דמה לערכין שהם קלים ואינן נוהגים אלא באדם ובבן ברית ולא בטומטום ואנדרוגינוס ופחות מבן חדש אבל הקדש חל על כל דבר:"],[4,"ואידך ההוא לנדון בכבודו הוא דאתא","וא\"ת מ\"מ נילף נמי בהיקישא דמסדרין דאין היקש למחצה ואין לומר דהיקישא משמע דלא אתא אלא לנדון בכבודו דכתיב נדר בערכך נפשות דמשמע דבר שהנפש תלוי בו אבל לדבר אחר לא הוקשו דהא בפרק שום היתומים (ערכין ד' כד.) אמרינן מנין שלא ישהא מרגלית לקלים פירוש אם אמר ערכי עלי ויש לו מרגלית שוה מנה ובמקום שעומדין אינה שוה אלא חמשים לפי שאין שם עשירים שיקנו אותה מנין שאין להעריכה אלא בנ' זוזים שנאמר והיה ערכך ביום ההוא כמו ששוה ביום ההוא ובפ' השיג יד (שם דף יח.) אמרינן אתא הקשת הקדש לערכין לנידון בכבודו ולמרגלית לקלים והכא חד מינייהו אלמא לכל מילי מקשינן וצריך לומר דסברא דק\"ו מבטל הקישא כיון שנוכל להעמיד ההיקישא לדבר אחר. כן משמע בפרק קמא דזבחים (דף י:) דקאמר תנן התם ר\"ע אומר כל הדמים שנכנסו להיכל לכפר פסולים וחכ\"א חטאת בלבד ר' אליעזר אומר אף האשם שנאמר כחטאת כאשם ופריך בשלמא רבי אליעזר כדאמר טעמא אלא רבנן מאי טעמייהו אמר רבא אשם שנכנס דמו לפנים פסול לא מצית אמרת מק\"ו כו' אלמא ק\"ו מבטל הקישא דכחטאת כאשם כיון דאיכא לאוקמא הקישא לדבר אחר וההיא דס\"פ כל הבשר (חולין דף קטו:) דגמרי בשר בחלב אסור באכילה בג\"ש דקדש קדש מאנשי קודש תהיון לי וגו' ואיסור הנאה יליף מק\"ו מערלה ואית דדריש בג\"ש לגמרי לאיסור אכילה ולהיתר הנאה לא דמי להכא אפילו יהא הקישא וק\"ו כמו ג\"ש וק\"ו דאפילו מאן דיליף התם ק\"ו מצי סבר הכא דאין הקישא למחצה דהתם ע\"י ק\"ו אין סותר ג\"ש כלל משום דקרא דבשר בשדה טרפה דאיירי בבשר שיצא חוץ למחיצתו איירי גם באיסורי הנאה כגון בשר קדשים שיצא חוץ ממחיצתו שהוא בשריפה ומאן דלא יליף איסור הנאה בק\"ו משום ג\"ש היינו משום דאכילה והנאה חדא היא אבל הכא מודה דעבדינן ק\"ו למסדרין כיון דמתוקם ההיקש למילתא אחריתי וצ\"ע דבהרבה מקומות בת\"כ ובגמרא שרוצה לעשות ק\"ו וסותר אותו ע\"י היקש או ג\"ש אם יש בכל מקום שלא נוכל להעמיד ההיקש או הג\"ש לד\"א וא\"ת דאמרינן בערכין בפרק קמא (דף ד:) ראש חמור זה הקדש ראש עבד זה הקדש הוא והקדש שותפין בו ולא אמר דנידון בכבודו בערכין פריך לה ומשני כאן בקדשי מזבח כאן בקדשי בדק הבית דהכא מיירי בקדשי מזבח. ר\"י:"],[4,"מה ערכין נידון בכבודו","פי' בקונט' דדרשינן מנפשות וא\"ת מה צריך קרא דמאי שנא מנזקין דאם קיטע ידו אומדין כמה הוא יפה בידו וכמה הוא יפה בלא יד וה\"נ יש לנו לשום כמה הוא שוה באבר שהנשמה תלויה בו וכמה הוא שוה בלא ממנו דהיינו ערך כולו דאינו שוה כלום אם היה נוטל אותו אבר וי\"ל דאמר בפרק האומר משקלי (ערכין דף יט.) דאין שמין בערכין אומד של נזקין אלא שמין אותו כאילו היתה ידו מוכתבת לרבו ראשון ולא כמו שנטלה לגמרי דאז מתגנה העבד ושוה הרבה פחות וה\"נ אין שמין באבר שהנשמה תלויה בו אי לאו דכתיב נפשות:"],[5,"מה ערכין שאין מחזירין מסדרין","וא\"ת כיון שמסדרין ומניחין לו שיעור המפורש במשנה א\"כ מה חזרה שייך דהרי מניחין לו לגמרי כדי צרכו ומה יחזיר לו עוד ואור\"ת דכשנוטל ממנו בתורת פרעון אז מסדרין אבל כשנוטל בתורת משכון דחייבי ערכין ממשכנין אותן אז אין מסדרין ושייך חזרה:"],[6,"ואידך עד שיהא במכותו כו'","פירש בקונטרס דהיינו רבנן דמתני' ולפי' ר\"ת דלקמן דרבנן דמתניתין מצי סברי דאין מסדרין צ\"ל ואידך היינו הני דאיבעיא להו מהו שיסדרו בבעל חוב אי נמי ברייתא דתנא לעיל דמסדרין:"],[6,"במכותו מתחילתו ועד סופו","למעוטי עני והעשיר וחזר והעני דנותן ערך עשיר כרבי יהודה דבפרק השיג יד (שם דף יז:):"],[9,"מהו שיסדרו בבעל חוב","פסק ר\"ת בספר הישר דאין מסדרין בבעל חוב דהא רשב\"ג דמתני' מסיק לעיל דסבר דאין מסדרין בב\"ח וקי\"ל (ב\"ק דף סט.) הלכה כרשב\"ג במשנתנו היכא דלא פסק גמרא כמאן דפליג עליה ולא מצינו בכל אמוראים דשמעתא שום אמורא שסבר בהדיא שמסדרין ורבה בר אבוה דאמר ליה לאליהו מהו שיסדרו לבעל חוב וא\"ל גמר מיכה מיכה מערכין נראה לר\"ת דגרסינן מנין שמסדרין לבעל חוב כלומר מנליה למאן דאית ליה מסדרין וכן גריס בה\"ג וכן נראה דאי כגי' הספרים דקבעי מהו שיסדרו לבעל חוב הוה ליה למימר מסדרין שהרי הטעם לא היה שואל אלא ודאי מנין גרס ולעולם אין מסדרין ס\"ל ובפ' השיג יד (ערכין שם) דפליגי רבי יהודה ורבנן בעני והעשיר וחזר והעני דר' יהודה סבר נותן ערך עשיר ומפרש בגמרא דטעמא דרבי יהודה משום דכתיב ואם מך הוא עד שיהיה במכותו מתחילתו ועד סופו מכלל דרבנן דפליגי עליה דרשי הוא ולא בבעל חוב דדוקא בערכין מסדרין ולא בבעל חוב כדדריש לעיל ויחיד ורבים הלכה כרבים ויש לדחות דדרשינן הוא ולא אשתו כדדרשינן לעיל ועוד הביא ראיה דאמרי' בפ\"ק דב\"ק (דף יא: ושם ד\"ה אפילו) מיניה ואפילו מן גלימא דעל כתפיה וכי תימא דהיינו שמפשיטין אותו גלימא דאלפא זוזא ויהבינן ליה גלימא אחרינא דחזיא ליה הא ליכא מידי דלא חזי ליה כרשב\"ג דלעיל ועוד דפסיק רב אלפס בפרק שמנה שרצים (שבת דף קיא.) כר\"ש דאמר כל ישראל בני מלכים ומיהו אמרינן התם דפסיק כר\"ש ולא מטעמיה ורבנן דמתני' נמי מצי סברי דאין מסדרין ומיירי בבא ליטול בתורת משכון דרבנן סברי שמחזירין לו כל ימי חייו ורשב\"ג סבר דאחר שלשים יום מוכרו אבל היכא דנטל בתורת גבייה יכול למוכרו מיד ולא יסדרו כלל וא\"ת אמאי לא מייתי מרשב\"ג דאין מסדרין ויש לומר דסבר גמרא דשקלינן מידי דלא חזי ליה ויהבינן ליה מידי דחזי ליה כמו שלמעלה לא היה יודע הגמרא ואע\"ג ששנינו דרשב\"ג מתיר בלוף לא ידע דהוי טעמא דליכא מידי דחזי ליה ומר' עקיבא ור' ישמעאל דאמרי (לעיל בבא מציעא דף קיג:) כל ישראל ראויין לאותה איצטלא אין להוכיח דסבירא להו מסדרין דמיירי דגבה בתורת משכון דת\"ק סבר דמפשיטין אותה איצטלא בת מאה מנה ונותנין לו הראויה לו וממנה עושין השבת העבוט בכל יום ויום והמותר יהיה לו למלוה בתורת משכון ולא יחזיר אותו כלל ורבי עקיבא ור' ישמעאל סברי דמן הטובה עושה השבת העבוט אבל בתורת גבייה לא הדר כלל ומדמהדר ליה אליהו מיכה מיכה לא בעי למיפשט אפילו גרס מהו שיסדרו משום דאליהו דחויי הוה מדחי ליה והיה לו להשיב אין מסדרין תדע שהרי השיב לו קברי עובדי כוכבים אינם מטמאים באהל כר\"ש בן יוחי אע\"ג דלא קי\"ל כוותיה אלא כרשב\"ג דמתני' דאהלות דאסר מדורות עובדי כוכבים משום אהל וטעמיה דאליהו משום דרוב ארונות יש בהן פותח טפח ויש מקום שלא גזרו כגון. לצאת לקראת מלכים וכיוצא בו וכן מצינו כשהיה קובר את ר\"ע היה דוחה שאמר ליה וכי אינך כהן אמר ליה צדיקים אין מטמאין ודחה אותו כן משום כבודו דר\"ע ועיקר טעמו היה לפי שהיה מת מצוה לפי שהיו יראים לקברו שהיה מהרוגי מלכות וכן נמצא בתשובת גאון שכתב שיש בסדר אליהו רבה שנחלקו עליו יש אומרים שהיה מבני בני בניה של לאה ואמר להם איני אלא מזרעה של רחל וא\"כ לא היה כהן וכאן אומר שכהן היה ומסיים התם אמרו לו תן סימן לדבריך אמר להן כך כתוב ביחוסו של בנימין ויערשיה ואליה וזכרי בני ירוחם אמרו לו לא כך אמרת לאותה אלמנה. עשי לי משם עוגה קטנה ולך ולבנך תעשה באחרונה ולא כהן אתה פי' לפי שכהן הוא היה רוצה ליטול חלה תחילה אמר להם אותו תינוק משיח בן יוסף היה ורמז רמזתי לעולם שאני בא תחילה ובאותה תשובה מביא נמי הא דגמרי' מיכה מיכה וגרס מנין שמסדרין לבעל חוב כמו שגורס ר\"ת וכן בב\"ר גבי ותאמר לאה בגד נחלקו רבי נהוראי אמר דאליהו מגד ור\"א אמר משל בנימין ועמד לפניהם ואמר להם רבותי למה אתה נחלקים עלי אני מבני בניה של רחל:"]]],[["מנין לערום שלא יתרום דכתיב (דברים כג, טו) ולא יראה בך ערות דבר","אמר ליה לאו כהן הוא מר מאי טעמא קאי מר בבית הקברות א\"ל לא מתני מר טהרות דתניא ר\"ש בן יוחי אומר קבריהן של עובדי כוכבים אין מטמאין שנאמר (יחזקאל לד, לא) ואתן צאני צאן מרעיתי אדם אתם אתם קרויין אדם ואין עובדי כוכבים קרויין אדם","אמר ליה בארבעה לא מצינא בשיתא מצינא א\"ל ואמאי אמר ליה דחיקא לי מילתא דבריה ועייליה לגן עדן אמר ליה פשוט גלימך ספי שקול מהני טרפי ספא שקל","כי הוה נפיק שמע דקאמר מאן קא אכיל לעלמיה כרבה בר אבוה נפץ שדנהו אפילו הכי אתייה לגלימיה סחט גלימא ריחא זבניה בתריסר אלפי דינרי פלגינהו לחתנוותיה","ת\"ר (דברים כד, יב) ואם איש עני הוא לא תשכב בעבוטו הא עשיר שכיב מאי קאמר אמר רב ששת הכי קאמר ואם איש עני הוא לא תשכב ועבוטו אצלך הא עשיר שכיב ועבוטו אצלך","ת\"ר המלוה את חבירו אינו רשאי למשכנו ואינו חייב להחזיר לו ועובר בכל השמות הללו מאי קאמר אמר רב ששת הכי קאמר המלוה את חבירו אינו רשאי למשכנו ואם משכנו חייב להחזיר לו ועובר בכל השמות הללו אסיפא","רבא אמר הכי קאמר המלוה את חבירו אינו רשאי למשכנו ואם משכנו חייב להחזיר לו במה דברים אמורים שמשכנו שלא בשעת הלואתו אבל משכנו בשעת הלואתו אינו חייב להחזיר לו ועובר בכל השמות הללו ארישא","תני רב שיזבי קמיה דרבא (שמות כב, כה) עד בא השמש תשיבנו לו זו כסות לילה (דברים כד, יג) השב תשיב לו את העבוט כבוא השמש זו כסות יום אמר ליה דיממא בליליא למה לי ודליליא ביממא למה לי","אמר ליה איסמייה אמר ליה לא הכי קאמר עד בא השמש תשיבנו לו זו כסות יום שניתנה לחבול בלילה השב תשיב לו את העבוט כבוא השמש זו כסות לילה שניתנה לחבול ביום","אמר ר' יוחנן משכנו ומת שומטו מעל גבי בניו מיתיבי אמר ר' מאיר וכי מאחר שממשכנין למה מחזירין למה מחזירין רחמנא אמר אהדר אלא מאחר שמחזירין"],[[0,"ערות דבר","בשעה שאתה מדבר בו לא יראה בך ערות דבר שמע מינה אין אדם מברך כשהוא ערום ותורם בעי ברכה והאי דבעי מיניה לענין תורם דהתם תנן (תרומות פ\"א מ\"ו) אין מגביהין תרומה ערום:"],[1,"לאו כהן מר","דאיכא למ\"ד דאליהו הוא פינחס דכתיב ביה קנא קנאתי וכן בפינחס בקנאו את קנאתי:"],[1,"אין מטמאין","דגבי אהל כתיב אדם (במדבר י״ט:י״ד) אדם כי ימות באהל:"],[2,"בארבעה לא מצינא","בגירס' דארבעה סדרין כגון מועד ישועות נשים שהן נוהגות בזמן הזה כבזמן הבית וקדשים נמי כדכתיב ובכל מקום מוקטר מוגש לשמי ואמרי' (מנחות דף קי.) אלו תלמידי חכמים העוסקין בהלכות עבודה בכל מקום מעלה עליהן הכתוב כאילו מקריבין אותן בבית המקדש:"],[2,"בשיתא מצינא","בתמיהה זרעים אינו נוהג בחוצה לארץ וכן טהרות:"],[2,"ספי","לקוט:"],[2,"טרפי","עלין:"],[3,"נפץ","אשקוש\"ט בלעז:"],[3,"סחט גלימא","נסחט ריח מתוך העלין לתוך טלית וקלטה טליתו את הריח:"],[3,"וזבני'","לגלימ' בי\"ב אלפי דינרי:"],[4,"לא תשכב בעבוטו","הא עשיר שכיב בעבוטו:"],[4,"מאי קאמר","וכי בשביל שהוא עשיר התירו לשכב על טליתו והרי הוא רבית אצלו שישתמש במשכונו חנם:"],[4,"הכי קאמר לא תשכב ועבוטו בידך","אלא השיבנו לו כבוא השמש כדכתיב השב תשיב לו את העבוט כבוא השמש:"],[5,"","ה\"ג המלוה את חבירו אינו רשאי למשכנו ואינו חייב להחזיר לו:"],[5,"ועובר בכל השמות הללו","השב תשיב ולא תשכב בעבוטו ועד בא השמש תשיבנו לו:"],[5,"מאי קאמר","דקתני אינו חייב להחזיר לו ועוד הדר תני עובר בכל השמות הללו (עובר בכל השמות הללו) השב תשיב לא תשכב בעבוטו ועד בא השמש תשיבנו:"],[5,"אסיפא","אם לא החזיר:"],[6,"ורבא אמר הכי קאמר וכו'","לא טעי תנא במאי דאתנייה חייב להחזיר לאוסופי ולמימר אינו חייב להחזיר אלא ודאי אינו חייב להחזיר נמי אתנייה והכי קאמר וכו' ושכח וחיסר ודילג מחייב להחזיר באינו חייב להחזיר:"],[6,"שמשכנו שלא בשעת הלואתו","בבית דין:"],[6,"אבל משכנו בשעת הלואתו","שהביא לו משכונו:"],[6,"אינו חייב להחזיר","דקראי בחובלו לאחר הלואה כתיב דהיכא דאתייה ניהליה לאו חובלו הוא:"],[6,"ארישא","אמשכנו שלא בשעת הלואתו ולא החזיר לו עובר בכל השמות הללו:"],[7,"עד בא השמש תשיבנו לו","משמע בבוקר תשיבנו לו ויהא בידו עד בא השמש ויקח לו ממנו:"],[7,"זה כסות לילה","לקמן פריך דלילה לאהדורי ליה ביממא למה ל:"],[7,"כבא השמש","בלילה החזירו לו:"],[8,"איסמייה","אסיר ברייתא זו מסדר משנתי:"],[8,"אמר ליה לא","תסמייה דהא כסות לילה וכסות יום דקאמר לאו תשמיש יום ותשמיש לילה קאמר אלא כסות העשויה למשכן בלילה וכסות העשויה למשכן ביום קאמר והכי קאמר עד בא השמש תשיבנו לו וכבא השמש תטלנו. זה כסות יום ולימדך הכתוב שניתנה לו רשות לחובלה בלילה ולענין חבלה קרי ליה כסות לילה:"],[9,"משכנו ומת","לוה לאחר שהשיב לו את העבוט:"],[9,"שומטו","מלוה מעל גבי בניו ואין נעשה אצלו כשאר מטלטלים שלהן דלא משתעבדי לב\"ח דכיון דמשכניה קנייה:"]],[[0,"מנין לערום שלא יתרום","הוה ליה למימר מנין שלא יברך דבשעה שתורם ממנו אינו אסור אלא בשעת ברכה ושאר ברכות אסור לברך כשהוא ערום אלא נקט הכי משום דמשנה היא ערום לא יתרום:"],[1,"אמר ליה לאו כהן (אתה)","תימה לר\"י היאך החיה בנה של האלמנה כיון שכהן היה דכתיב (מלכים א יז) ויתמודד על הילד וגו' ויש לומר שהיה ברור לו שיחייהו לכך היה מותר משום פיקוח נפש:"],[1,"ה\"ג דתניא ר' שמעון [בן יוחי] אומר","דאינה משנה בשום מקום ועוד דמשניות אף של זרעים וטהרות היו שגורות להם כדמשמע בכמה. דוכתין והא דקאמר בארבע לא מצינא בשיתא מצינא היינו בתוספתא:"]]],[["למה חוזרין וממשכנין שלא תהא שביעית משמטתו ולא יעשה מטלטלין אצל בניו","טעמא דהדר ומשכניה הא לא הדר ומשכניה לא","אמר רב אדא בר מתנא ולאו תרוצי קא מתרצת לה תריץ הכי וכי מאחר שמחזירין למה ממשכנין מעיקרא שלא תהא שביעית משמטתו ולא יעשה מטלטלין אצל בניו","ת\"ר (דברים כד, י) לא תבא אל ביתו לעבוט עבוטו לביתו אי אתה נכנס אבל אתה נכנס לביתו של ערב וכן הוא אומר (משלי כ, טז) לקח בגדו כי ערב זר וגו'","ואומר (משלי ו, א) בני אם ערבת לרעך תקעת לזר כפיך נוקשת באמרי פיך נלכדת באמרי פיך עשה זאת אפוא בני והנצל כי באת בכף רעך לך התרפס ורהב רעיך","אם ממון יש לו בידך התר לו פיסת יד ואם לאו הרבה עליו רעים","לצד שני לביתו אי אתה נכנס אבל אתה נכנס לשכר כתף לשכר חמר לשכר פונדק לשכר דיוקנאות יכול אפילו זקפן עליו במלוה ת\"ל משאת מאומה:","\u0001מתני'\u0002 אלמנה בין שהיא ענייה בין שהיא עשירה אין ממשכנין אותה שנאמר (דברים כד, יז) לא תחבול בגד אלמנה:","\u0001גמ'\u0002 ת\"ר אלמנה בין שהיא ענייה בין שהיא עשירה אין ממשכנין אותה דברי ר' יהודה","ר\"ש אומר עשירה ממשכנין אותה ענייה אין ממשכנין אותה שאתה חייב להחזיר לה ואתה משיאה שם רע בשכנותיה","למימרא דר' יהודה לא דריש טעמא דקרא ור\"ש דריש טעמא דקרא והא איפכא שמעינן להו","דתניא (דברים יז, יז) ולא ירבה לו נשים ר' יהודה אומר מרבה הוא ובלבד שלא יהו מסירות את לבו ר\"ש אומר אפילו אחת והיא מסירה את לבו ה\"ז לא ישאנה א\"כ מה ת\"ל ולא ירבה לו נשים אפילו כאביגיל","לעולם ר' יהודה לא דריש טעמא דקרא ושאני הכא דמפרש קרא ולא ירבה לו נשים ולא יסור מאי טעמא לא ירבה לו נשים משום דלא יסור","ור\"ש מכדי בעלמא דרשינן טעמא דקרא לכתוב רחמנא לא ירבה ולא בעינן לא יסור ואנא ידענא מאי טעמא לא ירבה משום דלא יסור לא יסור דכתב רחמנא למה לי אפילו אחת ומסירה את לבו הרי זה לא ישאנה:","\u0001מתני׳\u0002 החובל את הריחים עובר משום לא תעשה וחייב משום שני כלים שנאמר (דברים כד, ו) לא יחבול ריחים ורכב ולא ריחים ורכב בלבד אמרו אלא כל דבר שעושין בו אוכל נפש שנאמר כי נפש הוא חובל:","\u0001גמ׳\u0002 אמר רב הונא חבל ריחים לוקה שתים משום ריחים ומשום כי נפש הוא חובל ריחים ורכב לוקה שלש משום ריחים ורכב ומשום כי נפש הוא חובל","ורב יהודה אמר חבל ריחים לוקה אחת ורכב לוקה אחת ריחים ורכב לוקה שתים כי נפש הוא חובל"],[[0,"למה חוזרין וממשכנין","הרי עליו להחזיר לו למחר:"],[0,"שלא תהא שביעית משמטתו","דלהוי משכונו בידו והמלוה על המשכון אינו משמט:"],[0,"ולא יעשה מטלטלין אצל בניו","שלא ימות בעוד המשכון מוחזר לו ויהא מטלטלין אצל בניו:"],[1,"טעמא דהדר משכניה","שהיה בידו כשמת לוה:"],[2,"למה ממשכנין מעיקרא","דבר שעליו להחזיר מה מועיל לו:"],[2,"שלא תהא שביעית משמטתו וכו'","דמדמשכניה קנייה וכי מהדר ליה הוה פקדון גביה:"],[4,"בני אם ערבת לרעך או אם נוקשת באמרי פיך","שהוניתו בדברים:"],[4,"עשה זאת והנצל","התרפס יד אם ערבת ואם לא ערבת אלא נוקשת באונאת דברים רהב רעיך הרבה עליו רעים לבקש מחילה:"],[5,"אם ממון יש לו בידך","אם נעשה לו ערב ואם נוקשת בדברים רהב רעיך:"],[6,"לצד שני","כמו דבר אחר:"],[6,"לביתו","של לוה במלוה אי אתה נכנס אבל אתה נכנס למשכנו חוב אחר שאינה מלוה:"],[6,"שכר פונדק","השכיר לו פונדק:"],[6,"דיוקנאות","צר לו צורות בביתו בשכר:"],[9,"משיאה שם רע","שאתה יוצא ונכנס אצלה שחרית וערבית:"],[13,"מכדי בעלמא דריש טעמא דקרא","אע\"ג דלא מפרש טעמא כדאוקימנא גבי חובל:"],[14,"מתני' משום שני כלים","העליונה רכב והתחתונה ריחים:"]],[[2,"למה ממשכנין מעיקרא","הקשה ה\"ר אלחנן ולמה חוזרים וממשכנין וי\"ל כדי שלא יוכל הלוה לכפור וגם ימהר לפרוע חובו ולבקש מעות כי מתבייש שבכל יום ויום יחזירו משכונו ומ\"מ לא רצה הגמרא לתרץ כן כשאומר למה ממשכנו מעיקרא דעדיפא מיניה משני ליה:"],[7,"אלמנה בין שהיא ענייה בין שהיא עשירה אין ממשכנין אותה","וא\"ת אמאי לא פריך מהכא לשמואל דמשמע הא אחרים ממשכנין וליכא למימר דהאי אין ממשכנין דהיינו אין מנתחין הא אחרים מנתחין דהא לא תחבול כתיב דמשמע בבית ומנלן לאסור ניתוח דמדרבנן ליכא למיגזר בשליח ב\"ד גזירה שמא יכנס בביתו דבשליח ב\"ד ליכא למיגזר מדשרי בעלמא לנתח ולא גזרינן ואין סברא לגזור באלמנה יותר משום דאית בה תרי לאוין וי\"ל דלכך לא פריך ממתניתין דהכא משום דאיכא למידחי אין ממשכנין אותה משום לאו דלא תחבול הא אחרים לית בהו האי לאו לכך עדיפא ליה למיפרך מברייתא ור\"ש דקאמר בגמ' עשירה ממשכנין אותה איכא למימר נמי דסבר כשמואל וממשכנין היינו מנתחין דלדידיה ענייה דקאמר אין ממשכנין אותה היינו אין מנתחין דטעמא דאתה משיאה שם רע בשכנותיה שייך אפילו בניתוח והא דכתב רחמנא לא תחבול ולא כתיב לא תנתח היינו כדי לחייב על משכון שני לאוין אבל קשה דאי סבר ר\"ש כשמואל ולא שרי בעשירה אלא ניתוח ות\"ק שרי ניתוח בין בעשירה בין בענייה א\"כ מחמיר ר\"ש יותר מת\"ק ולשון הברייתא משמע שבא להקל ולהתיר בעשירה מה שאסר ת\"ק לכך נראה דר\"ש לית ליה דשמואל ומתיר למשכן עשירה ושאר בני אדם וה\"מ למפרך שפיר לשמואל מר\"ש אלא דלא איירי ר\"ש במתני' אלא בבריית' ושפיר פריך מברייתא אחריתי ועוד נראה לפרש דלכ\"ע לא יחבול ריחים ולא תחבול בגד אלמנה אתא קרא לאסור בה ניתוח דשרי בעלמא והא דאפקיה בלשון חבלה ולא בלשון ניתוח כדי לעבור במשכון בשני לאוין ולהכי לעיל כי אקשינן מינייהו לשמואל איצטריך לשנויי לעבור בשני לאוין ולא קאמר לאסור ניתוח משום דהוה קשה ליה אמאי אפקיה בלשון חבלה ואע\"ג דאיצטריך לשני לאוין לשמואל מ\"מ מיסתבר דעיקר קרא אתא לאסור ניתוח דשרי בעלמא ולא ללאו יתירא לחוד והשתא לא קשה לשמואל מידי מפלוגתא דרבי יהודה ור\"ש דהשתא אין ממשכנין אותה היינו אין מנתחין אותה ולהכי לא פריך מיניה דפשיטא דכי היכי דמשנינן לא ימשכננו אלא בב\"ד לא ינתחנו דה\"נ איכא לשנויי הכא ופי' זה נראה עיקר דאסור גם לשמואל ניתוח אפי' בכלים שעושין בהן אוכל נפש דלפי' קמא דלא אתא לשמואל אלא ללאו יתירא ולא לאסור ניתוח לא אתי שפיר דלמאן דפליג עליה נראה דבריחים ורכב אסור אפי' ניתוח דכיון דשליח ב\"ד בדברים אחרים מותר אפילו למשכן ובריחים ורכב אסור ה\"ה אפילו ניתוח דשרי בעלמא אפילו למלוה דאסור בריחים ורכב דמיסתבר לאסור כל משכונה שמישכן בשוה אבל לשמואל שאינו מתיר למשכן לשליח ב\"ד בדברים אחרים אלא ניתוח יש לנו לומר דבריחים ורכב נמי דוקא משכון הוא דאסור כמו שכתוב ולא ניתוח ונמצא ששמואל דמשמע דבא להחמיר מיקל יותר לענין ריחים ורכב שמתיר לנתח ומאן דפליג עליה אסר כדפרישית:"],[14,"וחייב משום ב' כלים","פי' אפילו בהתראה אחת אם חבל בפעם אחת ריחים ורכב והתרו בו משום לא יחבול ריחים ורכב לוקה שתים דאי בשתי התראות אפי' ריחים וריחים חייב כדאמר גבי נזיר (מכות דף כא.) אמרו לו אל תשתה אל תשתה חייב על כל אחד ואחד ואין לומר לעולם איירי בשתי התראות וקא משמע לן דריחים ורכב אינם כלי אחד שלא להתחייב אלא עד שיחבול שניהם דא\"כ ה\"ל למיתני החובל ריחים או רכב בלא תעשה כו' ותו לא אלא ודאי אתא לאשמועינן דבהתראה אחת חייב שתים וכן משמע בהדיא בגמ' דחייב שתים בריחים ורכב בהתראה אחת דאמר רב הונא חבל ריחים ורכב לוקה ג' והיינו בהתראה אחת דאי בשתי התראות לוקה שתים על הריחים ושתים על הרכב וכיון דבהתראה אחת איירי א\"כ חייב שתים דקתני היינו שתי מלקיות ותימה דהיכי לקי והא חשיב לה בגמרא (דף קטז.) לאו הניתק לעשה מדאמר ליה אביי זיל אהדר וכי תימא דמש\"ה א\"ל לאהדורי דכל מילתא דאמר רחמנא לא תעביד אי עביד לא מהני הא אביי גופיה קאמר בפ\"ק דתמורה (דף ד:) דאי עביד מהני ואין לומר דהאי דלקי היינו כגון ששבר הריחים ואת הרכב דשוב אינו ניתק לעשה שאינו יכול להחזיר הריחים ולהכי לקי כדאמרינן בפרק שילוח הקן (חולין דף קמא.) דאם הרג את האם שוב לא חשיב ניתק לעשה ולקי הא ליכא למימר דשאני הכא כיון דמפסיד בחובו כנגד הריחים הרי כאילו החזיר הריחים עצמו והוי לעולם ניתק לעשה כדאמר בפרק בתרא דמכות (דף טז.) אהשבת העבוט דהוי ניתק לעשה אפילו נאבד לו העבוט משום דכיון דאיתיה בתשלומין לא לקי ועוד דלא משכחינן במכות ביטלו ולא ביטלו בשום לאו הניתק לעשה כמו בשילוח הקן ובפאה שלא הפריש ואכל הכל ואם הלאו דחבלת ריחים חשיב ניתק לעשה ואם שיבר לוקה ה\"ל למיחשבי' נמי התם וע\"ק דהיכי חשיב ליה אביי ניתק לעשה הא לא אשכחן דנתקו הכתוב כדאשכחן גבי השבת העבוט דלא תבא אל ביתו לעבוט עבוטו דהתם ודאי נתקו הכתוב דכתיב השב תשיב מ\"מ אפי' משכנו באיסור ולהכי חשיב בפרק בתרא דמכות (שם) לאו הניתק לעשה וי\"ל דטעמא דאביי דא\"ל לאהדורי משום דאי עביד לא מהני כיון שהיה שוגג שאם היה יודע שהוא אסור לא היה חובלו והוה ליה זכייה בטעות וחוזרת:"]]],[["לשאר דברים הוא דאתא","לימא אביי ורבא בפלוגתא דרב הונא ורב יהודה קמיפלגי","דאמר רבא אכל נא לוקה שתים משום נא ומשום (שמות יב, ט) כי אם צלי אש מבושל לוקה שתים משום מבושל ומשום כי אם צלי אש נא ומבושל לוקה שלש משום נא ומשום מבושל ומשום לא תאכלנו כי אם צלי אש","אביי אמר אין לוקין על לאו שבכללות לימא אביי דאמר כרב יהודה ורבא דאמר כרב הונא","אמר לך רבא אנא דאמרי אפילו כרב יהודה עד כאן לא קאמר רב יהודה התם אלא דכי נפש הוא חובל לא משמע ריחים ורכב הלכך לשאר דברים הוא דאתא","אבל הכא כי אם צלי אש למאי אתא ש\"מ ללאו","ואביי אמר לך אנא דאמרי אפילו לרב הונא ע\"כ לא קאמר רב הונא התם אלא דכי נפש הוא חובל"],[[0,"גמ' לשאר דברים","ולאו לאוסופי לאו אריחים ורכב דהא ריחים ורכב כתיב ברישא ואיצטריך כי נפש לרבות שאר כלים של אוכל נפש:"],[3,"על לאו שבכללות","משום לא תאכלנו כי אם צלי אש דכייל נא ומבושל ואין לוקין אלא על נא ומבושל שהן מפורשין:"],[3,"אביי כרב יהודה","דהיכא דעבר על הכלל ועל הפרט והן שניהן בלאו אחד לא לקי אכללא:"],[4,"עד כאן לא קאמר רב יהודה התם","דלא מהני כי נפש לאוסופי לאוי יתירי אריחים ורכב:"],[4,"אלא משום דכי נפש","דמרבי שאר דברים אי לאו דכתיב ביה לא מישתמעי ליה מריחים ורכב דה\"א הנך דוקא הלכך לשאר דברים אתא ולא תישדייה נמי אהני דמפרש לאו דידהו לאטפויי לאוי:"],[5,"אבל הכא","אי לאו לטפויי לאוי אנא ומבושל אתא:"],[5,"כי אם צלי אש למאי אתא","אין לך דבר שאינו בכלל נא ומבושל חוץ מצלי דניתי לאזהורי לאו עלייהו ואי אשמעינן מצות צלי קרא אחרינא כתיב צלי אש ומצות וגו':"]],[[1,"לימא אביי ורבא בפלוגתא דרב הונא ורב יהודה קמיפלגי","וא\"ת טעמא דרב יהודה הוי משום דכי נפש הוא חובל לשאר דברים הוא דאתא ולא משום לאו שבכללות כדקאמר אביי וי\"ל שכן דרך הגמ' דאע\"ג שכבר פירש הטעם אומר לימא דכשנאמר הלימא בבית המדרש עדיין לא נודע להם טעם המפורש אלא היה סבור דטעמא דרב יהודה משום דאין לוקין על לאו שבכללות ולרב הונא לוקין וכה\"ג איכא נמי בפרק החולץ (יבמות דף לח.) גבי ספק ובני יבם שבאו לחלק בנכסי יבם דאחר שכבר פירש דטעמא של אדמון ורבנן כמו שמפרש לבסוף כשדוחה הלימא שלא נחלקו בקם דינא והדר דינא אמר אחרי כן לימא דמ\"ד קם דינא כרבנן ומ\"ד הדר דינא כאדמון:"],[4,"אמר לך רבא אנא דאמרי אפי' לרב יהודה כו'","תימה והא גבי זג וחרצן נמי נחלקו בפ' ג' מינין (נזיר דף לח:) ובפרק כל שעה (פסחים דף מא:) דרבא אמר אכל זג וחרצן לוקה ג' משום זג וחרצן ומשום כל אשר יעשה אע\"ג דמכל אשר יעשה אתא לשאר דברים דמרבה בפרק ג' מינים וי\"ל דמכל אשר יעשה משמע שהוא בלשון לאו יותר מכולם ולהכי מוקמינן ליה ללאו אזג וחרצן אע\"ג דצריך נמי לשאר דברים א\"נ כי נפש הוא חובל משמע דלא אתא אלא לשאר דברים ולא לאטפויי לאוי על ריחים ורכב דודאי אי הוה כתיב כל נפש הוא חובל כדכתיב (במדבר ו׳:ד׳) מכל אשר יעשה הוה קאי נמי אריחים ורכב וא\"ת אביי מ\"מ לא יוכל לדחות אזג וחרצן כמו שדוחה הכא אפלוגתא דנא ומבושל ע\"כ לא קאמר רב הונא אלא משום דכי נפש הוא חובל קרא יתירא הוא ופי' בקונטרס וכי היכי דאתא לשאר דברים אתא נמי לריחים ורכב וא\"כ בזג וחרצן נמי נימא לילקי ג' דכי היכי דאתא לשאר אתא נמי לזג וחרצן וי\"ל דלא נפרש כפירוש הקונט' אלא הכי פי' נפש הוא חובל קרא יתירא הוא ולא צריך לשאר דברים דשמעינן להו מריחים ורכב דלא הוו ב' כתובים הבאים כאחד דהא איצטריכו לחייב עליהם משום ב' כלים ולא איצטריך כי נפש הוא חובל לשאר דברים טפי מלריחים ורכב ולהכי שדייה נמי אריחים ורכב אבל כל אשר יעשה מגפן היין לשאר דברים דוקא הוא דאתא דלא שמעינן להו מזג וחרצן ומיהו גם על פי' הקונט' לא קשה דלהכי לא הביא ההוא דזג וחרצן לפי שאינו יכול לדחות ואינו מביא אלא דבר שיכול לדחות וכן דרך הגמ' שאינו מתחיל אלא כדי להוכיח ולהראות דמהכא ליכא למשמע מינה וכי דחי נמי דרב הונא כאביי היינו במאי דקאמר אביי אכל נא ומבושל לוקה שתים ואינו לוקה משום כי אם צלי אש דכי אם צלי אש אתא לכדתניא אבל במאי דמפרש טעמא דאביי משום דאין לוקין על לאו שבכללות לא מצי סבר כרב הונא דהא כי נפש הוא חובל הוי נמי לאו שבכללות ולקי עליה לרב הונא וא\"ת ואמאי איצטריך אביי הכא טעמא דאין לוקין משום כי אם צלי אש משום דהוי לאו שבכללות תיפוק ליה דאיצטריך לכדתניא וי\"ל דגמ' הוא דקמפרש ומפרש ההוא טעמא אליביה משום דידע גמרא דאביי אית ליה הכי בעלמא גבי זג וחרצן ושאור ודבש א\"נ אביי לדבריו דרבא קאמר וה\"ק לדידי לא אתי כי אם צלי אש ללאו אלא להקישא נכתב אלא אפי' לדידך דללאו אתא אין לוקין על לאו שבכללות ומטעמא דאמר אביי אין לוקין אלאו שבכללות קאמר בסוף פרק כל שעה תרתי הוא דלא לקי חדא מיהא לקי אבל לטעמא דמפרש כאן אביי אליבא דרב הונא דכי אם צלי אש לכדתניא אפי' חדא לא לקי:"],[4,"שנאמר לא יחבול ריחים ורכב","וא\"ת לר' יאשיה מנלן דחייב על כל אחת בפני עצמו כיון דמצריך או לחלק ולר' יונתן נמי דלא מצריך לחלק מנלן דחייב שתים משום ב' כלים כיון דבלאו אחד נאמרו דהכי אמרינן בסוף גיד הנשה (חולין דף קב: ושם ד\"ה לר\"י) לר' (יונתן דלא לקי אלא חדא אם אכל בשר מן החי ובשר מן הטריפה משום דתרוייהו בלאו אחד נאמרו ומיהו לר' יאשיה י\"ל כיון דכתיב ורכב ולא כתיב רכב הוי כאילו כתיב או רכב וכן בנא ומבושל כתיב ממנו דמשמע אפילו באחד מהן וכן גבי שאור ודבש דאמרינן בפרק כל המנחות (מנחות דף נח: ושם ד\"ה אין) דלוקה על כל אחד בפני עצמו דכתיב לא תקטירו ממנו וגבי חרצן וזג כתיב ועד דמשמע שפיר לחלק ועוד דגבי ריחים ורכב אי לא מיחייב אלא על שניהם יחד לשתוק קרא מרכב ולא לכתוב אלא ריחים דמשמע שניהם ביחד אבל קשה לר' יאשיה מנלן דחייב שתים כיון דבלאו אחד נאמרו אבל לר' יונתן דאיצטריך חילוק בכולהו חייב על כל אחד ושמא יש לומר דגם לר' יאשיה כיון דאיכא קראי בכולם לחלק חייב על כל אחד דלא דמי לבשר בשדה טריפה דליכא שום חילוק א\"נ יש לומר כיון שהאיסורין מפורשין קאי לאו אכל אחד ואחד כדפי' בקונטרס בפרק בתרא דמכות (דף יח.) גבי לא תוכל לאכול בשעריך מעשר דגנך וגו' דלא חשיב לאו שבכללות אפילו הוה כתיב לא תוכל לאכלם ואם אכל מכולם היה חייב על כל אחד ואחד דלא דמי לבשר בשדה טריפה ולא תאכל הנפש עם הבשר דמשמע דליכא אלא חדא מילתא אע\"ג דדרשינן מניה תרי מילי כיון דכתיב בלשון איסור אחד אין חייב אלא אחת והא דמצרכי' קרא לחלק בין אלמנה שהיא גרושה לכ\"ג בפרק עשרה יוחסין (קדושין עז:) היינו משום דבגוף אחד אין לחייב שתים בלא פסוק ולכך צריך יתור לחייב שתים באשה אחת וא\"ת דבפ\"ק דכריתות (דף ד.) אמרינן דבחלב שור וכשב ועז לא לקי אלא חדא וכן לחם קלי וכרמל וכן מעשר דגן ותירוש ויצהר לא הוי לקי אלא חדא אי לאו דאיכא קראי יתירי בפ\"ק דכריתות וי\"ל דזג וחרצן שני שמות נינהו וכן ריחים ורכב וכן כולם אבל חלב שור וכשב ועז שם חלב אחד הוא וכן שם לחם וכן שם מעשר אחד הוא:"],[5,"אבל [הכא] כי אם צלי אש למאי אתא","וא\"ת והא איצטריך לכדתניא כדקאמר אביי וי\"ל דרבא עביד הקישא מצלי אש דכתיב בקרא דלקמיה צלי אש ומצות על מרורים יאכלוהו (שמות י״ב:ח׳-ט׳) וסמיך ליה אל תאכלו ממנו נא וגו' אע\"ג דבברייתא פ' כל שעה (פסחים דף מא:) נקיט קרא דכי אם צלי אש לאו משום דמיניה דריש אלא ניחא ליה למנקט קרא גופיה דנא ומבושל ואביי סבר דדוקא נקט ליה ברייתא כי אם צלי אש אבל קרא אחריתי לא סמיכה הוא וא\"ת והא אכתי איצטריך כי אם צלי לחי ומבושל בחמי טבריא דרבא גופיה קאמר בסוף פ' כל שעה (שם.) מאי חייב דקאמר משום כי אם צלי אש גבי מבושל בחמי טבריא וי\"ל דאינו לוקה בחי ומבושל בחמי טבריא כדתניא התם יכול יהא לוקה ת\"ל נא ומבושל נא ומבושל אמרתי לך ולא חי ובשמעתין ה\"ק רבא כי אם צלי אש למאי אתא פי' לאיזה לאו ללקות אם לא לטפויי לאוי על נא ומבושל וא\"ת הא כי נפש הוא לרב יהודה קאמר רבא דאתא לדברים אחרים ללקות עליהם ולא אמרי' ריחים ורכב אמרתי לך ולא שאר דברים וי\"ל דכי נפש הוא חובל מזכיר האיסור שעושה שחובל לכך אתי לשאר דברים ללקות עליהם אבל כי אם צלי אש אינו מזכיר שם איסור ולכך לא אתי ללקות על דברים אחרים כי אם אנא ומבושל שכתב בהן לאו בהדיא השתא משמע הכא דאפילו לרבא אין לוקין אחי ומבושל בחמי טבריא מדקאמר אלא כי אם צלי אש למאי אתא וכ\"ש לאביי דאמר אין לוקין על לאו שבכללות ומוקי כי אם צלי אש לכדתניא ומכאן קשה על פירוש הקונט' דפי' בפרק כל שעה (פסחים דף מא.) דההיא ברייתא דקתני נא ובשל אמרתי לך ולא חי אתא כמ\"ד אין לוקין על לאו שבכללות ועוד דתיקשי מיניה לרבא דאמר לוקין ועוד פירש בקונט' אהא דקאמר התם תרתי הוא דלא לקי לאביי דאמר אין לוקין על לאו שבכללות חדא מיהא לקי ופירש על נא אינו לוקה שתים משום נא ומשום כי אם צלי אש אבל במילתא אחריתי דלא שייך אלא כי אם צלי אש כגון חי ומבושל בחמי טבריא לוקה והשתא נראין דבריו כסותרין זה את זה דהשתא ברייתא לא אתיא אפילו כאביי לכך נראה דברייתא אתיא לכ\"ע ולא לקי בשום ענין אחי ומבושל בחמי טבריא כדפרישית לעיל והא דקאמר חדא מיהא לקי מפרש ר\"ת תרתי לא לקי דאם התרו בו משום נא ומשום כי אם צלי אש אינו עובר אלא משום נא וכן במבושל אבל היכא דלא התרו בו אלא משום כי אם צלי אש כשאוכל נא ומבושל לוקה:"]]],[["יתירא הוא כיון דיתירא הוא שדייה אריחים ורכב","אבל הכא כי אם צלי אש לאו יתירא הוא דמבעי ליה לכדתניא בשעה שישנו בקום אכול צלי ישנו (שמות יב, ט) בבל תאכל נא בשעה שאינו בקום אכול צלי אינו בבל תאכל נא","תניא כוותיה דרב יהודה חבל זוג של ספרים וצמד של פרות חייב שתים זה בעצמו וזה בעצמו אינו חייב אלא אחת","ותניא אידך חבל זוג של ספרים וצמד של פרות יכול לא יהא חייב אלא אחת ת\"ל (דברים כד, ו) לא יחבול ריחים ורכב מה ריחים ורכב שהן מיוחדין שני כלים ועושין מלאכה אחת וחייב על זה בפני עצמו ועל זה בפני עצמו אף כל דברים שהן שני כלים מיוחדים ועושין מלאכה אחת חייב על זה בפני עצמו ועל זה בפני עצמו","ההוא גברא דחבל סכינא דאשכבתא מחבריה אתא לקמיה דאביי א\"ל זיל אהדריה דהוי ליה כלי שעושים בו אוכל נפש ותא קום בדינא עלה רבא אמר לא צריך למיקם בדינא עלה ויכול לטעון עד כדי דמיהן","ואביי לית ליה ההיא סברא מאי שנא מהנהו עיזי דאכלי חושלא בנהרדעא ואתא מרא דחושלא ותפס להו וקא טעין טובא ואמר אבוה דשמואל יכול לטעון עד כדי דמיהן","התם לאו מידי דעבדא לאושולי ולאוגורי הוא הכא מידי דעביד לאושולי ולאוגורי הוא דשלח רב הונא בר אבין דברים העשויין להשאיל ולהשכיר ואמר לקוחין הן בידי אינו נאמן","ורבא לית ליה האי סברא והא רבא אפיק זוגא דסרבלא וספרא דאגדתא מיתמי בדברים העשויין להשאיל ולהשכיר אמר לך רבא האי נמי כיון דמיפגמא קפדי אינשי ולא מושלי:","\u0001הדרן עלך המקבל\u0002"],[[0,"יתירא הוא","ללאו משום שאר דברים וכיון דיתירא הוא ללאו וכתביה סתמא שדייה נמי אריחים ורכב שאין לך להוציאם ממשמע' כי נפש הוא חובל על כרחך אבל הכא כי אם צלי אש לאו לאזהרה אתא לאוסופי לאו יתירא אלא כדתניא ומ\"מ נא ומבושל משמע ביה שאינו עובר בנא ומבושל ביום אלא בלילה:"],[2,"ה\"ג תניא כוותיה דרב יהודה חבל זוג וכו' ותניא אידך וכו'","ולא גרסינן תניא אידך דמתרוייהו מתני' מתרץ סייעת' ולא מחדא מינייהו דאי משום דקתני חייב ב' ולא ג' הא אפילו רב הונא מודה דמהיכא תיתי הא הני לא כתיבי ומכי נפש הוא חובל הוא דנפקי דאכל חד קאי כי נפש אלא מתרוייהו מתני' מיתוקמא סייעתא לרב יהודה:"],[2,"חבל זוג של ספרים","מספרים של ספרים והן של פרקים וכל חד כלי באפי נפשיה ועושין המלאכה בין שניהם כריחים ורכב:"],[2,"חייב שתים","משום כי נפש על כל אחד אע\"פ ששניהן צריכין למלאכה אחת וכן צמד של פרות חבל ב' פרות חורשות עם צמדן דהיינו נמי כלי אוכל נפש ונראה בעיני שהעול שלהן של פרקים הוה:"],[3,"ותניא אידך","דיליף להו מריחים ורכב דאיתקוש שאר דברים לריחים ורכב בחד קרא מה ריחים ורכב וכו':"],[3,"וחייב על זה בעצמו ועל זה בעצמו","שהרי פירשן הכתוב לברר אזהרה לכל אחד לעצמו:"],[3,"אף כל וכו'","ומדיליף להו מריחים ורכב ש\"מ בריחים ורכב חייב נמי שתים קאמר ולא שלש והיינו כרב יהודה וא\"ת מתני' קמייתא למאי אייתיה ה\"נ שמעי' לה מבתרייתא אי מבתרייתא חייב על זה בעצמו ועל זה בעצמו :"],[4,"סכינא דאשכבתא","של בית המטבחים שמקצבים בו בשר:"],[4,"ותא קום בדינא","תבעהו לדין על חובך אם מודה לך או אם יש עדים ישלם ואם לאו ישבע שבועת היסת:"],[4,"רבא אמר","כיון דמשכניה ואין עדים שמשכנו היה יכול לטעון לקוחה היא בידי לא צריך למיקם בדינא עילויה דקנה ליה משכון לישבע וליטול עד כדי דמיו:"],[5,"חושלא","שעורין קלופים:"],[6,"לאו מידי הוא דעביד לאושולי וכו'","שאין אדם משכיר ומשאיל עזים שלו הלכך יכול לטעון לקוחין הן בידי היכא דאין עדים שאספם מרשותם של בעליהן:"],[7,"זוגא דסרבלא","מספרים שגוזזין בהן צמר:"],[7,"אפילו מיתמי","שהביאו הבעלים עדים שהיו שלהן והן טוענין השאלנום לאביהם של אלו ואפקינהו רבא מינייהו משום דברים העשויין להשאיל ולהשכיר ואם איתא דיכול לטעון לקוח הוא בידי יתמי כי לא טענו נמי אנן טענינן להו:"]],[[2,"וצמד של פרות","פי' בקונטרס ב' פרות חורשות עם צמדם ואין נראה לר\"י דבפרות לא מיירי:"],[3,"ותניא אידך","לפי מה שפירש בקונטרס דמקמייתא ליכא לאוכוחי קשה לר\"י דא\"כ מבתרייתא נמי ליכא להוכיח דאיכא למימר שלא בא ללמד אלא שחייב על זה בעצמו ועל זה בעצמו אבל לא לחייב שלש ועוד דמקמייתא איכא לאוכוחי שפיר כדרב יהודה דלרב הונא אי חייב שתים ע\"כ חייב שלש דכיון דיליף מריחים ורכב ליתן בהן לאו של ריחים ורכב ולכך חייב שתים אחת משום ריחים ואחת משום רכב א\"כ חייב נמי מלקות שלישי משום כי נפש הוא חובל ואי לא יליף ליתן בהן לאו של ריחים אלא לאו של כי נפש הוא חובל לחודיה א\"כ לא יחייב אלא אחת דמכי נפש הוא חובל לא מיחייב אפילו בריחים ורכב אלא אחת ע\"כ נראה לר\"י דגרס תניא אידך בלא וי\"ו וכן גרס ר\"ח:"],[4,"כלים שעושין בהם אוכל נפש","נראה לר\"י דוקא כלים אבל אוכלים עצמן מותר לחבול:"],[7,"והא רבא אפיק זוגא דסרבלא וספרא דאגדתא כו'","ותימה דהכא משמע מטעם דעשויין להשאיל ולהשכיר לחוד אינו נאמן לומר לקוחין הן בידי ובפרק כל הנשבעים (שבועות דף מו:) גבי ראוהו שהטמין כלים תחת כנפיו ואמר לקוחין הן אינו נאמן קאמר ולא אמרן אלא בבעל הבית שאינו עשוי למכור כליו וכלים שאין דרכן להטמין ובאיניש דלא צניע אבל ליכא כל הני נאמן ולא אמרן אלא בדברים העשויין להשאיל ולהשכיר משמע אפילו בדברים העשויין להשאיל ולהשכיר בעי כל הני ונראה לר\"ת כגרסת הספרים ישנים וכן ר\"ח ובכולהו לא אמרן אלא בדברים שאין עשויין להשאיל ולהשכיר אבל עשויין אין נאמן אפילו ליכא חדא מכל הני וא\"ת דהכא משמע דספרים עשויין להשאיל ולהשכיר אפילו ספרא דאגדתא כל שכן שאר ספרים כדאמר בכתובות (דף נ.) וצדקתו עומדת לעד זה הכותב ספרים ומשאילן לאחרים וקשה דתנן בהגוזל בתרא (ב\"ק דף קיד: ושם) המכיר כליו וספריו ביד אחר אם יצא לו שם גניבה בעיר ישבע כמה נתן ויטול ואם לאו לאו כל הימנו שאני אומר מכרם לאחר ולקחם זה הימנו ואמאי יהיה נאמן זה לומר נגנבו לי במגו דאי בעי אמר השאלתיו לך ואף על גב דקאמר בפרק כל הנשבעין דאחזוקי אינשי בגנבי לא מחזקינן ואין נאמן לומר גנובים במגו דאי בעי אמר שאולים היינו היכא דאמר גנבת לי אבל היכא דאמר גנב אחר גנבם לי ומכרם לך לאו היינו אחזוקי אינשי בגנבי דהא כמה גנבי איכא בשוקא ונראה לרבינו תם דהתם איירי במכירים שאין בעל הספרים רגיל להשאיל אותן שהם בידו ולמורי ה\"ר דודי נראה לתרץ דמגו להוציא לא אמרינן ומיהו למ\"ד בחזקת הבתים (ב\"ב דף מד) דאמר מגו להוציא צ\"ל כפירוש ר\"ת וא\"כ אפילו לא יצא לו שם גניבה בעיר נאמן לומר גנובים היכא דמצי למימר השאלתים לך:"]]],[["מתני׳ \u0001הבית\u0002 והעלייה של שנים שנפלו שניהם חולקין בעצים ובאבנים ובעפר ורואין אלו אבנים העשויות להשתבר אם היה אחד מהן מכיר מקצת אבניו נוטלן ועולות לו מן החשבון:","\u0001גמ׳\u0002 מדקתני רואין מכלל דאיכא למיקם עלייהו אי בחבסא נפיל אי בחבטא נפיל","אי הכי רישא אמאי חולקין נחזי אי בחבטא נפיל עלייתא איתבור אי בחבסא נפיל תתייתא איתבור","לא צריכא דנפיל בליליא וליחזינהו בצפרא דפנינהו וליחזי מאן פנינהו ולישייליה דפנינהו בני רשות הרבים ואזלו לעלמא","וליחזי ברשות דמאן יתבן וליהוי אידך המוציא מחבירו עליו הראייה לא צריכא דייתבן בחצר דתרוייהו אי נמי ברשות הרבים ואיבעית אימא שותפין בכי האי גוונא לא קפדי אהדדי:","אם היה אחד מהן מכיר כו': והלה מה טוען אי דקאמר אין פשיטא ואי לא אמר אין למה נוטל אלא דא\"ל איני יודע","לימא תהוי תיובתא דר\"נ דאיתמר מנה לי בידך והלה אומר איני יודע רב הונא ורב יהודה אמרי חייב ר\"נ ור' יוחנן אמרי פטור","כדאמר ר\"נ כגון שיש עסק שבועה ביניהן הכא נמי כגון שיש עסק שבועה ביניהן","היכי דמי עסק שבועה כדרבא דאמר רבא מנה לי בידך והלה אומר אין לך בידי אלא חמשים והשאר איני יודע מתוך שאינו יכול לישבע ישלם:","ועולות לו מן החשבון: סבר רבא למימר לפי חשבון שבורות אלמא כיון דאמר איני יודע ריע טפי","א\"ל אביי אדרבה הא ריע טפי מדהני ידע טפי לא ידע תו לית ליה ואידך כולהו דהיאך נינהו","אלא אמר אביי לפי חשבון שלימות אי הכי מאי קמהני ליה למלבנא רווחא אי נמי טינא דמעבדא:","\u0001מתני׳\u0002 הבית והעלייה נפחתה העלייה ואין בעל הבית רוצה לתקן הרי בעל העלייה יורד ודר למטה עד שיתקן לו את העלייה","ר' יוסי אומר התחתון נותן את התקרה והעליון את המעזיבה:","\u0001גמ׳\u0002 נפחתה בכמה רב אמר ברובה ושמואל אמר בארבעה","רב אמר ברובה אבל בארבעה לא אדם דר חציו למטה וחציו למעלה ושמואל אמר בארבעה אין אדם דר חציו למטה וחציו למעלה","ה\"ד אי דאמר עלייה זו אזדא אלא דאמר ליה עלייה סתם לוגר ליה אחריתי","אמר רבא לא צריכא דא\"ל עלייה זו שאני משכיר לך כי סלקא סליק בהדה וכי נחית חות בהדה אי הכי מאי למימרא","אלא אמר רב אשי דא\"ל עלייה זו שעל גבי בית זה אני משכיר לך דהא שעביד בית לעלייה","וכי הא דאמר רבין בר רב אדא אמר ר' יצחק מעשה באחד שאמר לחבירו דלית שעל גבי פרסק זה אני מוכר לך ונעקר הפרסק ובא מעשה לפני רבי חייא ואמר חייב אתה להעמיד לו פרסק כל זמן שהדלית קיימא","בעי ר' אבא בר ממל"],[[0,"מתני' הבית והעלייה של שנים","כגון שני אחים שחלקו אחד נטל בית ואחד נטל עלייה שעל גביו והאבנים של חומת הבית מן תקרת הבית התחתונה שהיא קרקעיתה של עלייה ולמעלה של עליון והימנה ולמטה של תחתון:"],[0,"שניהם חולקים","הכל לפי הגבוה שהאחד הוא גבוה מחבירו ואבניו ועפרו מרובה משל חבירו חולקים לפי שאין ניכר איזו אבנים של עליון ואיזו אבנים של תחתון:"],[0,"רואים אלו אבנים ראויות להשתבר","אם יש אבנים שבורות של לבינים זה אומר שלימות שלי וזה אומר שלימות שלי רואין אלו אבנים ראויות להשתבר אם של עליון אם של תחתון והכל לפי המפולת שאם נחבט הבית מיסודו ונפל תחתיו החומה במקומה יש לדעת שהתחתונות נשברו ולכך נפלה הבית ואם נחבט הכותל להלן כמקל שהיה עומד זקוף ונפל שהעליונות של כותל נפלו להלן ממנו הרבה אז העליונות נשברו שנפלו מגובה רב והתחתונות שלימות שנפלו ממקום נמוך:"],[0,"מקצת אבניו","והן שלימות:"],[0,"ועולות לו מן החשבון","שחבירו יקח אחרות כנגדן ובגמרא מפרש מאי יטול כנגדן שלימות או שבורות:"],[1,"גמ' מכלל דאיכא למיקם עליה","דמפולת זו היאך נפלה:"],[1,"אי בחבסא נפלה","ותתאה איתבור כדפרישית:"],[1,"אי בחבטא נפול","כחבטת מקל ועלייתא איתבור:"],[2,"אי הכי","דאיכא למיקם עלייהו:"],[2,"רישא אמאי תנא חולקין","יטול העליון הרחוקות אם בחבטא נפול ואם בחבסא נפול יטול העליונות הן שלימות והן שבורות:"],[4,"לא קפדי אהדדי","למיקני רשותא דידיה דאפקורי מפקר ליה כל חד רשותיה לגבי חבריה להניח שם חפציו הלכך כי נמי יתבן ברשות דחד מינייהו לא הוי אידך מוציא דברשותא דהאי נמי יתבי דהא לא קפיד עליה מלאושליה דוכתא:"],[5,"דאמר איני יודע","ברי ושמא ברי עדיף:"],[6,"פטור מלשלם","אוקי ממונא בחזקת מריה וצריך לישבע שאינו יודע:"],[7,"עסק שבועה וכו'","והכא נמי כיון דמודה במקצת ואמר איני יודע במקצת דחייב שבועה דאורייתא משום הודאה במקצת:"],[9,"לחשבון שבורות","(שכנגדן) נוטל שבורות כנגדן וזה יטול את אלו לפי החשבון:"],[11,"לחשבון שלימות","(שכנגדן) אף הוא יטול שלימות כנגדן:"],[11,"למלבנא רווחא","יש לבינים העשויות כמלבן שהוא רחב מחבירו:"],[11,"א\"נ לטינא דמעבדא","יש טיט שעושין ממנו לבינים שמעובד ומגובל יפה מחבירו:"],[12,"מתני' הבית והעלייה: ונפחתה העלייה","גרס ולא גרס הכא של שנים דהא בשוכר קאי כדאמר בגמרא:"],[12,"ואין בעל הבית","משכיר:"],[13,"מעזיבה","טיח של טיט שנותנין על התקרה שקורין אשטרי\"ך ודומה לו במקרא ויעזבו (את) ירושלים בספר עזרא (נחמיה ג׳:ח׳) ובגמרא מפרש פלוגתייהו:"],[14,"גמ' אבל בארבעה לא","שאינו מחוסר אלא מקום הנחת כלי אחד וכנגדו יתן כלי אחר כגון תיבה או עריבה למטה וכשירצה להשתמש בו ישתמש:"],[15,"חציו למטה","כלומר מקצת תשמישו למטה ומקצת תשמישו למעלה:"],[15,"בארבעה","כיון שנפחתה בארבעה יורד ודר בבית לגמרי ולא כפינן ליה לדור חציו למעלה וחציו למטה:"],[16,"אזדא","מזלו גרם לו:"],[16,"לוגר לו אחריתי","אם יש לו ולמה אנו כופין את המשכיר לקולטו עמו בבית:"],[17,"כי סלקא","בעודה קיימת:"],[17,"וכי נחתא","אם תפחות נחית בהדה גור בבית:"],[18,"דשעביד הבית לגבי עלייה","דאי לא שעבדו למה ליה למימר שעל גבי בית זה והא קא חזי ליה דעלייה זו קאמר ליה:"],[19,"דלית","גפן מודלית שקורין פליד\"א:"],[19,"פרסקא","אילן שפירותיו אפרסקין:"]],[[4,"הבית והעלייה. וליחזי ברשות דמאן קיימי כו'","וא\"ת דהכא פשיטא ליה דאיירי בנפל לרשות דחד מינייהו שכן רגילות הוא שאינו נופל בצמצום בשוה ובריש בבא בתרא (דף ד.) פריך פשיטא דאם נפל הכותל דהוי של שניהם ומשני לא צריכא דנפל לרשות דחד וי\"ל משום דאוקי לה הכא דמונחים בשל זה כמו בשל זה פריך התם פשיטא דהוה משמע ליה לאוקמיה דומיא דהכא שנשנית לפניה בסמוך ועוד דהתם פריך מתוך הסוגיא דשפיר פריך פשיטא:"],[6,"לימא תיהוי תיובתא דר\"נ","דאמר פטור ואע\"ג דטעמא דר\"נ משום דאוקי ממונא בחזקת מריה והכא אוקימנא דקיימי ברה\"ר או בחצר שאינה של שניהם שאין האחד מוחזק יותר מחבירו מ\"מ בהכי חשיב מוחזק שאנו יודעין שהחצי שלו לכך פריך שפיר ועוד דבפ' השואל (לעיל בבא מציעא דף צח: ושם) פירש דכל ממון המוטל בספק חשיב כאילו שניהם מוחזקים בו:"],[9,"סבר רבא למימר לפי חשבון שבורות","נראה לר\"י שר\"ל לפי חשבון שבורות ושלימות כמו שהן מעורבות שם במקום שנפלו דמה סברא הוא לומר שיברור ולא יקח כי אם שבורות דוקא כנגדו:"],[12,"הבית והעלייה של שנים","בקונט' לא גרס של שנים ולר\"ת נראה דאע\"ג דמוקי לה בגמ' בשוכר ומשכיר מ\"מ שייך למיתני של שנים כיון דקתני בה בעל הבית ובעל עלייה ובגמרא דמוקי לה בשוכר ומשכיר משום דבאחין שחלקו אין על התחתון לבנות תקרה אבל קשה אי אין עליו לבנות מאי קאמר בגמר' תחתון שבא לסכך בארזים שומעין לו למה בא לסכך כיון דאין מוטל עליו דבאחין שחלקו מיירי:"],[16,"אי דא\"ל עלייה זו ונפל אזדא ליה","ויתן לו שכרו שכבר דר שאם דר חצי יתן חצי כדאמר בהאומנין (לעיל בבא מציעא דף עט.) גבי שוכר את החמור ומת לו בחצי הדרך נותן לו שכרו של חצי הדרך ושם [ד\"ה ואם] פירשתי אמאי לא אמר הכא ובסוף השואל (לעיל בבא מציעא דף קג.) גבי המשכיר בית לחבירו ונפל אם יש בדמים ליקח יקח ולשכור ישכור כדאמר גבי חמור:"]]],[["כשהוא דר לבדו הוא דר כדמעיקרא או דלמא שניהם דרין דא\"ל אדעתא לאפקינן לא אגרי לך","אם תמצא לומר שניהם דרין בו כשהוא משתמש דרך פתחים משתמש או דרך גגין משתמש מי אמר כדמעיקרא מה מעיקרא דרך גגין השתא נמי דרך גגין או דלמא מצי אמר ליה עלייה קבילי עלאי עלייה וירידה לא קבילי עלאי","אם תמצא לומר מצי אמר ליה עלייה וירידה לא קבילי עלאי שתי עליות זו על גב זו מהו איפחית עליונה נחית ודר בתחתונה איפחית תחתונה מהו למיסלק לגמרי בעליונה","מי אמרינן דא\"ל שם עלייה קבילית עלך או דלמא חד עלייה קביל עליה שתי עליות לא קביל עליה תיקו:","רבי יוסי אומר התחתון נותן את התקרה כו': מאי תקרה רבי יוסי בר חנינא אמר קינים וסנאין וסטיני אמר רבי שמעון בן לקיש לווחים ולא פליגי מר כי אתריה ומר כי אתריה","הנהו בי תרי דהוו דיירי חד עילאי וחד תתאי איפחית מעזיבה כי משי מיא עילאי אזלי ומזקי לתתאי מי מתקן ר' חייא בר אבא אמר העליון מתקן ור' אלעי משום ר' חייא בר' יוסי אמר התחתון מתקן וסימן (בראשית לט, א) ויוסף הורד מצרימה","לימא ר' חייא בר אבא ורבי אלעי בפלוגתא דרבי יוסי ורבנן קמיפלגי למאן דאמר העליון מתקן קסבר על המזיק להרחיק את עצמו מן הניזק ומאן דאמר תחתון מתקן קסבר על הניזק להרחיק את עצמו מן המזיק","ותיסברא רבי יוסי ורבנן לענין נזקין פליגי והא איפכא שמעינן להו דתנן מרחיקין את האילן מן הבור עשרים וחמש אמה ובחרוב ובשקמה חמשים אמה בין מלמעלה בין מן הצד אם הבור קדם קוצץ ונותן דמים אם האילן קדם לא יקוץ ספק זה קדם ספק זה קדם לא יקוץ","רבי יוסי אומר אע\"פ שהבור קודמת לאילן לא יקוץ שזה חופר בתוך שלו וזה נוטע בתוך שלו אלמא ר' יוסי סבר על הניזק להרחיק את עצמו ורבנן סברי על המזיק להרחיק את עצמו","אלא אי איכא למימר פליגי בפלוגתא דר' יוסי ורבנן דהתם קמיפלגי","ורבי יוסי ורבנן דהכא במאי פליגי בחוזק תקרה קמפלגי רבנן סברי מעזיבה אחזוקי תקרה הוא ואחזוקי תקרה על התחתון בעי לאחזוקי ורבי יוסי סבר מעזיבה אשוויי גומות הוא ואשוויי גומות על העליון לאשוויי","איני והאמר רב אשי כי הוינא בי רב כהנא הוה אמרינן מודה רבי יוסי בגירי דיליה","דפסקי מיא והדר נפלי:","\u0001מתני׳\u0002 הבית והעלייה של שנים שנפלו אמר בעל העלייה לבעל הבית לבנות והוא אינו רוצה לבנות הרי בעל העלייה בונה את הבית ודר בתוכה עד שיתן לו את יציאותיו","ר' יהודה אומר אף זה דר בתוך של חבירו צריך להעלות לו שכר אלא בעל העלייה בונה את הבית ואת העלייה מקרה את העליונה ויושב בבית עד שיתן לו את יציאותיו:"],[[0,"לבדו הוא דר","ובעל הבית יוצא מביתו בעל כרחו:"],[1,"דרך גגין","לעלות מבחוץ דרך סולם הקבוע לכניסת פתח העלייה ויכנס לעלייה הנפחת ומשם ירד לבית בסולם:"],[1,"עלייה קבילת עילואי","לעלות דרך סולם וליכנס לפתח ולדור למעלה אבל טורח של עלייה וירידה לא קבילית עלי:"],[2,"שתי עליות זו על גב זו מהו","והגמרא מפרש לבעיא ואזיל:"],[2,"איפחית עלייה עליונה","והוא שכר העליונה פשוט לי דדר בתחתונה דכ\"ש דהא עדיפא ליה:"],[2,"אלא איפחית תחתונה","והוא שכר את התחתונה מהו דנידחייה משכיר אצל העליונה או נכוף את המשכיר וידור עמו בבית:"],[3,"חדא עלייה","מעלה:"],[4,"קינים וסנאים","מעשה תקרה כעין מחצלות שקורין קלידי\"ש:"],[4,"וסטיני אמר ריש לקיש","שם חכם תלמידו של ריש לקיש:"],[4,"לווחין","פלנק\"ש בלעז מנסרים של ארז:"],[5,"איפחית מעזיבה","והתקרה קיימת אלא שהמים שותתין ויורדין דרך הפחתים הוו ולאו שוכר ומשכיר הוו אלא בית של זה והעלייה של זה:"],[5,"ויוסף הורד","תרגומו איתחת רבי חייא ב\"ר יוסי אמר תחתון וכו':"],[6,"בפלוגתא דרבי יוסי ורבנן","דמתניתין דס\"ד דהא דקאמר רבי יוסי העליון נותן את המעזיבה כדי שלא יזיקו מימיו את התחתון הוא דקסבר על המזיק להרחיק את עצמו והתחתון נותן תקרה שהרי השכיר לו מקום לגור ותנא קמא סבר על הניזק להרחיק את עצמו הלכך מעזיבה נמי על התחתון לעכב המים שלא ירדו עליו:"],[7,"ותיסברא דרבי יוסי ורבנן","דהכא בהיזיקא דתחתון פליגי ומעזיבה זו לעכב המים ובשביל נזקי התחתון:"],[7,"איפכא שמעינן להו","דרבי יוסי סבר על הניזק להרחיק את עצמו:"],[7,"מן הבור","שהשרשין מתפשטין ונוקבין בכותלי הבור ומחלידין את הקרקע והכתלים נופלים:"],[7,"חרוב ושקמה","יש להן שרשין יתירין וארוכין משאר אילנות:"],[7,"בין מלמעלה","בין שהאילן נמוך מן הבור שקרקעית הבור למעלה משרשי האילן שהאילן נטוע בבקעה והבור בהר והתם מפרש מפני שמחלידין את הקרקע ומעלין עפר ומקלקלין קרקעיתו של בור:"],[7,"מן הצד","ששניהם בקרקע השוה:"],[7,"ונותן דמים","בעל הבור לבעל האילן:"],[9,"אלא אי איכא למימר דפליגי","אם יש לתלות פלוגתא דהנך אמוראי דלעיל בפלוגתא דתנאי:"],[9,"בפלוגתא דרבי יוסי ורבנן דהתם הוא דפליגי","מ\"ד על העליון לתקן כרבנן ומ\"ד על התחתון כרבי יוסי:"],[10,"בחזוקי תקרה","וכשאין התחתון צועק שאינו חש למימיו אלא העליון צועק ואומר כשאני דורך על הנסרים הם מנענעים ואני דואג שמא תהפך אחד מהן תחתי או תשמט מן הקורה ואפול:"],[10,"חזוקי תקרה הוא","מאחר שהוא טח בטיט אין הנסרים נדין ממקומן:"],[10,"אשווי גומות הוא","דחזוקי תקרה סגי ליה ביתידות שקורין קבליי\"ש בלעז:"],[11,"איני והאמר רב אשי וכו'","אדרבי חייא בר יוסי פריך דאמר על התחתון לתקן ואוקימנא כרבי יוסי והא מודה רבי יוסי בגירי דיליה אע\"ג דאמר על הניזק להרחיק את עצמו ה\"מ היכי דלאו אדם עצמו מזיקו כגון אילן ובור שבשעת נטיעתו אינו מזיקו אלא השרשים גדילין ומתפשטין מאליהן לאחר זמן אבל היכא דאדם עצמו מזיקו וזורק בו חציו כי הכא ששופך המים על ראשו מודה הוא דלא גרמא דניזקין הוא דתיפטר אלא מזיק ממש הוא ואדם מועד לעולם ער וישן שוגג ומזיד:"],[12,"דפסקי והדר נפלי","לא היתה מקום רחיצת ידים של עליון על מקום נזקי תחתון אלא במקום אחר משם הן נמשכין עד שנופלים במקום שמזיקין:"],[13,"מתני' של שנים","בית של זה והעלייה של זה שחלקו כך בנחלת אביהן:"],[13,"אמר בעל העלייה לבעל הבית לבנות","החומה והתקרה התחתונה המוטלין עליו לבנות והוא יבנה החומה מן התקרה ולמעלה ותקרה העליונה של גג:"],[13,"בונה בית","לבדו עד תקרה התחתונה:"],[13,"עד שיתן לו יציאותיו","ואח\"כ יצא ממנו ויבנה עלייתו:"],[14,"אמר רבי יהודה אף זה דר בתוך של חבירו","אם כן הוא אף בעל העלייה זו כשהוא חוזר מעותיו לזה שהוא דר בתוך שלו ואי נמי זה לא חסר דהא בלאו הכי לא הוי בני לה איהו צריך להעלות לו שכר דזה מיהא נהנה שאלולי בית זה אין לו מקום לדור שם וקסבר זה נהנה וזה לא חסר חייב וצריך להעלות לו שכר ואי לא מיחזי כרבית:"],[14,"אלא בונה וגומר את הכל","ומקרה את העלייה למעלה וכל הצריך לה:"],[14,"ויושב בבית","התחתון דהוה ליה זה לא נהנה וזה לא חסר הוא לא נהנה שהרי עלייתו מוכנת לו לדור בה וזה לא חסר דבלאו הכי לא חזיא ליה דהא לא הוה בני לה:"]],[[2,"איפחית תחתונה מהו למידר בעליונה","וא\"ת אי דאמר ליה עלייה שתחת עלייה זו אני משכיר לך פשיטא שידור בעליונה ששיעבד לו ואי אמר שעל גבי בית זה אני משכיר לך פשיטא שלא יכול לסלקו לילך לעליונה וי\"ל דלעולם דא\"ל שעל גבי בית זה אני משכיר לך ומספקא ליה דלמא עלייה עליונה נמי היא בכלל בית והא דא\"ל שעל גבי בית זה משום דעיקר הבית היא למטה ואף על גב דמוכר את הבית לא מכר את העלייה לענין שיעבוד זה מיהא הוי בכלל בית:"],[14,"רבי יהודה אומר אף הדר בתוך של חבירו צריך להעלות לו שכר","מה שפירש בקונטרס דאם אין נותן לו שכר מיחזי כרבית אין נראה לר\"י דמה רבית שייך הכא דלא הלווהו כלום שהרי אם הבית נשרף לא היה נותן לו יציאותיו וגם אין אנו צריכין לטעם דרבית שהרי טעמו הוא משום דזה נהנה וזה חסר כדמפרש בגמרא:"],[14,"ויושב בבית עד שיתן לו יציאותיו","פי' בקונטרס דטעמא משום דהשתא לא נהנה דהרי עלייתו מוכנת לו וקשה דהא נהנה הוא שאין צריך לעלות ונראה דגרס ומקרה את העלייה ויושב בתוכה פי' בעליי' ולא יניח לבעה\"ב ליכנס בתוכו עד שיתן לו יציאותיו:"]]],[["\u0001גמ׳\u0002 אמר ר' יוחנן בשלשה מקומות שנה לנו רבי יהודה אסור לאדם שיהנה מממון חבירו חדא הא דתנן","אידך מה היא דתנן הנותן צמר לצבע לצבוע לו אדום וצבעו שחור שחור וצבעו אדום ר' מאיר אומר נותן לו דמי צמרו רבי יהודה אומר אם השבח יותר על ההוצאה נותן לו היציאה ואם ההוצאה יתירה על השבח נותן לו את השבח","ואידך מאי היא דתנן מי שפרע מקצת חובו והשליש את שטרו ואמר לו אם אין אני נותן לך מכאן ועד זמן פלוני תן לו שטרו הגיע זמן ולא נתן רבי יוסי אומר יתן רבי יהודה אומר לא יתן","אמאי דלמא עד כאן לא קאמר רבי יהודה הכא אלא משום דאיכא שחרוריתא","אי נמי לצבוע לו אדום וצבעו שחור משום דקא משנה והתנן כל המשנה ידו על התחתונה","ומי שפרע מקצת חובו נמי הוי אסמכתא ושמעינן ליה לר' יהודה דאמר לא קני","אמר רב אחא בר אדא משמיה דעולא תחתון הבא לשנות בגויל שומעין לו בגזית אין שומעין לו","בכפיסין שומעין לו בלבנים אין שומעין לו לסכך בארזים שומעין לו בשקמים אין שומעין לו","למעט בחלונות שומעין לו להרבות בחלונות אין שומעין לו להגביה אין שומעין לו למעט שומעין לו","עליון שבא לשנות בגזית שומעין לו בגויל אין שומעין לו","בכפיסין אין שומעין לו בלבנים שומעין לו בארזים אין שומעין לו בשקמה שומעין לו לרבות בחלונות שומעין לו למעט בחלונות אין שומעין לו להגביה אין שומעין לו למעט שומעין לו","אין לו לזה ולא לזה מאי תניא אין לו לא לזה ולא לזה אין לו לבעל עלייה בקרקע כלום","תניא רבי נתן אומר תחתון נוטל שני חלקים והעליון שליש ואחרים אומרים תחתון נוטל שלשה חלקים והעליון נוטל רביע אמר רבה נקוט דרבי נתן בידך דדיינא הוא ונחית לעומקא דדינא קא סבר כמה מפסיד עלייה בבית תילתא הלכך אית ליה תילתא:","\u0001מתני׳\u0002 וכן בית הבד שהוא בנוי בסלע וגינה אחת על גביו ונפחת הרי בעל הגינה יורד וזורע למטה עד שיעשה לבית בדו כיפין","הכותל והאילן שנפלו לרשות הרבים והזיקו פטור מלשלם נתנו לו זמן לקוץ את האילן ולסתור את הכותל ונפלו בתוך הזמן פטור לאחר הזמן חייב","מי שהיה כותלו סמוך לגינת חבירו ונפל ואמר לו פנה אבניך ואמר לו"],[[0,"גמ' שיהנה מממון חבירו","שלא במתנה עד שתהא מדעתו ונוחה לו:"],[1,"נותן לו דמי צמרו","צמר לבן כמו שמסר לו דקניה בשינוי ונתחייב מעות:"],[1,"ר' יהודה אומר","אם כן תחייבו נמצא זה נהנה שזה הביאו לו מן השוק אלא מחזיר לו את הצמר כמות שהוא צבוע וידו על התחתונה:"],[1,"אם השבח","שהשביח הצמר יתר על היציאה שהוציא צבע זה בסממנין ועצים ושכר טרחו כשאר שכיר יום:"],[1,"נותן לו את היציאה","ולא מה שראוי בקבלנות דהוי טפי ואם ההוצאה וכו':"],[2,"והשליש את שטרו","הפקידו ביד נאמן לפי שדאג הלוה שיחזור ויתבענו כל החוב:"],[2,"ואמר לו","לוה לשליש:"],[2,"אם אין אני נותן לו","את המותר מכאן עד יום פלוני:"],[2,"תן לו שטרו","ויחזור ויתבע הכל:"],[3,"ודלמא","לא היא זה נהנה וזה לא חסר לא קאסר רבי יהודה אלא זה נהנה וזה חסר הוא דאסר ומתניתין זה נהנה וזה חסר הוא דאמר ליה בעל הבית קא משחרת לכותלאי שאתה בונה חדשים ויפים וכל הדמים עלי ואתה משחירן בעשן לפני יציאתך:"],[4,"דהוה ליה משנה","וקנסא קניס ליה אבל זה נהנה וזה לא חסר כגון לעיל (בבא מציעא דף כד:) הדר בחצר חבירו בחצר דלא קיימא לאגרא והדר זה אפילו עביד למיגר דה\"ל נהנה וזה אינו חסר אינו צריך להעלות לו שכר:"],[5,"ושמעינן ליה וכו'","הכא אשמעינן הכי:"],[6,"תחתון שבא לשנות","בבנין חומה שעליו מן היסוד עד התקרה:"],[6,"בגויל שומעין לו","אם היה מתחילה מאבני גזית ובא לשנותו כשנפלה ולבנות באבני גויל שומעין לו מפני שהוא מחזיק את הבנין שחומת גויל רחבה משל גזית טפח כדאמר בפרק קמא דבבא בתרא (דף ב.) בגויל זה נותן ג' טפחים וזה נותן שלשה טפחים ובגזית זה נותן טפחיים ומחצה וזה נותן טפחיים ומחצה והתם מפרש גויל אבנים דלא משפיין דמורשי דידהו מטפי בה טפח:"],[7,"כפיסים","ארחי חצאי לבינים ורחבן טפח ומחצה ונותן אריח מכאן ואריח מכאן וטפח אבנים דקות וסיד ביניהם הוי עובי החומה ד' טפחים:"],[7,"בלבינים","שלימות ואין עוביו של כותל אלא כמדת רוחבן והן שלשה טפחים כלל הדבר התחתון שמרחיב עובי הבנין ומחזיקו שומעין לו אם ממעט חיזוקו אין שומעין לו שהעליון טוענו למחר יפול והעליון שבא להכביד את המשא תחתון מעכב עליו וכל זמן שממעט כובדו שומעין לו:"],[7,"ארזים","בקורות של תקרה תחתונה קמיירי וארזים מתקיימין מן השקמין ומשאן כבד:"],[8,"להרבות בחלונות","ממעט חוזק הבנין והעליון מעכב עליו:"],[8,"להגביה","חלל הבית אין שומעין לו שמטריח את העליון לעלות ועוד שהנמוך חזק מן הגבוה:"],[9,"עליון שבא לשנות וכו'","טעמא דכולהו שומעין לו מפני שממעט כובד המשא והיכא דמוסיף על כובדו תחתון מעכב עליו שהתחתון אינו חושש אם תפול החומה שמן התקרה ולמעלה:"],[9,"בא לשנות תחתון","משקמים לארזים שומעין לו שמהנהו לעליון שמתקיים וחזק מקום מדרך רגליו מארזים לשקמים אין שומעין לו מפני שהן נוחין להשבר:"],[11,"אין לו לא לזה ולא לזה","לבנות שעניים הם ובעל הקרקע רוצה למכור הקרקע:"],[12,"מאי","אית ליה לבעל העלייה בקרקע או לא:"],[12,"דדיינא הוא","אב בית דין היה כדאמרינן בהוריות בפרק בתרא (דף יג:):"],[12,"כמה מפסיד שליש","ימי קיומה היא ממהרת ליפול מחמת משא העלייה:"],[13,"מתני' בית הבד","בית לעצור זיתים וגינה אחת על גבו שחקק אדם בסלע תחתיה כגון כיפה והיה גינתו למעלה ובית בדו מלמטה וכשמת נטלו בניו זה בית הבד וזה גינה ונפחת גגו של בית הבד שהוא מקום זריעתו של העליון:"],[13,"כיפין","ארקוולט\"ו העליון יתן עליו עפר ויזרע:"],[14,"פטור","מלשלם דמאי הוה ליה למיעבד אנוס הוא:"],[14,"נתנו לו זמן","שראוהו בית דין שהיה נוטה ואמרו לו סתור:"],[14,"ונפל","לתוך גינתו של חבירו:"]],[[0,"בשלשה מקומות שנה לנו ר' יהודה אסור לאדם שיהנה מממון חבירו שלא מדעתו","אע\"פ שמן הדין היה נראה לומר שיהנה חדא דאע\"ג דזה נהנה וזה לא חסר אפי' הכי תיקנו חכמים שיהא חייב דאין לו ליהנות מממון חבירו שלא מדעתו ואידך דאמר רבי יהודה אם השבח כו' דאע\"ג דגזלן קונה בשינוי הכא תקינו דלא ליקני כיון שאין מתכוין לגזול ולקנות משום דאין לו ליהנות מממון חבירו שחבירו הביאו מן השוק וטרח בו כדפירש בקונט' וא\"ת לפי מאי דס\"ד השתא דטעמא משום דאסור שיהנה מממון חבירו ולא משום דכל המשנה ידו על התחתונה נהי דלא קני בשינוי משום שהבעלים טרחו להביאו מן השוק מ\"מ לא הוה ליה למימר ידו על התחתונה ואור\"י דהמ\"ל וליטעמיך א\"נ מן הדין לא קנאו בשינוי כיון שאינו מתכוין לקנות ומיהו מ\"מ היה לו ליתן שכר כפי מה שהשביחו בצביעת שחור ורבנן תקנו שלא יהנה מממון חבירו שלא מדעתו דהיינו בצביעת השחור שעשה שלא מדעתו הלכך ידו על התחתונה וגם משליש שטרו נמי אע\"ג דאסמכתא קניא הכא כיון שאין זו מתנה גמורה שאין נותנה בלב שלם תקנו חכמים שלא יהנה מלוה הימנו:"],[1,"אם השבח יתר על היציאה","פי' בירושלמי בפרק הגוזל קמא (ב\"ק דף ק: ד\"ה אם):"],[11,"לא לזה ולא לזה מאי","אין נראה לר\"י פירוש הקונט' שפי' שבעה\"ב רוצה למכור את הקרקע דבהא לא קמבעיא ליה דפשיטא דאין יכול למוכרו שהרי משועבד לזה לבנות עלייה שם כשירצה ואי רוצה למכור הקרקע לעשות הבית ואין מוכר אלא כח שיש לו בתוכה הא נמי פשיטא שבענין זה יכול למוכרה דלמה לא ימכור כח שיש לו בה אלא נראה לר\"י דמיירי שרוצה בעה\"ב לזורעה ובעל עלייה אמר גם אני אזרע שגם לי הקרקע משועבד לעלייה או דלמא מצי א\"ל היאך אין לך כלום בקרקע אלא לענין העלייה בלבד:"],[13,"וכן בית הבד כו'","פי' בקונטרס דאיירי באחין שחלקו כמו פלוגתא דר' יהודה ורבנן ולא בשוכר ומשכיר וקצת קשה דמשמע דמדפליגי הכא רב ושמואל בגמרא דמיירי בשוכר ומשכיר דומיא דההיא דפליגי לעיל ועוד אי באחין שחלקו מוטל על התחתון לבנות התקרה אמאי אצטריך לאוקמי ההיא דלעיל בנפחת העלייה בשוכר ומשכיר לוקמה באחין שחלקו ואי האי וכן אנפחת העלייה דלעיל קאי אמאי הפסיק ביניהם ולא הסמיכם:"]]],[["הגיעוך אין שומעין לו משקבל עליו אמר לו הילך את יציאותיך ואני אטול את שלי אין שומעין לו","השוכר את הפועל לעשות עמו בתבן ובקש ואמר לו תן לי שכרי ואמר לו טול מה שעשית בשכרך אין שומעין לו משקבל עליו ואמר לו הילך שכרך ואני אטול את שלי אין שומעין לו:","\u0001גמ׳\u0002 נפחתה רב אמר ברובה ושמואל אמר בארבע רב אמר ברובה אבל בארבע אדם זורע חציו למטה וחציו למעלה ושמואל אמר בארבע אין אדם זורע חציו למטה וחציו למעלה","וצריכא דאי אשמועינן דירה בהא קאמר שמואל משום דלא עבידי אינשי דדיירי פורתא הכא ופורתא הכא אבל לענין זריעה עבידי אינשי דזרעי הכא פורתא והכא פורתא אימא מודה ליה לרב ואי איתמר בהך בהך קאמר רב אבל בהא אימא מודה ליה לשמואל צריכא:","נתנו לו זמן: וכמה זמן ב\"ד א\"ר יוחנן שלשים יום:","מי שהיה כותלו כו': הא מדקתני סיפא הילך יציאותיך מכלל דפנינהו עסקינן טעמא דפנינהו הא לא פנינהו לא","אמאי ותקנה ליה שדהו דאמר ר' יוסי בר' חנינא חצירו של אדם קונה לו שלא מדעתו","ה\"מ היכא דקא מיכוין לאקנויי ליה אבל הכא אישתמוטי הוא דקא מישתמיט ליה:","השוכר לעשות עמו בתבן כו': וצריכא","דאי אשמועינן להך קמייתא דכי קאמר ליה הגיעוך אין שומעין לו משום דלית ליה אגרא גביה אבל הכא דאית ליה אגרא גביה אימא שומעין לו דאמרי אינשי ממרי רשותיך פארי אפרע","ואי אשמועינן הכא הכא שמשקבל עליו אין שומעין לו משום דאית ליה אגרא גביה אבל הכא דלית ליה אגרא גביה אימא שומעין לו צריכא:","אין שומעין לו: והתניא שומעין לו אמר רב נחמן לא קשיא כאן בשלו כאן בשל חבירו","א\"ל רבה לרב נחמן בשלו מ\"ט דא\"ל אגרא עלך בשל חבירו נמי שכרו עליו דתניא השוכר את הפועל לעשות בשלו והראהו בשל חבירו נותן לו שכרו משלם וחוזר ונוטל מבעל הבית מה שההנה אותו","אלא אמר רב נחמן לא קשיא כאן בשלו כאן בשל הפקר","איתיביה רבא לרב נחמן מציאת פועל לעצמו אימתי בזמן שאמר לו בעל הבית נכש עמי היום או עדור עמי היום אבל אם אמר לו עשה עמי מלאכה היום מציאתו לבעל הבית","אלא אמר רב נחמן לא קשיא כאן בהגבהה כאן בהבטה","אמר רבה הבטה בהפקר תנאי היא דתנן שומרי ספיחי שביעית נוטלין שכרן מתרומת הלשכה ר' יוסי אומר הרוצה מתנדב הוא ושומר חנם אמרו לו אתה אומר כן אין באין משל צבור","מאי לאו בהא קמיפלגי דת\"ק סבר הבטה בהפקר קני ואי יהיבי ליה אגרא אין ואי לא לא ורבי יוסי סבר הבטה בהפקר לא קני וכי אזלי צבור ומייתי השתא הוא דקא זכי ביה","ומה אתה אומר הכי קאמרי ליה מדבריך לדברינו אין עומר ושתי לחם באין משל צבור","אמר רבא לא דכ\"ע הבטה בהפקר קני והכא חיישינן שמא לא ימסרם יפה יפה קמיפלגי דרבנן סברי יהבינן ליה אגרא ואי לא חיישינן שמא לא ימסרם יפה יפה","רבי יוסי סבר לא חיישינן שמא לא ימסרם יפה יפה ומה אתה אומר הכי קאמרי ליה מדבריך לדברינו דחיישינן שמא לא ימסרם יפה יפה אין עומר ושתי לחם באין משל צבור","איכא דאמרי רבא אמר דכ\"ע הבטה בהפקר לא קני והכא בחיישינן לבעלי זרועות קמיפלגי דת\"ק סבר דתקינו רבנן למיתב ליה ארבע זוזי כי היכי דלישמעי בעלי זרועות וליפרשו מינייהו ור' יוסי סבר לא תקינו"],[[0,"הגיעוך","הם שלך ופנה אותן לעצמך:"],[0,"אין שומעין לו","אם אין זה רוצה אין קונה לו דבר הפקר או מתנה:"],[1,"בתבן ובקש","ללקט לו משלו או מן ההפקר:"],[1,"טול מה שעשית","כל מה שלקטת יהא שלך:"],[1,"אין שומעין לו","אע\"ג דבכל דוכתי אית ליה שוה כסף ככסף הכא גבי פועל בל תלין שכרו כתיב (ויקרא י״ט:י״ג) מאי דאתני בהדיה משמע:"],[9,"גמ' דלית ליה אגרא גביה","וזה אינו חפץ במתנתו והוא מזיקו שמנעו מזריעתו:"],[9,"אבל סיפא דאית ליה אגרא גביה","וזה בא לכופו על שכרו והוא אומר לו טול זה בפרעון אימא כו':"],[9,"ממרי רשותיך","מבעל חובך:"],[9,"פארי אפרע","אפי' נותן לך סובין קבלם:"],[10,"משום דאית ליה אגרא גביה","משקיבל עליה קנייה באגריה:"],[10,"צריכא","דאין שומעין לו דקנייה ליה חצרו:"],[11,"והתניא שומעין לו","לאומר לפועל טול מה שעשית בשכרך:"],[11,"בשל חבירו","שהיתה מלאכת חבירו שומעין לו:"],[13,"בשל הפקר","שומעין לו דא\"ל קני ביה את דלדידיה לא קני ליה ר\"נ לטעמיה דאמר לעיל (בבא מציעא דף י.) המגביה מציאה לחבירו לא קנה חבירו נמצא שאין פעולתו עליו ואין כאן בל תלין ולא דמי לשל חבירו דהתם ליכא למימר זכי ביה את וכי לא א\"ל שכרך על בעל הבית על כרחו שכרו עליו אבל הכא לא:"],[14,"איתיביה רבא לרב נחמן","למימר דפועל לאו בכלל המגביה מציאה לחבירו הוא אלא כיד בעה\"ב הוא וקנייה בעה\"ב בהגבהה דפועל אפילו אמר לו עשה עמי מלאכה סתם וכל שכן הכא דשכרו ללקט מציאות ממש:"],[15,"כאן בהגבהה כאן בהבטה","ואידי ואידי בשל הפקר מתני' כששכרו ללקט תבן וקש בהגבהה דפועל ועל כרחו שכרו עליו וברייתא כששכרו למלאכת הבטה כגון לשמור או להשליך מעלייה לארץ דליכא הגבהה דא\"ל אכתי לא זכאי ביה אנא זיל את זכי בה:"],[16,"תנאי היא","אי קניא אי לא:"],[16,"שומרי ספיחים","של שעורין לצורך מנחת העומר או של חטין לצורך שתי הלחם:"],[16,"אתה אומר אינן באין משל צבור","אם נשמע לך לא יביאו עומר ושתי הלחם משל צבור אלא משל יחיד זה שקנה מן ההפקר בשמירתו דסבירא להו הבטה קניא בהפקר הואיל ודבר טורח הוא ודעתו לכך על ידו נשמר:"],[18,"ומה אתה אומר אין באין וכו'","הא איהו סבר דלא קניא:"],[18,"מדבריך","שאתה אומר לשמרו בחנם:"],[18,"לדברינו","שאנו אומרים הבטה בהפקר קני אין וכו':"],[19,"אמר רבא","גרסינן הכא ולעיל אמר רבה:"],[19,"דכ\"ע הבטה בהפקר קני","וטעמא דר' יוסי דקסבר מסרה זה לצבור ונמצאו באין משל צבור:"],[19,"ורבנן","חיישי שמא לא יהא בלבו למסור יפה יפה בלב שלם דנוח לו שיקרבו משלו:"],[20,"מדבריך","שאתה אומר ישמרם חנם:"],[20,"לדברינו","שאנו חוששין שמא לא ימסרם יפה יפה אין עומר ושתי הלחם וכו':"],[21,"בחוששין לבעלי זרועות","שאם לא נוציא עליהן קול שהן של הקדש יש בעלי זרועות שלוקחין אותם בחזקה ולעצמן:"]],[[0,"אמר ליה הגיעוך אין שומעין לו","אע\"ג דמפקיר נזקיו לאחר נפילת אונס אמרי' בפרק המניח (בבא קמא דף כט.) דפטור הכא דאישתמוטי קא מישתמיט ואינו מפקירו כדאמר בגמרא:"],[4,"זמן ב\"ד ל' יום","ומכאן אנו למדים זמן ב\"ד לפרוע חובו ולכמה דברים דהוי ל' יום ורשב\"ג נמי אמר לעיל (בבא מציעא דף קיג.) אף לעצמו אין מחזיר אלא שלשים יום ומיהו לכל נזיקין לא אמר שיהא זמן ב\"ד ל' יום כמו הכא דהא לעיל (בבא מציעא דף פב:) גבי נשברה כדו ולא סילקו נפלה גמלו ולא העמידה ר\"מ מחייב בהזיקן אין זמן ב\"ד שלשים יום שם כדמשמע בהמניח את הכד (ב\"ק דף כט.) והיינו טעמא שבשעה קלה יכול להסירם משם:"],[7,"ליקני ליה חצרו כו'","אבל אי לאו דר\"י ברבי חנינא אתי שפיר דאין קונה לו אלא היכא דעומד בצד שדהו לכך כי לא פנינהו לא דכשאמר ליה הגיעוך לא היה אכתי עומד שם:"],[11,"כאן בשל חבירו","תימה למאי דס\"ד השתא אמאי צריך לומר לו טול מה שעשית בשכרך יאמר לא אתן לך כלום שלא עשית לי כלום:"],[12,"לעשות בשלו והראהו בשל חבירו","משמע דוקא לעשות בשלו אז נותן לו שכרו משלם אבל סתמא לא ותימה א\"כ אמאי איצטריך לשנויי כאן בשלו כאן בשל הפקר לישני כאן ששכרו לעשות שלו כאן ששכרו סתמא בשל חבירו ואור\"י דמשום הכי לא משני הכי דהא פשיטא דאם שכרו לעשות בשל חבירו דשומעים לו אבל הא דמשני לעיל הא בשל חבירו חידוש הוא דשומעין לו דהא לא קאי הכי וכן כאן בשל הפקר חידוש הוא וכן מה שמתרץ לסוף דבהבטה שומעין לו חידוש הוא דקא משמע לן דהבטה בהפקר לא קני:"],[16,"שומרי ספיחים","פירשתי בסוף פ' הזהב (לעיל בבא מציעא דף נח.):"]]],[["ומה אתה אומר הכי קאמרי ליה מדבריך לדברינו אין באין משל צבור וכן כי אתא רבין אמר רבי יוחנן חוששין לבעלי זרועות איכא בינייהו:","\u0001מתני׳\u0002 המוציא זבל לרשות הרבים המוציא מוציא והמזבל מזבל אין שורין טיט ברשות הרבים ואין לובנים לבנים אבל גובלין טיט ברשות הרבים אבל לא לבנים","הבונה ברשות הרבים המביא אבנים מביא והבונה בונה ואם הזיק משלם מה שהזיק רבן שמעון בן גמליאל אומר אף מתקן הוא את מלאכתו לפני שלשים יום:","\u0001גמ׳\u0002 לימא מתני' דלא כרבי יהודה דתניא רבי יהודה אומר בשעת הוצאת זבלים אדם מוציא זבלו לרה\"ר וצוברו כל שלשים יום כדי שיהא נישוף ברגלי אדם וברגלי בהמה שעל מנת כן הנחיל יהושע לישראל את הארץ","אפילו תימא רבי יהודה מודה ר' יהודה שאם הזיק חייב לשלם והתנן מודה רבי יהודה בנר חנוכה שהוא פטור מפני שהוא עושה ברשות מאי לאו רשות דבית דין לא רשות דמצוה","והתניא כל אלו שאמרו מותרין לקלקל ברה\"ר אם הזיק חייב לשלם ורבי יהודה פוטר אלא מחוורתא מתני' דלא כרבי יהודה","אמר אביי רבי יהודה ורבן שמעון בן גמליאל ור' שמעון כולהו סבירא להו כל מקום שנתנו לו חכמים רשות והזיק פטור רבי יהודה הא דאמרן רשב\"ג דתנן רשב\"ג אומר אף מתקן הוא את מלאכתו לפני שלשים יום","רבי שמעון דתנן היה מעמידו בעלייה צריך שיהא תחתיו מעזיבה שלשה טפחים ובכירה טפח ואם הזיק משלם מה שהזיק רבי שמעון אומר לא אמרו כל השיעורים הללו אלא שאם הזיק פטור מלשלם","ת\"ר החצב שמסר לסתת הסתת חייב הסתת שמסר לחמר החמר חייב החמר שמסר לכתף הכתף חייב הכתף שמסר לבנאי הבנאי חייב הבנאי שמסר לאדריכל אדריכל חייב ואם הניח אבן על הדימוס והזיקה כולן חייבין לשלם","והתניא אחרון חייב וכולן פטורים לא קשיא כאן בשכירות כאן בקבלנות:","\u0001מתני׳\u0002 שתי גנות זו על גב זו והירק בינתים ר\"מ אומר של עליון ר' יהודה אומר של תחתון אמר ר\"מ אם ירצה העליון ליקח את עפרו אין כאן ירק אמר ר' יהודה אם ירצה התחתון למלאות את גנתו אין כאן ירק","אמר ר\"מ מאחר ששניהן יכולין למחות זה על זה רואין מהיכן ירק זה חי אמר ר\"ש כל שהעליון יכול לפשוט את ידו וליטול הרי הוא שלו והשאר של תחתון:","\u0001גמ׳\u0002 אמר רבא בעיקרו כולי עלמא לא פליגי דעליון הוי כי פליגי בנופו ר\"מ סבר שדי נופו בתר עיקרו ור' יהודה סבר לא אמרינן שדי נופו בתר עיקרו","ואזדא לטעמייהו דתניא היוצא מן הגזע ומן השרשין הרי אלו של בעל הקרקע דברי ר' מאיר ר' יהודה אומר מן הגזע של בעל האילן ומן השרשין של בעל הקרקע"],[[0,"ומה אתה אומר","אינן באין משל צבור הא אמרן דלא קני:"],[0,"הכי קאמרי ליה מדבריך","דקאמרת ישמרם חנם:"],[0,"לדברינו","דסבירא לן דתקינו רבנן ארבעה זוזי מן התרומה לשומרי ספיחים וזה מוחל עליהן ונמצאו לו בתרומה ארבעה זוזים שאין לצבור חלק בהם ואם קונין מהן תמידין ומוספין ושאר קרבנות צבור אין תמידין באין משל צבור:"],[1,"מתני' המוציא מוציא והמזבל מזבל","כלומר אינו רשאי להשהותו שם אלא זה מוציאו מן הרפת לרה\"ר והנושאו יהא מזומן לישאנו לשדה ולגנה לזבל:"],[1,"אין שורין טיט","מקומות יש ששורין אותו ימים רבים צבור במקום אחד:"],[1,"ואין לובנים לבנים","לפי שמשהה אותן לייבשן ששוטח הטיט בקרקע חלקה כעובי הלבנים וחורץ בו חריצות שתי וערב כמדת הלבנים ומניחן שם עד שיבשו:"],[1,"וגובלין טיט","לתת מיד בבנין:"],[2,"והבונה בונה","מקבל מיד המביא ובונה:"],[2,"מתקן","מזמן ברשות הרבים ואינו חייב בנזקין:"],[3,"גמ' וצוברו כל שלשים יום","משלשים לשלשים חוזר וצוברו כדי שיהא נישף יפה:"],[4,"מודה רבי יהודה וכו'","ומתני' נמי עצה טובה קאמר שלא יתחייב בנזקו:"],[4,"בנר חנוכה פטור","גבי הניח חנוני נרו מבחוץ ועבר גמל טעון פשתן ודלקה בנר והדליק את הבירה בב\"ק (דף סב:):"],[4,"מאי לאו ברשות ב\"ד","אלמא כל מידי דיהבו ליה רבנן רשותא אם הזיק פטור:"],[5,"כל אלו שאמרו וכו'","כל אותן נזקין שנתנו חכמים עליהם רשות ואמרו מותרין לקלקל ברה\"ר ולהשליכן לשם כגון הוצאת זבלים לרבי יהודה וכגון פותקין ביבותיהם וגורפין מערותיהן בימות הגשמים דברשות קא עבדי בב\"ק (דף ו.):"],[6,"אף מתקן הוא","וקאי אתנא קמא דאמר אם הזיק משלם וקאמר ליה איהו אף בשלשים יום קודם לכן מתקן ופטור:"],[7,"היה מעמידו בעלייה","משנה היא בב\"ב בלא יחפור לא יעמיד אדם תנור בתוך הבית אא\"כ יש על גביו חלל גובה ד' אמות מפי התנור לעלייה:"],[7,"היה מעמידו בעלייה","עד שיהא תחתיו עובי מעזיבה שלשה טפחים:"],[7,"ובכירה","שאין היסק שבה גדול:"],[7,"טפח","מעזיבה יהא תחתיה:"],[7,"ואם הזיק","שדלק הבית והדליק את סביביו:"],[8,"חצב","החוצב אבן מן ההר לעקרה מחיבורה:"],[8,"סתת","הוא המרבעה ומחליקה:"],[8,"חמר","נושאה מן ההר שסיתתה הסתת שם ומוסרה לכתף המושיטה לבנאי העומד על מעמד החומה העשוי להילוך האומנין:"],[8,"אדריכל","הוא אבי האומנין שהוא מדקדק בהנחת האבן לצדדה על מושבה בשוה שלא תמיש ולא תטה ולא תהא בולטת חוץ לדימוס:"],[8,"חייב","זה שהיא בידו חייב בנזקה אם תפול מידו ותזיק את אחרים או תשבר היא הוא חייב לשלם ואף על גב דמוקמינן להא לקמן בקבלנות וכולן שותפין במלאכה אין חייב אלא מי שהיתה מסורה לו דכיון דכחו הוא הנזק מוטל עליו כל היכא דמיתרמי דתנן אדם מועד לעולם שוגג ומזיד אונס ורצון דנפקא לן בב\"ק (דף כו:) פצע תחת פצע לחייב על השוגג כמזיד ואונס כרצון:"],[8,"כולן","אלו שהיו שותפין במלאכה אחת ומשהניחו אבן על הדימוס היא שורת הבנין נפלה והזיקה הואיל ולאו כחו דאדריכל הוא שלאחר שהניחה נפלה וליכא לחיוביה משום גירי דיליה כולן חייבין יחד שכולן שותפין בדבר ועליהן המלאכה לעשות וקיבלו אחריות הנזק יחד:"],[9,"והתניא האחרון חייב","אדריכל שהניחה:"],[9,"בשכירות","האחרון חייב:"],[9,"בקבלנות","כולן חייבין היכא דלא נפלה מיד אחד מהן ועל כולן לשמור שתהא מיושבת יפה:"],[10,"מתני' שתי גנות זו על גב זו","סמוכות זו לזו האחת קרקעיתה גבוה ושאצלה קרקעיתה נמוך:"],[10,"והירק בינתים","בזקיפת הגובה שזו גבוהה מזו יש שומים או בצלים:"],[10,"של עליון","שהרי עפרו הוא ומשלו הוא יונק:"],[10,"של תחתון","שעל אוירו הוא מונח:"],[10,"למלאות גנתו עפר","משוה קרקעו לעליונה:"],[11,"אמר ר\"מ מאחר ששניהן הן יכולין למחות זה על זה","שלא יהא ירק זה כאן עליון ליטול עפרו והתחתון למלאות גנתו:"],[11,"רואין מהיכן ירק זה חי","ממקום שהוא יונק וגדל לו ינתן:"],[11,"כל שעליון יכול לפשוט ידו וליטול הרי אלו שלו","כדאמר ר\"מ הואיל ומעפרו היא חייה:"],[11,"והשאר של תחתון","ועליון הוא גופיה אפקורי מפקר להו לגביה שגנאי הוא לו ליטול רשות ליכנס לתוך של חבירו וללקוט:"],[12,"גמ' בעיקרו","שרשי הירק:"],[12,"בנופו","לפי שהן תלויין באוירו של תחתון פליגי בהו:"]],[[5,"מחוורתא מתני' דלא כר' יהודה","וא\"ת ואמאי לא משני מתני' שלא בשעת הוצאת זבלים ודברי הכל כדמשני בהמניח (ב\"ק דף ל. ושם) אמתני' דהתם וי\"ל דהכא פשיטא ליה דאיירי שלא בשעת הוצאת זבלים ולהכי לא הוה קשיא ליה הא דמתני' מצרכת לזבל לאלתר ור' יהודה מתיר להניח ל' יום אלא להכי לא מצי אתא כר' יהודה משום דמחייב לשלם מה שהזיק אפילו הזיק בההיא שעה קטנה שיש לו רשות להניח ולרבי יהודה אותה שעה כיון שיש לו רשות פטור ועי\"ל דמתניתין משמע דאיירי בשעת הוצאת זבלים מדקתני המזבל מזבל משמע בשעה שרגילין לזבל והא דלא הוה קשה ליה דרבי יהודה שרי שלשים יום ומתני' לאלתר משום דאיכא למימר דמתניתין עצה טובה קמ\"ל שימהר שלא יצטרך לשלם מה שהזיק:"],[13,"ותניא נמי גבי מקח וממכר כה\"ג","תניא גרסינן דאינה משנה בשום מקום ולא הוי כה\"ג ממש דאפילו אמר ר\"י היוצא מן הגזע של בעל הקרקע לא יקשה כלום שהרי עומד באוירו של בעל הקרקע וגם יונק מן הקרקע ועוד שלא היה בדעת המוכר למכור אלא זה האילן שהיה כעין שמכר אבל לא אילן חדש שעתיד לצאת מן הגזע דלא חשיב כאילן עצמו הענפים המתחדשים אלא נחשב כאילן אחר וכן ר' מאיר אם היה אומר כאן של בעל האילן לא היה קשה על משנתנו שכמו שהענפים המתחדשים בכל שנה הם של בעל האילן ה\"נ היוצא מן הגזע יהיו שלו והא דקאמר כה\"ג היינו שמיפה ר\"מ כאן כחו של בעל הקרקע טפי מרבי יהודה כמו במתני' ולהכי לא עביד צריכותא בסמוך אלא אערלה ואמקח וממכר ולא אמתניתין:"]]],[["ותנן נמי גבי ערלה כי האי גוונא אילן היוצא מן הגזע ומן השרשין חייב בערלה דברי רבי מאיר רבי יהודה אומר מן הגזע פטור מן השרשין חייב","וצריכי דאי אשמועינן קמייתא בהא קאמר רבי יהודה משום דממונא אבל גבי ערלה דאיסורא אימא מודי ליה לר' מאיר ואי איתמר בהא בהא קאמר ר' מאיר אבל בההיא אימא מודי ליה לר' יהודה צריכי:","אמר ר\"ש אומר כל שהעליון יכול לפשוט [וכו']: אמרי דבי רבי ינאי ובלבד שלא יאנס","בעי רב ענן ואיתימא רבי ירמיה מגיע לנופו ואין מגיע לעיקרו מגיע לעיקרו ואין מגיע לנופו מאי תיקו:","אמר אפרים ספרא תלמידו של ריש לקיש משום ריש לקיש הלכה כר\"ש אמרוה קמיה דשבור מלכא אמר להו אפריון נמטייה לרבי שמעון:","\u0001הדרן עלך הבית והעלייה וסליקא לה מסכת בבא מציעא\u0002"],[[0,"אילן היוצא מן הגזע וכו'","בלוקח אילן אחד בתוך של חבירו דקי\"ל בבבא בתרא (דף פא.) דדברי הכל לא קנה קרקע ואילן קטן היוצא (מן הגזע או) מן השרשין לית דינא ולית דיינא דקרקע גמורה היא ומן הגזע נמי רבי מאיר סבר שדי נופו בתר עיקרו והתם מפרש מאי גזע ומאי שרשין גזע כל שרואה פני חמה שרשין שאין רואין פני חמה ואע\"ג דשבח נוף העליון לבעל האילן כדקתני התם הגדילו לא ישפה התם הוא דאדעתא דהכי נחת שכל זמן שיהא ראויין לעשות פרי יהא בקרקע וישא ענף ופירי אבל אילן אחר העולה מן הגזע אילנא אחרינא הוא:"],[0,"חייב בערלה","גרסי' לר\"מ דאילן הוא לעצמו דגזע הסמוך לקרקע בתוך שלשה כקרקע הוא ואף על גב דלא מארעא ממש יניק שדי נופו בתר עיקרו:"],[3,"מגיע לעיקרו ואינו מגיע לנופו","כגון שנוטה נופו למטה:"],[4,"קמיה דשבור מלכא","לי נראה שבור מלכא ממש ומלך פרס היה ובקי בדינים ואמרוה להא דר\"ש דמתני' קמיה וקלסה ואמר אפריון נמטייה לר\"ש יקבל חן מאתנו על דבר זה ואית דאמרי שבור מלכא שמואל דבכמה דוכתי קרי ליה הכי ואין מיושב בה דמאי אמרוה אי להא דר\"ש דמתני' אטו שמואל לא הוה ידע לה למתני' ואי להא דאפרים ספרא אטו אי לא אמר ריש לקיש הלכה כר\"ש שמואל מי לא קים בדיני למיקלסיה לר\"ש עד דשמע משמיה דריש לקיש דהלכתא כוותיה:"],[4,"אפריון","חן שלנו:"]],[[4,"שבור מלכא","נראה לפרש כפי' הקונטרס דשבור מלכא היה בקי בהלכות כדאמרינן בסוף מסכת ע\"ז (דף עו:) שנעץ הסכין עשר פעמים בקרקע קשה כשחתך האתרוג בסכין לרב יהודה:"]]]]};
